\label{def:function space}
The function space $X$ is defined to be the family of functions $f \in L^3_\mathrm{loc}([0,\infty);L^3(\mathbb{T}^3))$ which satisfy, with $\rho := \int_\mathbb{T} f \, \mathrm{d}  \theta$, the following: 
    \begin{itemize}
        \item[(i)] $f \geq 0$ a.e.~$(0,\infty)\times\mathbb{T}^3$; 
        \item[(ii)] $\partial_\theta \sqrt{f} \in L^2_\mathrm{loc}([0,\infty);L^2(\mathbb{T}^3))$ and $\partial_t f \in L^{\nicefrac{6}{5}}_\mathrm{loc}([0,\infty);W^{-1,\nicefrac{6}{5}}(\mathbb{T}^3))$; 
        \item[(iii)] $0 \leq \rho \leq 1$ a.e.~$(0,\!\infty)\times\mathbb{T}^2$, $\partial_t \rho \in L^2_\mathrm{loc}(0,\!\infty;H^{-1}(\mathbb{T}^2))$, $\nabla\sqrt{1\!-\!\rho} \in L^2_\mathrm{loc}(0,\!\infty;L^2(\mathbb{T}^2))$; 
        \item[(iv)] $\sqrt{1\!-\!\rho}\nabla\sqrt{f} \in L^2_\mathrm{loc}([0,\infty);L^2(\mathbb{T}^3))$. 
    \end{itemize}

\label{def:weak sol}
      We say that $f \in X $ is a \emph{weak solution} of \eqref{eq:main eqn} if, for all $\varphi \in \mathscr{A}$, it holds: for a.e.~$t_1,t_2 \in (0,\infty)$ 
  \begin{equation}\label{eq:weak sol}
    \begin{aligned}
     \int_{t_1}^{t_2}\! & \int_{\mathbb{T}^3} f \partial_t \varphi \, \mathrm{d}  \xi \, \mathrm{d}  t + \int_{t_1}^{t_2} \int_{\mathbb{T}^3} (1-\rho) f {\bf e}(\theta) \cdot \nabla \varphi \, \mathrm{d}  \xi \, \mathrm{d}  t \\ 
      =&\int_{t_1}^{t_2} \!\int_{\mathbb{T}^3} \!\Big( \big((1-\rho)\nabla f \!+\! f \nabla \rho \big) \!\cdot\! \nabla \varphi \!+\! \partial_\theta f\partial_\theta \varphi \Big) \, \mathrm{d}  \xi \, \mathrm{d}  t \!+\! \int_{\mathbb{T}^3} f \varphi \big|_{t_2} \, \mathrm{d} \xi \!\!-\!\! \int_{\mathbb{T}^3} f \varphi \big|_{t_1} \, \mathrm{d} \xi. 
    \end{aligned}
\end{equation}
    Furthermore, we say that $f$ is a weak solution \emph{with initial data $f_0$} if it is a weak solution, and \eqref{eq:weak sol} holds with $t_1=0$ and the final integral replaced by $\int_{\mathbb{T}^3} f_0(\xi) \varphi(0,\xi) \, \mathrm{d}  \xi$.

\label{rem:global exist}
Recall that, given initial data $f_0$ which satisfies 
\begin{equation}\label{eq:initial data conditions}
   0 \leq f_0 \in L^q(\mathbb{T}^3) \quad \text{for some } q \in (1,\infty], \qquad 0 \leq \rho_0 \leq 1 \quad \text{a.e.~in } \mathbb{T}^2, 
\end{equation}
then there exists a  weak solution of \eqref{eq:main eqn} with initial data $f_0$ (in the precise sense of Definition \ref{def:weak sol}), which satisfies 
\begin{equation}\label{eq:convergence to initial data old}
    \lim_{t\to 0^+} \Vert f(t) - f_0 \Vert_{W^{-1,\nicefrac{6}{5}}(\mathbb{T}^3)} = 0; 
\end{equation}
this was proved in \cite[Theorem 1]{Martin}. Throughout the manuscript, we say that $f_0$ is \emph{admissible initial data} if it satisfies \eqref{eq:initial data conditions}, and whenever initial data $f_0$ is mentioned, the letter $\rho_0$ always denotes $\rho_0 = \int_\mathbb{T} f_0 \, \mathrm{d}  \theta$, \textit{i.e.}~the initial data for $\rho$.

\label{rem:attainment old}
Let $f$ be a weak solution with initial data $f_0$ as per Definition \ref{def:weak sol}. Then, for all $\varphi \in W^{1,6}(\mathbb{T}^3)$ depending only on $\xi$, it holds a.e.~$t>0$
  \begin{equation}\label{eq:to see clearly conservation of initial mass}
    \begin{aligned}
    \int_{\mathbb{T}^3} \! \big( f(t,\xi) - f_0(\xi) \big) \varphi(\xi)   \, \mathrm{d} \xi =&\, \int_{0}^{t} \int_{\mathbb{T}^3} (1-\rho) f {\bf e}(\theta) \cdot \nabla \varphi \, \mathrm{d}  \xi \, \mathrm{d}  s \\ 
    &- \!\int_{0}^{t} \!\!\int_{\mathbb{T}^3} \!\!\Big( \big((1-\rho)\nabla f \!+\! f \nabla \rho \big) \!\cdot\! \nabla \varphi \!+\! \partial_\theta f\partial_\theta \varphi \Big) \, \mathrm{d}  \xi \, \mathrm{d}  s. 
    \end{aligned}
\end{equation}
The boundedness of the relevant terms from Definition \ref{def:weak sol} (\textit{cf.~}\cite[Eq.~(1.5)]{Martin}) yields \eqref{eq:convergence to initial data old}: 
\begin{equation}\label{eq:as per remark attainment old}
\lim_{t \to 0^+} \Vert f(t) - f_0 \Vert_{(W^{1,6}(\mathbb{T}^3))'} = \lim_{t \to 0^+} \sup_{ \Vert \varphi \Vert_{W^{1,6}} \leq 1} \bigg| \int_{\mathbb{T}^3} \big(f(t)-f_0 \big) \varphi  \, \mathrm{d}  \xi \bigg| = 0 .
\end{equation}

\label{rem:convergence initial data rho}
  Suppose that $f$ is a weak solution of \eqref{eq:main eqn} with admissible initial data $f_0$. Then, it holds 
  \begin{equation}\label{eq:conv rho to initial data}
\lim_{t\to 0^+} \Vert \rho(t) - \rho_0 \Vert_{L^2(\mathbb{T}^2)}=0. 
\end{equation}
Note that $\rho \in C([0,\infty);L^2(\mathbb{T}^2))$ is immediate from $\partial_t \rho \in L^2_\mathrm{loc}([0,\infty);H^{-1}(\mathbb{T}^2)) , \rho \in L^2_\mathrm{loc}([0,\infty);H^1(\mathbb{T}^2))$ and the Lions--Magenes Lemma \cite[Ch.3, \S 1.4
Lem.1.2]{Temam}, but this \emph{does not directly imply} \eqref{eq:conv rho to initial data}. Nevertheless, this convergence is true, \textit{cf.}~Appendix \ref{sec:appendix rho initial data}.

\label{lem:dibenedetto classic}
    Let $d \in \mathbb{N}$, $\Omega \subset \mathbb{R}^d$ have piecewise smooth boundary, $I \subseteq [0,\infty)$ any bounded interval, and $p,m \geq 1$. Then, there exists a positive constant $C=C(d,p,m,\partial\Omega,\Omega)$, independent of $I$, such that, for all $v \in L^\infty(I;L^m(\Omega)) \cap L^p(I;W^{1,p}(\Omega))$, 
    \begin{equation*}
        \Vert v \Vert_{L^q(I\times\Omega)} \leq C(1+|I|)^{\frac{1}{q}} \Big( \Vert v \Vert_{L^\infty(I;L^m(\Omega))} + \Vert v \Vert_{L^p(I;W^{1,p}(\Omega))} \Big) \qquad \text{with } q = p(1+\frac{m}{d}). 
    \end{equation*}
    Consequently, we have, for any bounded interval $I\subseteq [0,\infty)$, the continuous embeddings 
    \begin{equation*}
       \begin{aligned} 
       &L^\infty(I; L^2(\mathbb{T}^2)) \cap L^2(I;H^1(\mathbb{T}^2)) \hookrightarrow L^4(I\times\mathbb{T}^2) , \\
       &L^\infty(I;L^2(\mathbb{T}^3)) \cap L^2(I;H^1(\mathbb{T}^3)) \hookrightarrow L^{\nicefrac{10}{3}}(I\times\mathbb{T}^3). 
       \end{aligned}
    \end{equation*}

\label{lem:Lp schauder}
    Let $I \subseteq [0,\infty)$ be any compact interval, $p \in [2,\infty)$, $\alpha \in (0,1)$, $c > 1$, $d\in\mathbb{N}$. Assume $A \in [C^{\alpha}(I\times\mathbb{T}^d)]^{d \times d}$ is symmetric and \begin{equation*}
    c^{-1} |w|^2 \leq A(t,x)w \cdot w \leq c|w|^2 \qquad \forall w \in \mathbb{R}^d, \quad \forall (t,x) \in I\times\mathbb{T}^d.
    \end{equation*}
    Suppose that $v \in L^2(I;H^2(\mathbb{T}^d))$, with $\partial_t v \in L^2(I\!\times\! \mathbb{T}^d)$, satisfies, for $F \in L^p(I\times\mathbb{T}^d)$,  
    \begin{equation*}
        \partial_t v - A:\nabla^2 v = F. 
    \end{equation*}
Then, for any $I' \subset\subset I$ compactly contained in $I$, it holds $\partial_t v , \nabla^2 v \in L^p(I' \times \mathbb{T}^d)$, and 
\begin{equation}\label{eq:schauder Lp}
    \Vert \partial_t v \Vert_{L^p(I'\times\mathbb{T}^d)} + \Vert \nabla^2_\xi v \Vert_{L^p(I'\times\mathbb{T}^d)} \leq C \Big(  \Vert F \Vert_{L^p(I\times\mathbb{T}^d)} + \Vert v \Vert_{L^2(I\times\mathbb{T}^d)} \Big), 
\end{equation}
where $C$ depends only on $|I\setminus I'|,I,c,\Vert A \Vert_{C^{\alpha}},\alpha,d$.

\label{lem:Schauder Holder}
    Let $I \subseteq [0,\infty)$ be any compact interval, $\alpha \in (0,1)$, $c > 1$, and $d\in\mathbb{N}$. Assume the matrix $A \in [C^{\alpha}(I\times\mathbb{T}^d)]^{d \times d}$ is symmetric and  \begin{equation*}
    c^{-1} |w|^2 \leq A(t,x)w \cdot w \leq c|w|^2 \qquad \forall w \in \mathbb{R}^d, \quad \forall (t,x) \in I\times\mathbb{T}^d.
    \end{equation*}
    Suppose that $v \in L^2(I;H^2(\mathbb{T}^d))$, with $\partial_t v \in L^2(I\!\times\! \mathbb{T}^d)$, satisfies, for $F \in C^{\nicefrac{\alpha}{2},\alpha}(I\times\mathbb{T}^d)$, 
    \begin{equation*}
        \partial_t v - A:\nabla^2 v = F. 
    \end{equation*}
Then, for any $I' \subset\subset I$ compactly contained in $I$, it holds $v \in C^{1+\nicefrac{\alpha}{2},2+\alpha}(I' \times \mathbb{T}^d)$, and 
\begin{equation}\label{eq:est schauder holder}
    \Vert v \Vert_{C^{1+\nicefrac{\alpha}{2},2+\alpha}(I'\times\mathbb{T}^d)} \leq C \Big( \Vert F \Vert_{C^{\nicefrac{\alpha}{2},\alpha}(I\times\mathbb{T}^d)} + \Vert v \Vert_{L^2(I\times\mathbb{T}^d)} \Big), 
\end{equation} 
where $C$ depends only on $|I\setminus I'|,I,c,\Vert A \Vert_{C^{\alpha}},\alpha,d$.

\label{lem:Gehring}
    Let $I\subseteq [0,\infty)$ be any compact interval, $c>1$, $N,d \in \mathbb{N}$, and suppose $g,G$ are vector fields satisfying 
    \begin{equation*}
        g \in [L^{p_*}(I\times\mathbb{T}^d)]^{N}, \qquad G \in [L^p(I\times\mathbb{T}^d)]^{N\times d} 
    \end{equation*}
    for some $p>2$. Assume the tensor $A \in [L^\infty(I\times\mathbb{T}^d)]^{N^2 d^2}$ satisfies the ellipticity condition 
    \begin{equation*}
         c^{-1} |w|^2 \leq \!\!\! \underbrace{A(t,x)w \cdot w}_{ \sum_{\alpha,\beta,i,j} A(t,x)^{\alpha\beta}_{ij} w_i^\alpha w_j^\beta } \!\!\! \leq c|w|^2 \qquad \forall w \in \mathbb{R}^{d \times N}, \quad \forall (t,x) \in I\times\mathbb{T}^d,
    \end{equation*}
    and suppose that $v \in [L^\infty(I\times\mathbb{T}^d) \cap L^2(I;H^1(\mathbb{T}^d))]^N$, with $\partial_t v \in [L^2(I;H^{-1}(\mathbb{T}^d))]^N$, satisfies the linear \emph{divergence form} equation 
    \begin{equation*}
        \partial_t v - \operatorname{div}(A \nabla v) = g + \operatorname{div} G. 
    \end{equation*}
Then, there exists $\delta>0$ depending only on $c,I,p,d,\Vert A \Vert_{L^\infty},$ such that, for any $I' \subset\subset I$ compactly contained in $I$, it holds $ \nabla v \in L^{2+\delta}(I' \times \mathbb{T}^d)$.

\label{thm:reg}
Let $f$ be a weak solution of \eqref{eq:main eqn} with admissible initial data $f_0$ satisfying \eqref{eq:initial data conditions}. Then, there exists a constant $C > 1$ $($independent of $t,T$, the initial data, and the solution$)$ such that 
   \begin{equation}\label{eq:infinite speed of propagation in thm statement}
       \operatorname*{ess \, inf}\limits_{(t,T)\times\mathbb{T}^2}(1\!-\!\rho) \geq  C^{-1} \Vert 1\!-\!\rho_0 \Vert_{L^1(\mathbb{T}^2)} e^{-C( T + t^{-10} )} 
   \end{equation}
for all $0<t<T<\infty$. Moreover, if $\Vert 1-\rho_0\Vert_{L^1(\mathbb{T}^2)}>0$, then $f \in C^\infty((0,\infty)\!\times\!\mathbb{T}^3)$.

\label{lem:bombieri giusti}
 Let $\beta>0$, $\tilde r \in (0,1]$, and $\{\mathcal{Q}_r\}_{r \in (0,\tilde r]}$ be a family of nested subsets of $\mathbb{R}^{d+1}$ with $\mathcal{Q}_{r} \subset \mathcal{Q}_R$ for all $0<r<R\leq \tilde r$ and $|\mathcal{Q}_1|<\infty$. Assume that $\varphi \in L^1(\mathcal{Q}_1)$ is non-negative  and satisfies$:$
    \begin{enumerate}
        \item[(i)] there exists a positive constant $C_0$ independent of $\beta,r,R,\tilde r,p$ such that 
    \begin{equation}\label{eq:first est adapt bombieri giusti}
       \Vert \varphi \Vert_{L^\infty(\mathcal{Q}_r)} \leq \left(\frac{C_0 }{(R-r)^\beta}\right)^{\frac{1}{p}} \Vert \varphi \Vert_{L^p(\mathcal{Q}_R)} \quad \text{for all } 0 < r < R \leq \tilde r \text{ and all } p \in (0,1); 
    \end{equation}
        \item[(ii)] there exists a positive constant $C_1 >  e^{-1}$ such that, for all $r \in (0,\tilde r)$, 
    \begin{equation}\label{eq:assump bombieri giusti on log set}
        \big| \{ (t,y) \in \mathcal{Q}_r : \, \log \varphi(t,y) > s \} \big| \leq \frac{C_1}{s} \qquad \text{for all } s > 0. 
    \end{equation}
    \end{enumerate}
      Then, there exists a positive constant $C_2 = C_2(C_0,C_1,\beta)$, independent of $r,\tilde r$, such that 
    \begin{equation}\label{eq:bombieri giusti final bound i}
        \Vert \varphi \Vert_{L^\infty(\mathcal{Q}_r)} \leq \exp \big( C_2 (\tilde r -r)^{-2\beta} \big) \qquad \text{for all } r \in (0,\tilde r). 
    \end{equation}

Define the increasing function $     r \mapsto   \Phi(r) := \operatorname*{ess \, sup}_{\mathcal{Q}_r} \log \varphi$. This function is well-defined since $\varphi$ is non-negative; however, \emph{a priori} it may be infinite. We will prove that the assumptions of the lemma imply that, for any $r \in (0,\tilde r)$, either: 
    \begin{itemize}
        \item[(a)] $\Phi(r) \leq 2 C_1$, in which case there is nothing to prove and we set $C_2 = 2C_1$; 
        \item[(b)] or, $\Phi(r) > 2 C_1$, in which case it holds 
        \begin{equation}\label{eq:iterate bombieri giusti}
            \Phi(r) \leq \frac{3}{4} \Phi(R) + \frac{C}{(R-r)^{2\beta}} \qquad \forall R \in (r,\tilde r], 
        \end{equation}
        where the positive constant $C=C(C_0,C_1)$ is independent of $r,R,\tilde{r}$. 
    \end{itemize}
    The rest of the proof is divided into two steps. 


    \smallskip 

    \noindent 1. \textit{Proof of \eqref{eq:bombieri giusti final bound i} in case (b)}. We prove the result \eqref{eq:bombieri giusti final bound i} in the case where (b) holds. Suppose that case (b) holds at a given $r \in (0,\tilde r)$. Define the increasing sequence of radii $\{r_n\}_{n \geq 0}$:
\begin{equation*}
    r_n = \tilde r - \frac{\tilde r-r}{1+n} \qquad \forall n \in \mathbb{N} \cup \{0\} \implies r_{n+1} - r_n = \frac{\tilde r-r}{(n+2)(n+1)}, 
\end{equation*}
whence $r = r_0 < r_1 < \dots < r_n \nearrow \tilde r$. Note that, if there exists $n\in\mathbb{N}$ such that $\Phi(r_n) \leq 2C_1$, then since $\Phi$ is increasing, we get $\Phi(r)=\Phi(r_0) \leq \Phi(r_n) \leq 2C_1$, and we are back to case (a), where there is nothing to prove. Thus, henceforth we assume $\Phi(r_n) > 2C_1$ for all $n\in\mathbb{N}$, whence \eqref{eq:iterate bombieri giusti} holds with $r=r_n$, $R=r_{n+1}$ ($n\in\mathbb{N}_{\geq 0}$). 
By induction on \eqref{eq:iterate bombieri giusti}, 
    \begin{equation}\label{eq:induction on the bound bombieri giusti}
    \begin{aligned}
        \Phi(r) = \Phi(r_0) &\leq (\frac{3}{4})^n \Phi(r_n) + C \sum_{j=0}^{n-1} (\frac{3}{4})^{j} \frac{1}{(r_{j+1} - r_j)^{2\beta}}, 
    \end{aligned}
    \end{equation}
    and, using the assumption \eqref{eq:first est adapt bombieri giusti} with $R=\tilde r$, the first term on the right-hand side decays: 
      \begin{equation*}
  \begin{aligned}
      (\frac{3}{4})^n  \Phi(r_n) =  (\frac{3}{4})^n \log\Vert \varphi \Vert_{L^\infty(\mathcal{Q}_{r_n})} &\leq (\frac{3}{4})^n \log\left( \left(\frac{C_0 }{(\tilde r-r_n)^\beta}\right)^{\frac{1}{p}} \Vert \varphi \Vert_{L^p(\mathcal{Q}_1)} \right) \\ 
      &=  (\frac{3}{4})^n \big( \frac{1}{p} \log C_0 +  \log\Vert \varphi \Vert_{L^p(\mathcal{Q}_1)}  \big) + \frac{\beta}{p}(\frac{3}{4})^n \log (\frac{1+n}{\tilde r-r}) , 
  \end{aligned}
    \end{equation*}
so $ (\frac{3}{4})^n  \Phi(r_n) \to 0$,  for any fixed $p \in (0,1)$; note that $\Vert \varphi \Vert_{L^p(\mathcal{Q}_1)} \leq |\mathcal{Q}_1|^{\nicefrac{1}{p}-1}\Vert \varphi \Vert_{L^1(\mathcal{Q}_1)} < \infty$ for $p \in (0,1)$ by H\"older's inequality. By letting $n\to \infty$ in \eqref{eq:induction on the bound bombieri giusti}, we recover 
       \begin{equation*}
     \Phi(r) \leq   C \sum_{j=0}^{\infty} (\frac{3}{4})^j \frac{1}{(r_{j+1} - r_j)^{2\beta}} = \underbrace{C\bigg(   \sum_{j=0}^{\infty} (\frac{3}{4})^{j} (j+2)^{2\beta}(j+1)^{2\beta} \bigg)}_{=:C'} (\tilde r-r)^{-2\beta}, 
    \end{equation*}
where $C'$ is independent of $r,\tilde{r}$; note that the infinite sum manifestly converges for all $\beta > 0$ by the d'Alembert ratio test. It then follows (recalling the non-negativity of $\varphi$) that 
\begin{equation*}
    \Vert \varphi \Vert_{L^\infty(\mathcal{Q}_r)} = \operatorname*{ess \, sup}_{\mathcal{Q}_r} \exp \log \varphi = e^{\Phi(r)} \leq e^{C' (\tilde r-r)^{-2\beta}}. 
\end{equation*}
We set $C_2 = C'$, which depends only on $C_0,C_1,\beta$, and the proof of \eqref{eq:bombieri giusti final bound i} is complete.    



\smallskip 

\noindent 2.i. \textit{Proof of \eqref{eq:iterate bombieri giusti}$:$ $L^p$ estimate for the logarithm}. Our goal in this step is to obtain (for $\varphi$ the function in the statement of Lemma \ref{lem:bombieri giusti} with $r \in (0,\tilde r)$ and $\Phi(r)$ satisfying case (b) at the beginning of the proof) the following estimate: 
 \begin{equation}\label{eq:tricky bombieri giusti ii}
        \begin{aligned}
           \Vert \varphi \Vert^{p_R}_{L^{p_R}(\mathcal{Q}_R)} \leq C_3 e^{\frac{1}{2}p_R\Phi(R)} \qquad \forall R \in (r,\tilde r], 
        \end{aligned}
    \end{equation}
where the positive constant $C_3$ is independent of $p_R,\beta,r,\tilde r,R$, and $p_R $ is prescribed by 
\begin{equation}\label{eq:choice of p bombieri giusti}
    p_R = \frac{2}{\Phi(R)}\log \frac{\Phi(R)}{2C_1}. 
\end{equation}
Note that $p_R \in (0,1)$ since the assumption $\Phi(r) > 2C_1$ with $C_1 > e^{-1}$ implies $\Phi(R) \geq \Phi(r) > 2C_1$ since $\Phi$ is increasing, and (since $\sup_{s \in (1,\infty)} s^{-1}\log s = e^{-1}$) 
\begin{equation}\label{eq:p of r is less than one}
   0 < \frac{2}{\Phi(R)}\log \frac{\Phi(R)}{2C_1} = \frac{1}{C_1} \frac{2C_1}{\Phi(R)}\log \frac{\Phi(R)}{2C_1} < e \sup_{s \in (1,\infty)} s^{-1}\log s = 1, 
\end{equation}
Define $
    A_R := \{(t,y) \in \mathcal{Q}_R : \, \log \varphi(t,y) > \frac{1}{2}\Phi(R)\} $ and $ B_R := \{(t,y) \in \mathcal{Q}_R : \, \log \varphi(t,y) \leq \frac{1}{2}\Phi(R) \}$. For all $p > 0$, it holds $\operatorname*{ess \, sup}_{\mathcal{Q}_R} \varphi^p =  \operatorname*{ess \, sup}_{\mathcal{Q}_R} \exp(p \log \varphi )  = e^{p \Phi(R)}$, whence 
    \begin{equation}\label{eq:tricky bombieri giusti}
        \begin{aligned}
           \Vert \varphi \Vert^p_{L^p(\mathcal{Q}_R)} \!=\!  \iint_{A_R}\!\!\!\varphi^p  \!+\! \iint_{B_R} \!\!\!\varphi^p   \!\leq\! |A_R| e^{p \Phi(R)} \!+\! |B_R| e^{ \frac{p}{2}\Phi(R)} \!\leq\! \frac{2 C_1}{\Phi(R)}e^{p \Phi(R)} \!+\! |\mathcal{Q}_1| e^{\frac{p}{2}\Phi(R)}, 
        \end{aligned}
    \end{equation}
where we used \eqref{eq:assump bombieri giusti on log set} for the first term, and bluntly bounded $|B_R| \leq |\mathcal{Q}_R| \leq |\mathcal{Q}_1|$. We emphasise that the above estimate holds for all possible choices of $p > 0$ and $R \in (r,\tilde r]$; including if we choose $p$ to depend on $R$ as per \eqref{eq:choice of p bombieri giusti}. Next, we estimate the first term on the right-hand side of \eqref{eq:tricky bombieri giusti} by the final term. Setting $p=p_R$ as per \eqref{eq:choice of p bombieri giusti}, we get 
\begin{equation*}
    \frac{2 C_1}{\Phi(R)}e^{p_R \Phi(R)} = e^{\frac{p_R}{2} \Phi(R)}, 
\end{equation*}
and we deduce from \eqref{eq:tricky bombieri giusti} that, defining the positive constant $C_3=1+|\mathcal{Q}_1|$ independent of $p,d,\beta,r,R,\tilde r$, there holds \eqref{eq:tricky bombieri giusti ii} with $p_R$ prescribed by \eqref{eq:choice of p bombieri giusti}. 



\smallskip 

\noindent 2.ii. \textit{Proof of \eqref{eq:iterate bombieri giusti}$:$ estimate on $\Phi(r)$}. Using \eqref{eq:first est adapt bombieri giusti} with the choice $p=p_R \in (0,1)$ and 
\eqref{eq:tricky bombieri giusti ii}, the monotonicity of $\log$ implies, since $ \Phi(r) = \frac{1}{p_R} \log (\Vert \varphi \Vert_{L^\infty(\mathcal{Q}_r)}^{p_R} )$, 
\begin{equation}\label{eq:almost there bombieri giusti}
    \begin{aligned}
        \Phi(r) \leq \frac{1}{p_R}\log \bigg( \frac{C_0}{(R-r)^\beta} C_3 e^{\frac{1}{2}p_R\Phi(R)} \bigg) &\leq \frac{1}{2}\Phi(R) + \frac{1}{p_R} \log \Big( \frac{C_0 C_3}{(R-r)^\beta} \Big) \\ 
        &= \frac{1}{2}\Phi(R) \bigg( 1 + \frac{\log \big( \frac{C_0 C_3}{(R-r)^\beta} \big)}{\log \big(\frac{\Phi(R)}{2C_1}\big)}\bigg), 
    \end{aligned}
\end{equation}
where we used the explicit representation \eqref{eq:choice of p bombieri giusti} for $p_R$ to obtain the final line. We divide the analysis into two cases. The first case is when it holds: ${\log ( \frac{C_0 C_3}{(R-r)^\beta} )}/{\log (\frac{\Phi(R)}{2C_1})} \leq \frac{1}{2}$, 
in which case we deduce from \eqref{eq:almost there bombieri giusti} that it holds $\Phi(r) \leq \frac{3}{4}\Phi(R)$, and hence \eqref{eq:iterate bombieri giusti} is satisfied. On the other hand, if instead it holds ${\log ( \frac{C_0 C_3}{(R-r)^\beta} )}/{\log (\frac{\Phi(R)}{2C_1})} > \frac{1}{2}$, then (using again $\Phi(R) \geq \Phi(r) > 2C_1$) we deduce $\Phi(r) \leq \Phi(R) < \frac{2 C_1 C_0^2 C_3^2}{(R-r)^{2\beta}}$, where we used that $\Phi$ is an increasing function of the radius to write the first inequality. In either case, \eqref{eq:iterate bombieri giusti} holds with $C(C_0,C_1)=2C_1 C_0^2 (1+|\mathcal{Q}_1|)^2$ using the definition of $C_3$. The proof is complete.

\label{lem:moser 1/u}
    Let $u$ be a weak solution of \eqref{eq:u eq} satisfying \eqref{eq:initial upgrade dt rho}, $\varepsilon,p \in (0,1)$, $0 < r < R \leq 1$. There exists a constant $C$ independent of $p,r,R,\varepsilon$ such that 
    \begin{equation}\label{eq:est on 1/u for future times}
   \begin{aligned}
     \Vert (u+\varepsilon)^{-1} \Vert_{L^{\infty}(Q_r^-)} \leq \left(\frac{C }{(R-r)^2} \right)^{\frac{1}{p}}\Vert (u+\varepsilon)^{-1} \Vert_{L^{p}(Q_R^-)}.
   \end{aligned} 
\end{equation}

The proof is divided into three steps. 

\smallskip 

\noindent 1. \textit{Caccioppoli-type inequality}. Let $q > 0$ and, for all $\varepsilon \in (0,1)$, define $   w_\varepsilon := (u+\varepsilon)^{-\nicefrac{q}{2}}. $ Let $0<r < R \leq 1$. Our objective in this step is to show  (for $C$ independent of $q,r,R,\varepsilon$): 
\begin{equation}\label{eq:first checkpoint moser}
   \begin{aligned}
     \operatorname*{ess \, sup}_{s \in (-r,0)}\Vert w_\varepsilon(s) \Vert_{L^2(\mathbb{T}^2)}^2 \!+\! \int^{0}_{-r}  \Vert \nabla w_\varepsilon(s)\Vert_{L^2(\mathbb{T}^2)}^2 \, \mathrm{d}  s \leq \frac{C(1+q^2)}{R\!-\!r}   \int_{-R}^0 \Vert w_\varepsilon(s ) \Vert_{L^2(\mathbb{T}^2)}^2 \, \mathrm{d}  s.
   \end{aligned} 
\end{equation}
To this end, let $\psi \in C^\infty_c((-R,0])$   be such that 
\begin{equation}\label{eq:test function time psi}
    0 \leq \psi \leq 1 \text{ on } [-1,0], \quad \psi|_{[-1,-R]} = 0 , \quad \psi|_{[-r,0]} = 1,  \quad \Vert \partial_t \psi \Vert_{L^\infty((0,1))} \leq \frac{C}{R-r},
    \end{equation}
    for some $C$ independent of $r,R$; $\psi$ is only a function of $t$. Recalling the discussion that follows \eqref{eq:u eq} and \eqref{eq:initial upgrade dt rho}, we have $w_\varepsilon \in L^\infty((-1,1)\times\mathbb{T}^2) \cap L^2((-1,1);H^1(\mathbb{T}^2))$; furthermore, $$\phi := -q (u+\varepsilon)^{-q-1} \psi^2 = -q w_\varepsilon^{2+\frac{2}{q}} \psi^2$$ also belongs to this space, whence it is an admissible test function. We therefore insert $\phi$ as a test function into the weak formulation of \eqref{eq:u eq} and get 
\begin{equation*}
   \begin{aligned}
       \langle \partial_t u , \phi \rangle = -q\langle \partial_t (w_\varepsilon^{-\frac{2}{q}}) , w^{2+\frac{2}{q}}_\varepsilon \psi^2 \rangle = 2 \langle w_\varepsilon \partial_t w_\varepsilon , \psi^2 \rangle = \frac{\mathrm{d}}{\mathrm{d} t} \int_{\mathbb{T}^2} |\psi w_\varepsilon|^2 \, \mathrm{d}  x - 2 \int_{\mathbb{T}^2} \psi \partial_t \psi w^2_\varepsilon \, \mathrm{d}  x, 
   \end{aligned} 
\end{equation*}
where we used \eqref{eq:initial upgrade dt rho} to justify the Sobolev chain rule (\textit{cf.}~\cite[\S 5.10]{Evans}); we emphasise that we are \emph{not} using the Lions--Magenes Lemma here. Similarly, it holds 
\begin{equation*}
   \begin{aligned}
        - \langle \operatorname{div}({\bf p} u) , \phi \rangle &= -2(q\!+\!1)\! \int_{\mathbb{T}^2} \psi^2 {\bf p} (w_\varepsilon^{-\frac{2}{q}} \!-\! \varepsilon) \! \cdot\! w^{1+\frac{2}{q}}_\varepsilon \nabla w_\varepsilon \, \mathrm{d}  x \\ &= -2(q\!+\!1) \! \int_{\mathbb{T}^2} \psi^2 w_\varepsilon {\bf p}  \! \cdot\! \nabla w_\varepsilon \, \mathrm{d}  x + 2(q\!+\!1) \varepsilon \! \int_{\mathbb{T}^2} \psi^2 w^{1+\frac{2}{q}}_\varepsilon {\bf p} \cdot\! \nabla w_\varepsilon \, \mathrm{d}  x, 
   \end{aligned}
\end{equation*}
and $\langle \Delta u , \phi \rangle = q\int_{\mathbb{T}^2} \psi^2 \nabla (w_\varepsilon^{-\frac{2}{q}}) \!\cdot\! \nabla (w^{2+\frac{2}{q}}_\varepsilon) \, \mathrm{d}  x = -\frac{4}{q}(q+1) \int_{\mathbb{T}^2} |\nabla(\psi w_\varepsilon)|^2 \, \mathrm{d}  x.$ Observe that 
\begin{equation*}
    \bigg|   \varepsilon\! \int_{\mathbb{T}^2}  \psi^2 w^{1+\frac{2}{q}}_\varepsilon   {\bf p} \cdot\! \nabla w_\varepsilon \, \mathrm{d}  x \bigg| \leq   \varepsilon\! \int_{\mathbb{T}^2}  \underbrace{w^{\frac{2}{q}}_\varepsilon}_{\leq \varepsilon^{-1}}  \psi w_\varepsilon |\nabla (\psi w_\varepsilon) | \, \mathrm{d}  x \leq   \int_{\mathbb{T}^2}  \psi w_\varepsilon |\nabla (\psi w_\varepsilon) | \, \mathrm{d}  x,
\end{equation*}
where we also used $|{\bf p}|\leq 1$ by \eqref{eq:polarisation bound}, hence, using also Young's inequality, we obtain 
\begin{equation*}
   \begin{aligned}
      \frac{\mathrm{d}}{\mathrm{d} t} \Vert \psi  w_\varepsilon & \Vert_{L^2(\mathbb{T}^2)}^2 \!+\! 4(1\!+\! q^{-1}) \Vert\nabla(\psi w_\varepsilon)\Vert_{L^2(\mathbb{T}^2)}^2 \leq 4(q\!+\!1) \!\int \!\! \psi w_\varepsilon |\nabla (\psi w_\varepsilon)| \, \mathrm{d}  x \!+\! 2\! \int\!\! \psi |\partial_t \psi| w^2_\varepsilon \, \mathrm{d}  x \\ 
      &\leq 2q^2 (1+q^{-1})\Vert \psi w_\varepsilon\Vert^2_{L^2(\mathbb{T}^2)} + 2 (1+q^{-1})\Vert\nabla(\psi w_\varepsilon)\Vert_{L^2(\mathbb{T}^2)}^2 + \frac{2C}{R-r} \Vert w_\varepsilon \Vert^2_{L^2(\mathbb{T}^2)}. 
   \end{aligned} 
\end{equation*}
By bounding the first term on the right-hand side bluntly using $0\leq \psi \leq 1$, it follows that 
\begin{equation*}
   \begin{aligned}
      \frac{\mathrm{d}}{\mathrm{d} t} \Vert \psi w_\varepsilon \Vert_{L^2(\mathbb{T}^2)}^2 + (1\!+\! q^{-1}) \Vert\nabla(\psi w_\varepsilon)\Vert_{L^2(\mathbb{T}^2)}^2 \leq C \Big( q^2(1+q^{-1}) +\frac{1}{R-r} \Big) \Vert w_\varepsilon \Vert^2_{L^2(\mathbb{T}^2)}, 
   \end{aligned} 
\end{equation*}
where $C$ is independent of $q,r,R,\varepsilon$.  Integrating in time over $[-R,t]$, for any $t \in (-r,0)$, 
\begin{equation*}
   \begin{aligned}
     \Vert w_\varepsilon(t) \Vert_{L^2(\mathbb{T}^2)}^2 + \int_{-R}^t \int_{\mathbb{T}^2} |\nabla(\psi w_\varepsilon)|^2 \, \mathrm{d}  x \, \mathrm{d}  s \leq  \frac{C(1+q^2)}{R-r}  \! \int_{-R}^t \Vert w_\varepsilon(s) \Vert_{L^2(\mathbb{T}^2)}^2 \, \mathrm{d}  s, 
   \end{aligned} 
\end{equation*}
where we used that $\psi(t) = 1$ for such $t$ and $\psi(-R)=0$ from \eqref{eq:test function time psi}, $1 \leq 1 +q^{-1}$, and Young's inequality to write $2q \leq 1 + q^2$. Using also the fact that $\psi$ does not depend on $x$ and $\psi \equiv 1$ in $[-r,0]$ to control the second term on the left-hand side of the previous inequality, as well as $0<R-r<1$, we deduce \eqref{eq:first checkpoint moser} as desired. 




\smallskip 

\noindent 2. \textit{Recursive estimate}. Our goal in this step is to obtain (for $C$ independent of $q,r,R,\varepsilon$): 
\begin{equation}\label{eq:second checkpoint moser}
   \begin{aligned}
     \Vert (u+\varepsilon)^{-1} \Vert_{L^{2q}(Q_r^-)} \leq \Big( \frac{C   (1+q^2)}{R\!-\!r} \Big)^{\frac{1}{q}} \Vert (u+\varepsilon)^{-1} \Vert_{L^q(Q_R^-)} , 
   \end{aligned} 
\end{equation}
for all choices of $0<r<R \leq 1$ with $R-r < 1$. 

The standard interpolation inequality of Lemma \ref{lem:dibenedetto classic} implies 
\begin{equation*}
    \begin{aligned}
        \Vert w_\varepsilon \Vert_{L^4(Q_r^-)} \leq C  \Big( \Vert w_\varepsilon \Vert_{L^\infty(-r,0;L^2(\mathbb{T}^2))} + \Vert \nabla w_\varepsilon \Vert_{L^2((-r,0)\times\mathbb{T}^2)}  \Big), 
    \end{aligned}
\end{equation*}
where the positive constant $C$ is independent of $r,R,q,\varepsilon$. By inserting  into \eqref{eq:first checkpoint moser}, we get 
\begin{equation*}
   \begin{aligned}
     \Vert w_\varepsilon \Vert_{L^4(Q_r^-)} \leq C  \Big(\frac{1+q^2}{R\!-\!r} \Big)^{\frac{1}{2}} \Vert w_\varepsilon \Vert_{L^2(Q_R^-)}, 
   \end{aligned} 
\end{equation*}
which is a \emph{reverse H\"older inequality}, and we obtain \eqref{eq:second checkpoint moser} by rewriting the above in terms of $u+\varepsilon$, where the constant $C$ has changed but is still independent of $q,r,R,\varepsilon$. 



\smallskip 

\noindent 3. \textit{Moser's iterations}. As per the statement, let $0 < r < R \leq 1$ be fixed. Define the radii 
\begin{equation}\label{eq:sequence of radii}
r_0 = R, \qquad r_n := R - (R-r) \sum_{k=1}^n 2^{-k}  \qquad \forall n\in\mathbb{N}; 
\end{equation}
note that the sequence is monotonically decreasing, and $r_n \to r$ as $n\to\infty$. Furthermore, 
\begin{equation}\label{eq:spacing between radii}
    r_{n} - r_{n+1} = (R-r) 2^{-n-1}   \qquad \forall n \in \mathbb{N}; 
\end{equation}
note $0< r_{n+1} < r_n \leq 1$ and $0<r_n - r_{n+1} < 1$ for all $n$. Also define the powers $q_n := p 2^n$ for all $n $, where we note $q_0 = p$ and $q_n \to \infty$; where $p \in (0,1)$ is given in the statement. 


By applying the result of \eqref{eq:second checkpoint moser} with $R=r_n$, $r=r_{n+1}$, $q=q_n$, we deduce 
\begin{equation}\label{eq:the first kappa n}
   \begin{aligned}
     \Vert (u\!+\!\varepsilon)^{-1} \Vert_{L^{p 2^{n+1}}(Q_{r_{n+1}}^-)} \leq \underbrace{\Big( \frac{C (1\!+\! p^2 2^{2n}) }{r_{n}\!-\!r_{n+1}} \Big)^{\frac{1}{p 2^{n}}}}_{=:\kappa_n} \Vert (u\!+\!\varepsilon)^{-1} \Vert_{L^{p 2^n}(Q_{r_n}^-)} \quad \forall n \in \mathbb{N}. 
   \end{aligned} 
\end{equation}
Note that, for all $n$ sufficiently small such that $p 2^n \leq 1$, it holds $\kappa_n \leq ( \frac{C 2^{n+2} }{R-r} )^{\frac{1}{p 2^{n}}} = ( \frac{4C }{R-r} )^{\frac{1}{p 2^{n}}}2^{\frac{n}{p 2^n}}, $ while for all $n$ sufficiently large such that $p 2^n \geq 1$, we obtain $\kappa_n \leq ( \frac{C p^2  2^{3n+2} }{R-r} )^{\frac{1}{p 2^{n}}} = ( \frac{4C p^2 }{R-r} )^{\frac{1}{p 2^{n}}}2^{\frac{3n}{p 2^n}}, $ whence, since $p \in (0,1)$, we deduce in either case that 
\begin{equation*}
    \kappa_n \leq \Big( \frac{C}{R-r} \Big)^{\frac{1}{p 2^{n}}}2^{\frac{3n}{p 2^n}} \qquad \forall n \in \mathbb{N}, 
\end{equation*}
where $C$ has changed, but remains independent of $p,r,R,\varepsilon,n$. By iteration on \eqref{eq:the first kappa n}, 
\begin{equation}\label{eq:just before moser}
   \begin{aligned}
     \Vert (u\!+\!\varepsilon)^{-1} \Vert_{L^{p 2^{n}}(Q_{r_n}^-)} \! \leq \! \bigg( \! \underbrace{\prod_{k=0}^{n-1} \Big(\frac{C}{R \! -\! r}\Big)^{\frac{1}{p 2^k}} 2^{\frac{3k}{p 2^k}} }_{=: A_n} \! \bigg) \Vert (u \! + \! \varepsilon)^{-1} \Vert_{L^{p}(Q_R^-)} \qquad \forall n \geq 1. 
   \end{aligned} 
\end{equation}
We study the convergence of the coefficients $A_n$. We have 
\begin{equation*}
   \begin{aligned} \log A_n = \sum_{k=0}^{n-1} \log \bigg[ \Big(\frac{C }{R-r}\Big)^{\frac{1}{p 2^k}}  2^{\frac{3k}{p2^k}} \bigg]  &= \frac{1}{p}\log \Big(\frac{C  }{R-r}\Big) \sum_{k=0}^{n-1} {2^{-k}}  + \frac{3}{p} \log 2 \sum_{k=0}^{n-1} k {2^{-k}} \\ 
   &\longrightarrow \frac{2}{p} \log \Big( \frac{C  }{R-r} \Big) + \frac{1}{p} \log \bar{C}, 
   \end{aligned}
\end{equation*}
where $\bar{C} = 2^{3 \sum_{n \geq 0} n 2^{-n}}$ is independent of $p,r,R,\varepsilon$. It follows that $  A_n \nearrow A = \left(\frac{C }{(R-r)^2}  \right)^{\frac{1}{p}} , $ for some $C$ independent of $p,r,R,\varepsilon$. Passing to the limit $n\to\infty$ in \eqref{eq:just before moser} yields   \eqref{eq:est on 1/u for future times}.

\label{lem:moser u upper}
    Let $u$ be a weak solution of \eqref{eq:u eq} satisfying \eqref{eq:initial upgrade dt rho}, $\varepsilon ,p \in (0,1)$,  $0 < r < R \leq 1$. There exists a  constant $C$ independent of $p,r,R,\varepsilon$ such that 
    \begin{equation}\label{eq:Linfty e on cylinder by moser}
   \begin{aligned}
     \Vert u+\varepsilon \Vert_{L^{\infty}(Q_r)} \leq \left(\frac{C}{(R\!-\!r)^5} \right)^{\frac{1}{p}}\Vert u+\varepsilon \Vert_{L^{p}(Q_R)}. 
   \end{aligned} 
\end{equation}

The proof is divided into several steps. 

\smallskip 

\noindent 1. \textit{Caccioppoli-type inequality}. Define $w_\varepsilon := (u+\varepsilon)^{\nicefrac{q}{2}}$ for $q>0$ such that $q \neq 1$, and 
\begin{equation}\label{eq:delta def in proof of moser upper}
    \delta := \big| 1 - q^{-1} \big|. 
\end{equation}
Our objective in this step is to prove 
\begin{equation}\label{eq:first checkpoint moser bis}
   \begin{aligned}
     \operatorname*{ess \, sup}_{s \in (-r,r)}\Vert w_\varepsilon(s) \Vert_{L^2(\mathbb{T}^2)}^2 \!+\!  \int_{-r}^{r} \!\! \! \Vert \nabla w_\varepsilon(s)\Vert_{L^2(\mathbb{T}^2)}^2 \, \mathrm{d}  s \!\leq\! C \Big(  \frac{1\!+\!q^2\!+\!\delta^{-1} }{R\!-\!r} \Big) \! \int_{-R}^{R} \!\!\! \Vert w_\varepsilon(s) \Vert_{L^2(\mathbb{T}^2)}^2 \, \mathrm{d}  s. 
   \end{aligned} 
\end{equation}


Let $\psi \in C^\infty_c((-R,R))$ be such that 
\begin{equation}\label{eq:test function time psi for moser upper}
    0 \leq \psi \leq 1 , \quad \psi|_{[-r,r]}=1, \quad \psi|_{[-1,1]\setminus[-R,R]}=0, \quad \Vert \partial_t \psi \Vert_{L^\infty((-1,1))} \leq \frac{C}{R-r},
    \end{equation}
    for some constant $C$ independent of $r,R$. As before, $\psi$ is only a function of $t$, and again recalling the discussion that follows \eqref{eq:u eq} and \eqref{eq:initial upgrade dt rho}, 
    $\phi := q (u+\varepsilon)^{q-1} \psi^2 = q w_\varepsilon^{2-\frac{2}{q}} \psi^2$ 
    is an admissible test function. We  insert $\phi$ into the weak formulation of \eqref{eq:u eq} and get 
\begin{equation*}
   \begin{aligned}
       \langle \partial_t u , \phi \rangle = q\langle \partial_t (w_\varepsilon^{\frac{2}{q}}) , w^{2-\frac{2}{q}}_\varepsilon \psi^2 \rangle = 2 \langle w_\varepsilon \partial_t w_\varepsilon , \psi^2 \rangle = \frac{\mathrm{d}}{\mathrm{d} t} \int_{\mathbb{T}^2} |\psi w_\varepsilon|^2 \, \mathrm{d}  x - 2 \int_{\mathbb{T}^2} \psi \partial_t \psi w^2_\varepsilon \, \mathrm{d}  x, 
   \end{aligned} 
\end{equation*}
where we use \eqref{eq:initial upgrade dt rho}, as well as $ - \langle \operatorname{div}({\bf p} u) , \phi \rangle = 2(q\!-\!1)\! \int_{\mathbb{T}^2} \psi^2 {\bf p} (w_\varepsilon^{\frac{2}{q}} \!-\! \varepsilon) \! \cdot\! w^{1-\frac{2}{q}}_\varepsilon \nabla w_\varepsilon \, \mathrm{d}  x ,$
and $\langle \Delta u , \phi \rangle = - q\int_{\mathbb{T}^2} \psi^2 \nabla (w_\varepsilon^{\frac{2}{q}}) \!\cdot\! \nabla (w^{2-\frac{2}{q}}_\varepsilon) \, \mathrm{d}  x = 4(q^{-1}-1) \int_{\mathbb{T}^2} |\nabla(\psi w_\varepsilon)|^2 \, \mathrm{d}  x. $ In turn, we get 
\begin{equation}\label{eq:equality}
   \begin{aligned}
      -\frac{\mathrm{d}}{\mathrm{d} t} & \int_{\mathbb{T}^2} |\psi w_\varepsilon|^2 \, \mathrm{d}  x + 4(q^{-1}-1) \int_{\mathbb{T}^2} |\nabla(\psi w_\varepsilon)|^2 \, \mathrm{d}  x \\ 
      =& 2(q\!-\!1) \!\int_{\mathbb{T}^2}\!\! \psi^2 w_\varepsilon {\bf p}  \! \cdot\! \nabla w_\varepsilon \, \mathrm{d}  x \!-\! 2(q\!-\!1) \varepsilon\! \int_{\mathbb{T}^2}\!\! \psi^2 w^{1-\frac{2}{q}}_\varepsilon   {\bf p} \cdot\! \nabla w_\varepsilon \, \mathrm{d}  x \!-\! 2 \! \int_{\mathbb{T}^2}\!\! \psi \partial_t \psi w^2_\varepsilon \, \mathrm{d}  x; 
   \end{aligned} 
\end{equation}
the second term on the right-hand side is bounded by (using also \eqref{eq:polarisation bound} to control ${\bf p}$)
\begin{equation*}
    \bigg| \varepsilon \int_{\mathbb{T}^2}\! \psi^2 w^{1-\frac{2}{q}}_\varepsilon   {\bf p} \cdot\! \nabla w_\varepsilon \, \mathrm{d}  x \bigg| \leq \varepsilon \int_{\mathbb{T}^2}\! \underbrace{w^{-\frac{2}{q}}_\varepsilon}_{\leq \varepsilon^{-1}} \psi w_\varepsilon  |\nabla (\psi w_\varepsilon)| \, \mathrm{d}  x \leq \int_{\mathbb{T}^2}\! \psi w_\varepsilon |\nabla (\psi w_\varepsilon)| \, \mathrm{d}  x. 
\end{equation*}
 The rest of the proof of \eqref{eq:first checkpoint moser bis} is divided into two substeps (depending on the value of $q$). 




\smallskip 

\noindent 1.i. \textit{Parabolic estimate: case $q \in (0,1)$}. In this case $q^{-1}-1>0$, and \eqref{eq:equality} yields 
\begin{equation*}
   \begin{aligned}
      -\frac{\mathrm{d}}{\mathrm{d} t} \Vert \psi  w_\varepsilon & \Vert_{L^2(\mathbb{T}^2)}^2 \!+\! 4(q^{-1}\!-\!1) \Vert\nabla(\psi w_\varepsilon)\Vert_{L^2(\mathbb{T}^2)}^2 \leq 4(1\!-\!q) \!\int \!\! \psi w_\varepsilon |\nabla (\psi w_\varepsilon)| \, \mathrm{d}  x   \!+\! 2\! \int\!\! \psi |\partial_t \psi| w^2_\varepsilon \, \mathrm{d}  x \\ 
      &\leq 2q^2(q^{-1}-1)\Vert \psi w_\varepsilon\Vert^2_{L^2(\mathbb{T}^2)} + 2(q^{-1}-1)\Vert\nabla(\psi w_\varepsilon)\Vert_{L^2(\mathbb{T}^2)}^2 + \frac{2C}{R-r} \Vert w_\varepsilon \Vert^2_{L^2(\mathbb{T}^2)}, 
   \end{aligned} 
\end{equation*}
where we used Young's inequality in the final line. Using $0 \leq \psi \leq 1$, it follows that 
\begin{equation*}
   \begin{aligned}
     - \frac{\mathrm{d}}{\mathrm{d} t} \Vert \psi w_\varepsilon \Vert_{L^2(\mathbb{T}^2)}^2 \!+\! (q^{-1}\!-\!1) \Vert\nabla(\psi w_\varepsilon)\Vert_{L^2(\mathbb{T}^2)}^2 \leq C\Big(q^2 (q^{-1}\!-\!1)\!+\!\frac{1}{R\!-\!r} \Big) \Vert w_\varepsilon \Vert^2_{L^2(\mathbb{T}^2)}, 
   \end{aligned} 
\end{equation*}
where the positive constant $C$ is independent of $q,r,R,\varepsilon$. Note that since $q \in (0,1)$ we have $q^2(q^{-1}-1) \leq q^2 q^{-1} = q < 1$. By rewriting the left-hand side in terms of $\delta$ and integrating in time over the interval $[t,R]$, for any $t \in (-r,r)$, we get 
\begin{equation*}
   \begin{aligned}
     \Vert w_\varepsilon(t) \Vert_{L^2(\mathbb{T}^2)}^2 + \delta \int_{t}^{R} \! \int_{\mathbb{T}^2} \! |\nabla(\psi w_\varepsilon)|^2 \, \mathrm{d}  x \, \mathrm{d}  s \leq \frac{C}{R\!-\!r}  \! \int_{t}^{R} \! \Vert w_\varepsilon(s) \Vert_{L^2(\mathbb{T}^2)}^2 \, \mathrm{d}  s, 
   \end{aligned} 
\end{equation*}
where we used that $\psi(t) = 1$ for such $t$, $\psi(R)=0$ from \eqref{eq:test function time psi for moser upper}, and $0<R-r<1$. Thus, by considering each term on the left-hand side separately, we deduce for $q \in (0,1)$: 
\begin{equation*}
   \begin{aligned}
     \Vert w_\varepsilon(t) \Vert_{L^2(\mathbb{T}^2)}^2 + \int_{t}^{R} \! \int_{\mathbb{T}^2} \! |\nabla(\psi w_\varepsilon)|^2 \, \mathrm{d}  x \, \mathrm{d}  s \leq C \Big( \frac{1+\delta^{-1}}{R\!-\!r}  \Big) \int_{t}^{R} \! \Vert w_\varepsilon(s) \Vert_{L^2(\mathbb{T}^2)}^2 \, \mathrm{d}  s. 
   \end{aligned} 
\end{equation*}
One deduces \eqref{eq:first checkpoint moser bis} easily for this range of $q$. 

\smallskip 

\noindent 1.ii. \textit{Parabolic estimate: case $q>1$}. For $q>1$, applying Young's inequality to \eqref{eq:equality} gives 
\begin{equation*}
   \begin{aligned}
      \frac{\mathrm{d}}{\mathrm{d} t} & \int_{\mathbb{T}^2} |\psi w_\varepsilon|^2 \, \mathrm{d}  x + 4(1-q^{-1}) \int_{\mathbb{T}^2} |\nabla(\psi w_\varepsilon)|^2 \, \mathrm{d}  x \\ 
      &\leq 2q^2(1-q^{-1})\Vert \psi w_\varepsilon\Vert^2_{L^2(\mathbb{T}^2)} + 2(1-q^{-1})\Vert\nabla(\psi w_\varepsilon)\Vert_{L^2(\mathbb{T}^2)}^2 + \frac{2C}{R-r} \Vert w_\varepsilon \Vert^2_{L^2(\mathbb{T}^2)}, 
   \end{aligned} 
\end{equation*}
and thus, rewriting in terms of $\delta$, noting that $\delta \in (0,1)$ in this case, and $q^2(1-q^{-1})=q^2 \delta$, 
\begin{equation*}
   \begin{aligned}
    \delta  \frac{\mathrm{d}}{\mathrm{d} t} \Vert \psi w_\varepsilon \Vert_{L^2(\mathbb{T}^2)}^2 + \delta \Vert\nabla(\psi w_\varepsilon)\Vert_{L^2(\mathbb{T}^2)}^2 \leq C \big(q^2\delta +\frac{1}{R\!-\!r} \big) \Vert w_\varepsilon \Vert^2_{L^2(\mathbb{T}^2)}, 
   \end{aligned} 
\end{equation*}
where the constant $C$ is independent of $q,r,R,\varepsilon$. Dividing by $\delta$ and integrating in time over $[-R,t]$ for $t \in (-r,r)$, arguing as per the end of Step 1.i, we again obtain   \eqref{eq:first checkpoint moser bis}. 



\smallskip 

\noindent 2. \textit{Recursive estimate}. Using $\Vert w_\varepsilon \Vert_{L^4(Q_r)} \leq C    ( \Vert w_\varepsilon \Vert_{L^\infty(-r,r;L^2(\mathbb{T}^2))} + \Vert \nabla w_\varepsilon \Vert_{L^2(Q_r)}  )$ from Lemma \ref{lem:dibenedetto classic} as per Step 2 of the proof of Lemma \ref{lem:moser 1/u} and arguing identically, we get 
\begin{equation}\label{eq:second checkpoint moser upper}
   \begin{aligned}
     \Vert u+\varepsilon \Vert_{L^{2q}(Q_r)} \leq \Big( \frac{C(1+ q^2 + \delta^{-1} )}{R\!-\!r} \Big)^{\frac{1}{q}} \Vert u+\varepsilon \Vert_{L^q(Q_R)}, 
   \end{aligned} 
\end{equation}
where $C$ is independent of $q,r,R,\varepsilon$. Next, as per Step 2 of the proof of \cite[Lemma 3.9]{BonforteDolbeaultNazaretSimonov}, set $$\gamma :=5/3,$$ and using the H\"older inequality, we get $
    \Vert u+ \varepsilon \Vert_{L^{\gamma q}(Q_r)} \leq |Q_r|^{(1-\frac{\gamma}{2})\frac{1}{\gamma q}} \Vert u + \varepsilon \Vert_{L^{2q}(Q_r)} \leq |Q_1|^{\frac{1}{10q}}\Vert u + \varepsilon \Vert_{L^{2q}(Q_r)}, $ which, using \eqref{eq:second checkpoint moser upper}, yields the \emph{reverse H\"older inequality}
\begin{equation}\label{eq:second checkpoint moser upper gamma}
   \begin{aligned}
     \Vert u+\varepsilon \Vert_{L^{\gamma q}(Q_r)} \leq \Big( \frac{C (1+q^2+\delta^{-1} ) }{R\!-\!r} \Big)^{\frac{1}{q}} \Vert u+\varepsilon \Vert_{L^q(Q_R)}, 
   \end{aligned} 
\end{equation}
where $C$ is independent of $q,r,R,\varepsilon$. The reason for introducing this exponent $\gamma$ is to avoid $q_n = 1$ for some $n$ for the sequence of powers in the iteration (\textit{cf.~}next step of the proof). 






\smallskip 

\noindent 3. \textit{Moser's iterations}. Let $0 < r < R \leq 1$ be fixed as in the statement, and recall from \eqref{eq:sequence of radii} the sequence of radii $r_0 = R$, $r_n = R - (R-r) \sum_{k=1}^n 2^{-k} $, which satisfies $r_{n} -r_{n+1} = (R-r) 2^{-n-1}$ as per \eqref{eq:spacing between radii}. For the sequence of powers, we set 
\begin{equation*}
    n_0 := 1+ \floor{\frac{\log(\frac{1+\gamma}{2p})}{\log \gamma}}, \qquad q_0 := \frac{1+\gamma}{2 \gamma^{n_0}}, 
\end{equation*}
where $p$ is given in the statement, and $q_n := q_0 \gamma^n$ for all $n$. The definition of $n_0$ implies 
\begin{equation*}
    \frac{\log(\frac{1+\gamma}{2p})}{\log \gamma} < n_0 \leq 1 + \frac{\log(\frac{1+\gamma}{2p})}{\log \gamma} \implies    \frac{1+\gamma}{2p} <    \gamma^{n_0} \leq \gamma \frac{1+\gamma}{2p}, 
\end{equation*}
whence $q_0 < p \leq \gamma q_0$ and 
\begin{equation*}
    \gamma^{n_0} q_0 = \frac{1+\gamma}{2}=\frac{4}{3} > 1 > \frac{4}{5} = \frac{1+\gamma}{2\gamma} = \gamma^{n_0-1} q_0  , 
\end{equation*}
whence $|q_n \!-\! 1| \geq \min\{q_{n_0}\!-\!1,1\!-\!q_{n_0-1}\} = \frac{1}{5}$. Defining $\delta_n := |1-q_n^{-1}|$ as per \eqref{eq:delta def in proof of moser upper}, it holds 
\begin{equation*}
    \delta_n^{-1} = \frac{q_n}{|q_n-1|} \leq 5 q_n \leq \frac{5}{2}(1+q_n^2) \qquad \forall n. 
\end{equation*}
As such, by iterating \eqref{eq:second checkpoint moser upper gamma} along the sequence of radii $\{r_n\}$ and powers $\{q_n\}$, we get 
\begin{equation}\label{eq:kappa n round 2}
   \begin{aligned}
     \Vert u+\varepsilon \Vert_{L^{q_0 \gamma^{n+1}}(Q_{r_{n+1}})} \leq \underbrace{\Big( \frac{C (1+q_0^2 \gamma^{2n})}{r_{n}\!-\!r_{n+1}} \Big)^{\frac{1}{q_0 \gamma^{n}}} }_{=:\kappa_n}\Vert u+\varepsilon \Vert_{L^{q_0 \gamma^n}(Q_{r_n})} \qquad \forall n \in \mathbb{N}. 
   \end{aligned} 
\end{equation}
As per Step 3 of the proof of Lemma \ref{lem:moser 1/u}, we study the boundedness of $\kappa_n$: for all $n$ sufficiently small such that $q_0 \gamma^n \leq 1$, it holds $\kappa_n \leq ( \frac{C 2^{n+2}}{R-r} )^{\frac{1}{q_0 \gamma^{n}}} \leq ( \frac{4C}{R-r} )^{\frac{1}{q_0 \gamma^{n}}} 2^{\frac{n}{q_0 \gamma^n}},$
while for all $n$ sufficiently large such that $q_0 \gamma^n \geq 1$, we have $\kappa_n \leq ( \frac{C q_0^2 \gamma^{2n} 2^{n+2}}{R-r} )^{\frac{1}{q_0 \gamma^{n}}} \leq ( \frac{4Cq_0^2}{R-r} )^{\frac{1}{q_0 \gamma^{n}}} 2^{\frac{3n}{q_0 \gamma^n}} \leq ( \frac{4C}{R-r} )^{\frac{1}{q_0 \gamma^{n}}} 2^{\frac{3n}{q_0 \gamma^n}}, $ where we also used $0 < q_0 < p < 1$ and $\gamma < 2$. In either case, we obtain 
\begin{equation*}
    \kappa_n \leq \Big( \frac{C}{R-r} \Big)^{\frac{1}{q_0 \gamma^{n}}} 2^{\frac{3n}{q_0 \gamma^n}} \qquad \forall n \in\mathbb{N}, 
\end{equation*}
where $C$ is independent of $q_0,p,r,R,\varepsilon,n$. Returning to \eqref{eq:kappa n round 2} and iterating,  
\begin{equation*}
   \begin{aligned}
     \Vert u+\varepsilon \Vert_{L^{q_0 \gamma^{n+1}}(Q_{r_{n+1}})} \leq \underbrace{\bigg( \prod_{k=0}^n \Big( \frac{C }{R-r} \Big)^{\frac{1}{q_0 \gamma^{k}}} 2^{\frac{3k}{q_0 \gamma^k}} \bigg)}_{=: B_n} \Vert u+\varepsilon \Vert_{L^{q_0}(Q_{R})}, 
   \end{aligned} 
\end{equation*}
\textit{i.e.}, using H\"older's inequality and $|Q_1|^{\frac{1}{q_0}-\frac{1}{p}} \leq (1+|Q_1|)^{\frac{1}{q_0}-\frac{1}{p}}$, we get 
\begin{equation}\label{eq:still with Bn}
    \begin{aligned}
        \Vert u\!+\!\varepsilon \Vert_{L^{q_0 \gamma^{n+1}}(Q_{r_{n+1}})} \leq B_n |Q_1|^{\frac{1}{q_0}-\frac{1}{p}}  \Vert u \!+\! \varepsilon \Vert_{L^p(Q_R)} \leq B_n (1+|Q_1|)^{\frac{1}{q_0}} \Vert u \!+\! \varepsilon \Vert_{L^p(Q_R)}. 
    \end{aligned}
\end{equation}
Analogously to Step 3 of the proof of Lemma \ref{lem:moser 1/u}, we study the convergence of $\{B_n\}_n$:
\begin{equation*}
   \begin{aligned}
      \log B_n = \frac{1}{q_0} \log  \Big( \frac{C }{R-r} \Big) \sum_{k=0}^n  \gamma^{-k} + \frac{3}{q_0}\log 2 \sum_{k=0}^n k \gamma^{-k} \nearrow \frac{1}{q_0} \frac{\gamma}{\gamma-1} \log  \Big( \frac{C }{R-r} \Big) + \frac{1}{q_0}\log \bar{C}, 
   \end{aligned} 
\end{equation*}
with $\log \bar{C} = 3 \log 2 \sum_{n\geq 0} n \gamma^{-n}$, and thus using the continuity of the logarithm, it holds 
\begin{equation*}
    B_n \nearrow B = \Big( \frac{C }{(R-r)^{\frac{\gamma}{\gamma-1}}} \Big)^{\frac{1}{q_0}}, 
\end{equation*}
for some $C$ independent of $q_0,R,r$ and can be assumed greater than $1$. Returning to \eqref{eq:still with Bn}, 
\begin{equation*}
    \begin{aligned}
        \Vert u+\varepsilon \Vert_{L^{\infty}(Q_{r})} \leq \Big( \frac{C }{(R-r)^{\frac{\gamma}{\gamma-1}}} \Big)^{\frac{1}{q_0}}  \Vert u + \varepsilon \Vert_{L^p(Q_R)} \leq \Big( \frac{C }{(R-r)^{\frac{\gamma^2}{\gamma-1}}} \Big)^{\frac{1}{p}} \Vert u + \varepsilon \Vert_{L^p(Q_R)}
    \end{aligned}
\end{equation*}
using that $p \leq \gamma q_0$ and $C \geq 1 > R-r$, where $C$ is independent of $p,r,R,\varepsilon$ but is allowed to depend on $\gamma$. The result follows by bluntly bounding $(R-r)^{-\frac{\gamma^2}{\gamma-1}} = (R-r)^{-25/6} \leq (R-r)^{-5}$, using again that $R-r < 1$.

\label{lem:log level sets}
Let $u$ be a weak solution of \eqref{eq:u eq} satisfying \eqref{eq:initial upgrade dt rho}, $\varepsilon,r \in (0,1)$. Define 
\begin{equation}\label{eq:aeps def}
    w_\varepsilon := -\log(u+\varepsilon), \qquad a_\varepsilon :=  \int_{\mathbb{T}^2}   \log\big(u(0,x)+\varepsilon\big) \, \mathrm{d}  x 
\end{equation}
There exists a positive constant $C$ independent of $\varepsilon,r$ such that, for all $s > 0$, it holds 
    \begin{equation}\label{eq:sublevel log est}
       \begin{aligned}
           & \bigg| \Big\{ (t,x) \! \in Q_r^+ \!:  w_\varepsilon(t,x) \!+\! a_\varepsilon  \! > \! s   \Big\} \bigg| \leq \frac{C}{s}, \quad \bigg| \Big\{ (t,x) \! \in Q_r^-\! :  w_\varepsilon(t,x) \!+\! a_\varepsilon \! <\!- s   \Big\} \bigg| \leq \frac{C}{s}. 
       \end{aligned}
    \end{equation}

The proof is divided into three steps. 

\smallskip 

\noindent 1. \textit{A differential inequality for the mean}. Recall  \eqref{eq:initial upgrade dt rho}: this regularity implies that (in view of the chain rule for Sobolev functions, \textit{cf.}~\textit{e.g.}~\cite[\S 5.10]{Evans}) the formula 
\begin{equation*}
    \frac{\mathrm{d}}{\mathrm{d} t} \int_{\mathbb{T}^2} -\log(u+\varepsilon)   \, \mathrm{d}  x = \langle \partial_t u , -(u+\varepsilon)^{-1}  \rangle 
\end{equation*}
is justified a.e.~$t$. By testing \eqref{eq:u eq} against $-(u+\varepsilon)^{-1} $, we get 
\begin{equation*}
    \begin{aligned}
        \int_{\mathbb{T}^2}   w_\varepsilon(t_2,x) \, \mathrm{d}  x \!-\! \int_{\mathbb{T}^2}   w_\varepsilon(t_1,x) \, \mathrm{d}  x \!+\! \int_{t_1}^{t_2} \!\! \int_{\mathbb{T}^2}  | \nabla w_\varepsilon |^2 \, \mathrm{d}  x \, \mathrm{d}  \tau = \!\int_{t_1}^{t_2}\!\!\! \int_{\mathbb{T}^2} \! \frac{u}{(u+\varepsilon)} {\bf p} \!\cdot\! \nabla w_\varepsilon \, \mathrm{d}  x \, \mathrm{d}  \tau. 
    \end{aligned}
\end{equation*}
for a.e.~$-1 < t_1<t_2 < 1$. Thus, by applying Young's inequality and using $\Vert {\bf p} \Vert_{L^\infty} \leq 1$, 
\begin{equation}\label{eq:first log est}
    \begin{aligned}
        \int_{\mathbb{T}^2}  w_\varepsilon(t_2,x) \, \mathrm{d}  x - \int_{\mathbb{T}^2}   w_\varepsilon(t_1,x) \, \mathrm{d}  x + \frac{1}{2} \int_{t_1}^{t_2} \int_{\mathbb{T}^2}  | \nabla w_\varepsilon |^2 \, \mathrm{d}  x \, \mathrm{d}  t \leq C_*(t_2-t_1), 
    \end{aligned}
\end{equation}
where $C_*=\frac{1}{2}|\mathbb{T}^2|$ is independent of $t_1,t_2,\varepsilon$. Poincar\'e--Wirtinger's inequality in $\mathbb{T}^2$ implies 
\begin{equation*}
    \int_{t_1}^{t_2} \int_{\mathbb{T}^2}   |w_\varepsilon(\tau,x) - \bar{w}_\varepsilon(\tau)|^2   \, \mathrm{d}  x \, \mathrm{d}  \tau \leq C_P^2 \int_{t_1}^{t_2} \int_{\mathbb{T}^2}    | \nabla w_\varepsilon |^2 \, \mathrm{d}  x \, \mathrm{d}  \tau, 
\end{equation*}
where the Poincar\'e constant $C_P>0$ is independent of $t_1,t_2,\varepsilon$, and $\bar{w}_\varepsilon(\tau) := \fint_{\mathbb{T}^2}   w_\varepsilon(\tau,x) \, \mathrm{d}  x$ is the spatial mean. 
By dividing \eqref{eq:first log est} by $|\mathbb{T}^2|$, the previous inequality implies 
\begin{equation*}
    \begin{aligned}
        \frac{\bar{w}^\varepsilon(t_2) - \bar{w}^\varepsilon(t_1)}{t_2-t_1} +  \frac{(1/2C_P^2)}{t_2-t_1}\int_{t_1}^{t_2} \fint_{\mathbb{T}^2}   |w_\varepsilon(\tau,x) - \bar{w}_\varepsilon(\tau)|^2 \, \mathrm{d}  x \, \mathrm{d}  \tau \leq C_*, 
    \end{aligned}
\end{equation*}
where the positive constant $C_*$ is independent of $t_1,t_2,\varepsilon$. By letting $t_2 \to t_1$ and using the Lebesgue Differentiation Theorem, we recover the \emph{differential inequality for the mean}: 
\begin{equation}\label{eq:first log est mod}
    \begin{aligned}
        \frac{\mathrm{d}}{\mathrm{d} t}\bar{w}_\varepsilon(t) + \frac{1}{2C_P^2 } \fint_{\mathbb{T}^2}   |w_\varepsilon(t,x) - \bar{w}_\varepsilon(t)|^2 \, \mathrm{d}  x \leq C_* \qquad \text{a.e.~}t \in (-1,1). 
    \end{aligned}
\end{equation}





\smallskip 


\noindent 2. \textit{Super-level set estimates}. Our aim in this step is to adapt the strategy of Step 1 to recover a \emph{monotonically decreasing} quantity from the differential inequality \eqref{eq:first log est mod}; \textit{i.e.}~replacing the right-hand side $C_*$ with $0$ instead. To this end, we consider the function: 
\begin{equation}\label{eq:underline subsol log est i}
    \underline{w}(t,x) := w_\varepsilon(t,x) 
    - \bar{w}_\varepsilon(0) - C_* t, 
\end{equation}
where $C_*$ is the positive constant from \eqref{eq:first log est mod}. We also set 
\begin{equation}\label{eq:big W def in superlevel est}
    W(t) := \bar{w}_\varepsilon(t) - \bar{w}_\varepsilon(0) - C_* t; 
\end{equation}
note that $W(0) = 0$, $|\underline{w}(t,x) - W(t)| = |w_\varepsilon(t,x) - \bar{w}_\varepsilon(t)|$ and $\frac{\mathrm{d}}{\mathrm{d} t}W(t) = \frac{\mathrm{d}}{\mathrm{d} t}\bar{w}_\varepsilon(t) - C_*$. Substituting these computations in \eqref{eq:first log est mod}, we deduce 
\begin{equation}\label{eq:first log est mod W}
    \begin{aligned}
      \frac{\mathrm{d}}{\mathrm{d} t}W(t) \!+\!  \frac{1}{2C_P^2}\fint_{\mathbb{T}^2} |\underline{w}(t,x) \!-\! W(t)|^2 \, \mathrm{d}  x \leq 0 \implies W(t) \leq W(0) = 0 \quad \text{a.e.~} t \in (0,1). 
    \end{aligned}
\end{equation}


Next, for all $s>0,t \in (0,1)$, define the super-level set $\Sigma_s(t)$ and $\sigma_s(t)$ by 
\begin{equation}\label{eq:define sets Sigma and sigma}
\Sigma_s(t) := \{x \in \mathbb{T}^2 : \underline{w}(t,x) > s \}, \qquad \sigma_s(t) := \{x \in \mathbb{T}^2 : w_\varepsilon(t,x) - \bar{w}_\varepsilon(0) > s \}; 
\end{equation}
our strategy will be to use estimates on $\Sigma_s(t)$ to control the measure of $\sigma_s(t)$. Indeed, for all $t \in (0,1)$, we verify directly the inclusions 
\begin{equation}\label{eq:relationship between Sigma and sigma set}
    \Sigma_s(t) \subset \sigma_s(t) \quad \forall s>0, \qquad \sigma_{2s}(t) \subset \Sigma_s(t) \quad \forall s \geq C_*. 
\end{equation}
Using \eqref{eq:first log est mod W}, direct computation (using that $W(t) \leq 0$) yields 
\begin{equation}
    \underline{w}(t,x) - W(t) > s - W(t) \geq s > 0 \quad \text{for all } x \in \Sigma_s(t). 
\end{equation}
Furthermore, using also $\frac{\mathrm{d}}{\mathrm{d} t}W(t) = - \frac{\mathrm{d}}{\mathrm{d} t}(s-W(t))$ and \eqref{eq:first log est mod W}, we get 
\begin{equation*}
   \frac{1}{2C_P^2|\mathbb{T}^2|} \int_{\Sigma_s(t)} \!\!\!\!\!\! (s-W(t))^2 \, \mathrm{d}  x \leq \frac{\mathrm{d}}{\mathrm{d} t}(s- W(t)) \implies  \frac{\mathrm{d}}{\mathrm{d} t}(s- W(t)) \geq \frac{1}{2C_P^2|\mathbb{T}^2|} |\Sigma_s(t)| (s-W(t))^2. 
\end{equation*}
We integrate the final inequality in $t$ over the interval $[0,r]$ and get 
\begin{equation*}
    |\{(t,x) \in Q_r^+ : \underline{w}(t,x) > s \}| = \int_0^r |\Sigma_s(t)| \, \mathrm{d}  t \leq  \frac{2C_P^2|\mathbb{T}^2|}{s- W(0)}  - \frac{2C_P^2|\mathbb{T}^2|}{s-W(r)} \leq \frac{2C_P^2|\mathbb{T}^2|}{s}, 
\end{equation*}
where we used $W(0)=0$, $s-W(r)>0$. By the above and \eqref{eq:relationship between Sigma and sigma set}, we get 
\begin{equation}\label{eq:suplevel est i}
   |\{(t,x) \in Q_r^+: w_\varepsilon(t,x) \!-\! \bar{w}_\varepsilon(0) > s \}| \leq |\{(t,x) : \underline{w}(\tau,x) > \frac{s}{2} \}| \leq \frac{4C_P^2|\mathbb{T}^2|}{s} \quad \forall s \geq C_*, 
\end{equation}
while, for $0 < s < C_*$, we estimate bluntly by the measure of the whole space 
\begin{equation}\label{eq:suplevel est ii}
   |\{(t,x) \in Q_r^+:w_\varepsilon(t,x) - \bar{w}_\varepsilon(0) > s \}| \leq |Q_1^+| \frac{s}{s} < \frac{|Q_1| C_*}{s} \quad \forall s \in (0,C_*). 
\end{equation}
By putting together the bounds of \eqref{eq:suplevel est i}--\eqref{eq:suplevel est ii}, we obtain the super-level set estimate 
\begin{equation*}
   |\{(t,x)\in Q_r^+ : w_\varepsilon(t,x) - \bar{w}_\varepsilon(0) > s \}| \leq \frac{C}{s} \qquad \forall s>0, 
\end{equation*}
where the positive constant $C=\max\{|Q_1|C_*,4C_P^2|\mathbb{T}^2|\}$ is independent of $\varepsilon,r$. Rewriting in terms of $a_\varepsilon$ as per \eqref{lem:log level sets} yields the first part of \eqref{eq:sublevel log est}. 

\smallskip 

\noindent 3. \textit{Sub-level set estimates}. As per the final step of \cite[Lemma 3.11]{BonforteDolbeaultNazaretSimonov}, rewriting only Step 2 of the proof with $-t$ instead of $t$ yields the second part of \eqref{eq:sublevel log est}. We write out several details for the benefit of the reader. In this latter case, it holds $W(t) \geq 0$ for all $t \in (-1,0)$ with $W$ as per \eqref{eq:big W def in superlevel est}, and the inclusions of \eqref{eq:relationship between Sigma and sigma set} are again satisfied, but with re-defining the sets in \eqref{eq:define sets Sigma and sigma} as $\Sigma_s(t) = \{x: \underline{w}(t,x) < -s\}$ and $\sigma_s(t) = \{x : w_\varepsilon(t,x) - \bar{w}_\varepsilon(0) < -s \}$, and $\underline{w}$ still defined as per \eqref{eq:underline subsol log est i}. Then, we notice that for all $x \in \Sigma_s(t)$, it holds 
\begin{equation*}
    W(t) - \underline{w}(t,x) > W(t) + s \geq s > 0, 
\end{equation*}
and thus, arguing as before, we obtain from the differential inequality of \eqref{eq:first log est mod W} that 
\begin{equation*}
    \frac{\mathrm{d} }{\mathrm{d} t} W(t) + \frac{1}{2C_P^2|\mathbb{T}^2|} \int_{\Sigma_s(t)} (W(t)+s)^2 \, \mathrm{d}  x \leq 0 \implies \frac{1}{2C_P^2|\mathbb{T}^2|} |\Sigma_s(t)| \leq \frac{\mathrm{d}}{\mathrm{d} t} (W(t)+s)^{-1}, 
\end{equation*}
and thus $|\{(t,x) \in Q_r^- : \underline{w}(t,x) < -s \}| = \int^0_{-r} |\Sigma_s(t)| \, \mathrm{d}  t \leq \frac{2C_P^2|\mathbb{T}^2|}{W(0)+s} - \frac{2C_P^2|\mathbb{T}^2|}{W(-r)+s} \leq \frac{2C_P^2|\mathbb{T}^2|}{s}$, and the required conclusion follows as per the end of Step 2 of the proof.

\label{prop:lower bound rho improved}
   Let $f$ be a weak solution of \eqref{eq:main eqn} with admissible initial data $f_0$, $\rho = \int_\mathbb{T} f \, \mathrm{d}  \theta$. Then, there exists a positive constant $C>1$ $($independent of $t,T$, the initial data, and the solution$)$ such that 
   \begin{equation}\label{eq:infinite speed of prop}
       \operatorname*{ess \, inf}\limits_{(t,T)\times\mathbb{T}^2}(1\!-\!\rho) \geq  C^{-1} \Vert 1\!-\!\rho_0 \Vert_{L^1(\mathbb{T}^2)} e^{-C\big( T +  (1 \wedge t)^{-10} \big)},  \qquad \forall 0 < t < T < \infty.
   \end{equation}

\label{prop:lower bound rho improved small times only}
   Let $u$ be a weak solution of \eqref{eq:u eq} on $(0,\infty)\times\mathbb{T}^2$ satisfying \eqref{eq:initial upgrade dt rho}. Then, there exists $C>0$, independent of $t$ and $u$, such that 
   \begin{equation}\label{eq:infinite speed of prop small times}
       \operatorname*{ess \, inf}\limits_{(\frac{5}{4}t,\frac{3}{2}t)\times\mathbb{T}^2} u \geq e^{-Ct^{-10}}  \operatorname*{ess \, sup}\limits_{(\frac{1}{4}t,\frac{3}{4}t)\times\mathbb{T}^2} u  \qquad \forall t \in (0,1). 
   \end{equation}

The proof is divided into several steps. We begin by fixing $t_0 \in (0,1)$, setting $a_\varepsilon =  \int_{\mathbb{T}^2}   \log(u(t_0,x) +\varepsilon) \, \mathrm{d}  x $ from \eqref{eq:aeps def} and defining the non-negative measurable functions 
    \begin{equation*}
        v^-_\varepsilon(t,x) := e^{a_\varepsilon} \big(u(t,x)+\varepsilon\big)^{-1} , \qquad v^+_\varepsilon(t,x) := e^{-a_\varepsilon} \big(u(t,x)+\varepsilon\big).
    \end{equation*}



    \smallskip 

    \noindent 1. \textit{Upper bound on the supremum}. By translating the relevant cylinders and multiplying by $e^{-a_\varepsilon}$ (which is justified since $e^{-a_\varepsilon} u(\frac{t_0}{2}+t,x)$ is also a solution of \eqref{eq:u eq} when $u$ is), the conclusion of Lemma \ref{lem:moser u upper}
    holds in the form:  for all $\varepsilon , p\in (0,1)$, and $0 < r < R \leq \frac{t_0}{2}$, there exists a positive constant $C$ independent of $p,r,R,\varepsilon,t_0$ such that 
    \begin{equation*}
   \begin{aligned}
     \Vert v^+_\varepsilon \Vert_{L^{\infty}(Q_r(\frac{t_0}{2}))} \leq \left(\frac{C }{(R-r)^5} \right)^{\frac{1}{p}}\Vert v^+_\varepsilon \Vert_{L^{p}(Q_R(\frac{t_0}{2}))}. 
   \end{aligned} 
\end{equation*}
It therefore follows that $v_\varepsilon^+$ satisfies the first assumption of the Bombieri--Giusti Lemma \ref{lem:bombieri giusti}. Furthermore, for all $s>0$ and all $r<t_0/2$, using the notation $w_\varepsilon(t,x) = -\log(u(t,x)+\varepsilon)$, 
\begin{equation*}
   \begin{aligned}
       \big| \{ (t,x) \in Q_r(\frac{t_0}{2}) : \log v^+_\varepsilon (t,x) > s \} \big|        &=  \big| \{ (t,x) \in Q_{r}(\frac{t_0}{2}) : w_\varepsilon(t,x) \!+\! a_\varepsilon < -s \} \big| \\ 
       &\leq  \big| \{ (t,x) \in Q^-_{t_0}(t_0) : w_\varepsilon(t,x) \!+\! a_\varepsilon < -s \} \big|    \leq \frac{C}{s} , 
   \end{aligned} 
\end{equation*}
by applying Lemma \ref{lem:log level sets} with the choice $r=t_0$ on the translated cylinder at time $t=t_0$ (note that $a_\varepsilon$ corresponds precisely to $\int_{\mathbb{T}^2}\log(u(t_0,x)+\varepsilon) \, \mathrm{d}  x$ so that Lemma \ref{lem:log level sets} applies with the cylinder centered at $t_0$), 
where the positive constant $C$ is independent of $\varepsilon,s,r,t_0$, and where we used the identification of the cylinders $Q_r(\frac{t_0}{2}) = (\frac{t_0}{2}-r,\frac{t_0}{2}+r)\times\mathbb{T}^2 \subset (0,t_0) \times \mathbb{T}^2 = Q^-_{t_0}(t_0)$ for all $r < t_0/2$. The second condition of the Bombieri--Giusti Lemma \ref{lem:bombieri giusti} is therefore also verified for $v_\varepsilon^+$ for the family of nested sets $\{\mathcal{Q}_r = Q_r(\frac{t_0}{2})\}_{r<t_0/2}$, whence an application of this result (taking $\beta =5$ and $\tilde r = t_0/2$) implies $\Vert v^+_\varepsilon \Vert_{L^\infty(Q_r(t_0))} \leq e^{\bar{C}_1 (\frac{t_0}{2}-r)^{-10}}$ for all $0<r<\frac{t_0}{2}$, where the positive constant $\bar{C}_1$ is independent of $\varepsilon,r,t_0$. Thus, 
\begin{equation}\label{eq:first half of harnack}
   \begin{aligned}
      \varepsilon + \operatorname*{ess \, sup}_{Q_r(\frac{t_0}{2})} u \leq e^{a_\varepsilon} e^{\bar{C}_1 (\frac{t_0}{2}-r)^{-10}} \qquad \forall 0 < r < \frac{t_0}{2}. 
   \end{aligned}
\end{equation}


\smallskip 

\noindent 2. \textit{Lower bound on the infimum}. Similarly, by multiplying the conclusion of Lemma \ref{lem:moser 1/u} with $e^{a_\varepsilon}$ and centering the cylinders at $t= 3t_0/2$ by translation, we get 
    \begin{equation*}
   \begin{aligned}
    \Vert v^-_\varepsilon \Vert_{L^{\infty}(Q_r^-(\frac{3}{2}t_0))} \leq \left(\frac{C }{(R-r)^2} \right)^{\frac{1}{p}}\Vert v^-_\varepsilon \Vert_{L^{p}(Q_R^-(\frac{3}{2}t_0))} \qquad \forall 0 < r < R \leq \frac{3}{2}t_0, 
   \end{aligned} 
\end{equation*}
for all $p \in (0,1)$, with $C$ again independent of $\varepsilon,r,R,p,t_0$. Meanwhile, another application of Lemma \ref{lem:log level sets} (this time with the choice $r=t_0/2$ and having translated the cylinder to $t=t_0$) implies for all $s>0$ and all $r < t_0/2$, with the notation $w_\varepsilon(t,x) = -\log(u(t,x)+\varepsilon)$, 
\begin{equation*}
   \begin{aligned}
      \big| \{ (t,x) \in Q_r^-(\frac{3}{2}t_0) : \log v^-_\varepsilon (t,x) > s \} \big|             &=  \big| \{ (t,x) \in Q_r^-(\frac{3}{2}t_0) : w_\varepsilon(t,x) \!+\! a_\varepsilon > s \} \big| \\ 
      &\leq  \big| \{ (t,x) \in Q_{\frac{t_0}{2}}^+( t_0) : w_\varepsilon(t,x) \!+\! a_\varepsilon > s \} \big|   \leq \frac{C}{s} , 
   \end{aligned} 
\end{equation*}
where the positive constant $C$ is independent of $\varepsilon,s,r,t_0$, where we used the identification of the cylinders $Q_r^-(\frac{3}{2}t_0) = (\frac{3}{2}t_0-r,\frac{3}{2}t_0)\times\mathbb{T}^2 \subset (t_0,\frac{3}{2}t_0) = Q_{t_0/2}^+(t_0)$ for all $ r < t_0/2$. The second condition of the Bombieri--Giusti Lemma \ref{lem:bombieri giusti} is thus also fulfilled by $v_\varepsilon^-$ for the family of nested sets $\{\mathcal{Q}_r = Q_r^-(\frac{3}{2}t_0)\}_{r<t_0/2}$. Applying this result with the choices $\beta =2$ and $\tilde r = t_0/2$ implies $\Vert v^-_\varepsilon \Vert_{L^\infty(Q_r^-(\frac{3}{2}t_0))} \leq e^{\bar{C}_2 (\frac{t_0}{2}-r)^{-4}}$ for all $0<r<\frac{t_0}{2}$, where the positive constant $\bar{C}_2$ is independent of $\varepsilon,r,t_0$, from which we deduce 
\begin{equation}\label{eq:second half of harnack}
   \begin{aligned}
      \varepsilon + \operatorname*{ess \, inf}_{Q_r^-(\frac{3}{2}t_0)} u \geq e^{a_\varepsilon} e^{-\bar{C}_2 (\frac{t_0}{2}-r)^{-4}} \qquad \forall 0 < r < \frac{t_0}{2}. 
   \end{aligned}
\end{equation}

\smallskip 

\noindent 3. \textit{Harnack inequality}. Choosing $r=t_0/4$ in \eqref{eq:first half of harnack} and \eqref{eq:second half of harnack}, we get (with $C_1' = 4^{10} \bar{C}_1$, $C_2' = 4^4 \bar{C}_2$), the bound $( \varepsilon + \operatorname*{ess \, inf}_{Q_{t_0/4}^-(\frac{3}{2}t_0)} u ) e^{C_2' t_0^{-4}} \geq e^{a_\varepsilon} \geq ( \varepsilon + \operatorname*{ess \, sup}_{Q_{t_0/4}(\frac{t_0}{2})} u ) e^{-C_1' t_0^{-10}}$. Setting $C=C_1'+C_2'$, which is independent of $\varepsilon,t_0$, we deduce by letting $\varepsilon \to 0^+$ 
\begin{equation*}
    \operatorname*{ess \, inf}_{Q_{\frac{t_0}{4}}^-(\frac{3}{2}t_0)} u  \geq e^{- C t_0^{-10}} \operatorname*{ess \, sup}_{Q_{\frac{t_0}{4}}(\frac{t_0}{2})} u , 
\end{equation*}
where we also used $0<t_0<1$. Rewriting the cylinders and setting $t=t_0$ yields \eqref{eq:infinite speed of prop small times}.

\label{cor:lower bound depending on L1 norm}
    Let $f$ be a weak solution of \eqref{eq:main eqn} with admissible initial data $f_0$, $\rho = \int_\mathbb{T} f \, \mathrm{d}  \theta$, and $u=1-\rho$. Then, there exists a positive constant $C$ $($independent of $t$, the initial data, and the solution$)$, such that 
   \begin{equation}\label{eq:infinite speed of prop small times in terms of L1}
       \operatorname*{ess \, inf}\limits_{(\frac{5}{4}t,\frac{3}{2}t)\times\mathbb{T}^2} u \geq  C^{-1} \Vert 1-\rho_0 \Vert_{L^1(\mathbb{T}^2)}  e^{-Ct^{-10}} \qquad \forall t \in (0,1). 
       \end{equation}

\label{lem:propogation big times}
        Let $f$ be a weak solution of \eqref{eq:main eqn} with admissible initial data $f_0$, $\rho = \int_\mathbb{T} f \, \mathrm{d}  \theta$, and $u=1-\rho$. Fix any Lebesgue point $t_0 \in (0,1)$ of $t \mapsto \operatorname*{ess \, inf}_{x\in \mathbb{T}^2} u(t,x)$. Then, there exists a strictly positive constant $C$ $($independent of $t_0,t$, the initial data, and the solution$)$ such that 
        \begin{equation*}
            \operatorname*{ess \, inf}_{(t_0,t)\times\mathbb{T}^2} u \geq C^{-1} e^{-Ct} \operatorname*{ess \, inf}_{x\in\mathbb{T}^2}u(t_0,x) \qquad \forall t > t_0. 
        \end{equation*}

\label{lem:tech iteration lemma}
Let $\{A_k\}_{k\geq 0}$ be a sequence of non-negative differentiable functions satisfying the differential recurrence inequality on $[0,t]$$:$ 
      \begin{equation}\label{eq:for tech iter lemma}
        \frac{\mathrm{d} A_k}{\mathrm{d} t} + A_k \leq C_*^k (A_{k-1})^2 \qquad \forall k \geq 1, 
    \end{equation}
    where $C_* \geq 2$ is independent of $k$. Let $n_k = 2^k$, and suppose there exists $M_1,M_2>0$ such that $\sup_{k \geq 0} A_k(0)^{1/n_k} \leq M_1$ and $\Vert A_0 \Vert_{L^\infty([0,t])} \leq M_2$. Then, with $\beta = 1 + \sum_{j=1}^\infty (j+1)2^{-j}$, 
    \begin{equation}\label{eq:KimZhangPrecise}
       \sup_{k \geq 0} \Vert A_k \Vert_{L^\infty([0,t])}^{1/n_k} \leq C_*^\beta (M_1+M_2). 
    \end{equation}

Fix $t_0 \in (0,1)$ as in the statement. By Corollary \ref{cor:lower bound depending on L1 norm}, it holds  $\operatorname*{ess \, inf}_{x\in\mathbb{T}^2} u(t_0,x) > 0$ provided $\Vert 1 -\rho_0 \Vert_{L^1(\mathbb{T}^2)}>0$, which we assume. In other words, defining $v:=1/u$ and $v_0 = v(t_0,\cdot)$, 
    \begin{equation}\label{eq:lower bound in proof of propagation}
      \Vert v_0 \Vert_{L^\infty(\mathbb{T}^2)} = \big( \operatorname*{ess \, inf}_{x\in\mathbb{T}^2} u(t_0,x) \big)^{-1} < \infty. 
    \end{equation}
    We will now rewrite the equation \eqref{eq:u eq} as an evolution on $v$, and then show by an iteration procedure that $v$ is bounded for all subsequent times by a quantity depending on $\Vert v_0 \Vert_{L^\infty}$. 

    \smallskip 

    \noindent 1. \textit{Equation for $v$}. By formal manipulations, we expect the equation for $v$ to be $\partial_t v + \operatorname{div}({\bf p} v) - 2 {\bf p} \! \cdot \! \nabla v = \Delta v - 2\frac{|\nabla v|^2}{v}$, \textit{i.e.}, we expect $v$ to be a weak \emph{subsolution} of 
    \begin{equation}\label{eq:v eqn for propagation}
        \partial_t v + \operatorname{div}({\bf p} v) - 2 {\bf p} \! \cdot \! \nabla v = \Delta v.
    \end{equation}
    Note however that \emph{a priori} it is not even clear that $v \in L^2_\mathrm{loc}(0,\infty;H^1(\mathbb{T}^2))$ for $t \geq t_0$; the purpose of this step of the proof is to verify this rigorously. 


    Equation \eqref{eq:u eq} is only satisfied in the weak sense dual to $L^2_\mathrm{loc}(0,\infty;H^1(\mathbb{T}^2))$. To this end, we cannot test \eqref{eq:u eq} directly with functions of $v$ itself, but instead we consider the regularised version $v_\varepsilon := 1/(u+\varepsilon) \in L^2_\mathrm{loc}(0,\infty;H^1(\mathbb{T}^2)) \cap L^\infty((0,\infty)\!\times\!\mathbb{T}^2)$ by Definition \ref{def:weak sol} (\textit{cf.~}also \eqref{eq:initial upgrade dt rho}). We test \eqref{eq:u eq} against the admissible test function $-v_\varepsilon^3$ (since, formally, $\frac{1}{2} \partial_t (v_\varepsilon^2) = v_\varepsilon \partial_t v_\varepsilon = -(u+\varepsilon)^3 \partial_t u = - v_\varepsilon^3 \partial_t u$), and get 
    \begin{equation*}
    \langle \partial_t u ,-v_\varepsilon^3 \rangle -  3\int_{\mathbb{T}^2} v_\varepsilon^2 \nabla v_\varepsilon \cdot  {\bf p} u \, \mathrm{d}  x =  3\int_{\mathbb{T}^2} v_\varepsilon^2 \nabla v_\varepsilon \cdot \nabla u \, \mathrm{d}  x, 
\end{equation*}
using \eqref{eq:initial upgrade dt rho u} and the chain/product rules for Sobolev functions belonging to $H^1(\mathbb{T}^2)$ for a.e.~$t $, \textit{cf.}~\textit{e.g.}~\cite[\S 5.10]{Evans}. Then, writing $u = v_\varepsilon^{-1} - \varepsilon$ and again using the chain rule for Sobolev functions to write $\nabla u = -v_\varepsilon^{-2}\nabla v_\varepsilon$ (here we also use that $v_\varepsilon^{-2} = (u+\varepsilon)^2 \leq (1+\varepsilon)^2 \in L^\infty$), 
\begin{equation*}
    \langle \partial_t u ,-v_\varepsilon^3 \rangle -  3\int_{\mathbb{T}^2} v_\varepsilon \nabla v_\varepsilon \cdot  {\bf p}  \, \mathrm{d}  x +  3 \varepsilon \int_{\mathbb{T}^2} v_\varepsilon^2 \nabla v_\varepsilon \cdot  {\bf p}  \, \mathrm{d}  x = -3\int_{\mathbb{T}^2} |\nabla v_\varepsilon|^2 \, \mathrm{d}  x. 
\end{equation*}
Using that $(1+\varepsilon)^{-1} \leq v_\varepsilon \leq \varepsilon^{-1} \in L^\infty$, $v_\varepsilon \in L^2_\mathrm{loc}(0,\infty;H^1(\mathbb{T}^2))$, and $\partial_t u \in L^{\nicefrac{3}{2}}_\mathrm{loc}([t_0,\infty)\times\mathbb{T}^2)$ from \eqref{eq:initial upgrade dt rho u}, the chain rule for Sobolev functions and the Lions--Magenes Lemma \cite[Ch.3, \S 1.4
Lem.1.2]{Temam} yield $\frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t} \Vert v_\varepsilon \Vert_{L^2(\mathbb{T}^2)}^2 =  \langle \partial_t v_\varepsilon , v_\varepsilon \rangle = -  \langle v_\varepsilon^2 \partial_t u , v_\varepsilon \rangle =  \langle \partial_t u , - v_\varepsilon^3 \rangle $, whence (using the boundedness of ${\bf p}$ \eqref{eq:polarisation bound}, $\varepsilon v_\varepsilon^2 \leq v_\varepsilon$, and H\"older's inequality) 
\begin{equation*}
    \frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t} \Vert v_\varepsilon \Vert_{L^2(\mathbb{T}^2)}^2 + 3 \Vert \nabla v_\varepsilon \Vert^2_{L^2(\mathbb{T}^2)} \leq 6 \Vert v_\varepsilon \Vert_{L^2(\mathbb{T}^2)} \Vert \nabla v_\varepsilon \Vert_{L^2(\mathbb{T}^2)} . 
\end{equation*}
Applying Young's inequality and then Gr\"onwall's Lemma (integrating over $[t_0,t]$) implies 
\begin{equation}\label{eq:gronwall quantitative large times}
    \operatorname*{ess \, sup}_{s \in [t_0,t]}\Vert v_\varepsilon(s,\cdot) \Vert^2_{L^2(\mathbb{T}^2)} + \Vert \nabla v_\varepsilon \Vert^2_{L^2((t_0,t)\times\mathbb{T}^2)} \leq  C \Vert v_\varepsilon(t_0,\cdot) \Vert_{L^2(\Omega)}^2 e^{ Ct} \leq C\Vert v_0 \Vert^2_{L^\infty} e^{Ct}, 
\end{equation}
for a.e.~$t>t_0$, where we used \eqref{eq:lower bound in proof of propagation} and $v_\varepsilon \leq v$, and the constant $C$ changed in the final inequality (but is independent of $t_0,t$ and the initial data). Letting $\varepsilon \to 0^+$ and using the lower semicontinuity of the norm, we get $v \in L^2_\mathrm{loc}([t_0,\infty);H^1(\mathbb{T}^2)) \cap L^\infty_\mathrm{loc}([t_0,\infty);L^2(\mathbb{T}^2))$. 


It remains to write down the equation for $v$. By the aforementioned applications of the chain rule, it holds $\partial_t v_\varepsilon = -v_\varepsilon^2 \partial_t u$ with $\partial_t u$ integrable \eqref{eq:initial upgrade dt rho} and $\nabla v_\varepsilon = -v_\varepsilon^2 \nabla u$. It follows (using the previous computations) that, in the weak sense dual to $L^2_\mathrm{loc}([t_0,\infty);H^1(\mathbb{T}^2))$, 
\begin{equation}\label{eq:eqn for v eps}
    \begin{aligned}\partial_t v_\varepsilon + \operatorname{div}\big( {\bf p} v_\varepsilon(1-\varepsilon v_\varepsilon) \big) - 2 {\bf p} \!\cdot \! \nabla v_\varepsilon (1-\varepsilon v_\varepsilon) = \Delta v_\varepsilon - 2\frac{|\nabla v_\varepsilon|^2}{v_\varepsilon}. 
    \end{aligned}
\end{equation}
Letting $\varepsilon \to 0^+$, using the Dominated Convergence Theorem with $v_\varepsilon = \frac{v}{1+\varepsilon v} \to v$ a.e.~and the regularity $v \in L^2_\mathrm{loc}([t_0,\infty);H^1(\mathbb{T}^2))$, we get that $v$ is a weak subsolution of \eqref{eq:v eqn for propagation}. 





    \smallskip 

    \noindent 2. \textit{Boundedness of $v$}. We argue very closely to \cite[Lemma 5.4]{reg2} using the equation \eqref{eq:eqn for v eps}. We test the equation \eqref{eq:eqn for v eps} with $v_\varepsilon^{n-1}$ for $n \geq 2$ and obtain 
  \begin{equation*}
        \begin{aligned} 
        \frac{\mathrm{d}}{\mathrm{d} t}\int_{\mathbb{T}^2} |v_\varepsilon^{\frac{n}{2}}|^2 \, \mathrm{d}  x + 4(1+\frac{1}{n}) \int_{\mathbb{T}^2} |\nabla (v_\varepsilon^{\frac{n}{2}}) |^2 \, \mathrm{d}  x = & 2(n+1) \int_{\mathbb{T}^2} (1-\varepsilon v_\varepsilon) v_\varepsilon^{\frac{n}{2}} \nabla(v_\varepsilon^{\frac{n}{2}}) \! \cdot \! {\bf p} \, \mathrm{d}  x , 
       \end{aligned}
    \end{equation*}
whence applying Young's inequality (noting also that $0 < v_\varepsilon \leq \varepsilon^{-1}$ so that $|1-\varepsilon v_\varepsilon| \leq 1$), 
\begin{equation}\label{eq:before GN}
        \begin{aligned} 
        \frac{\mathrm{d}}{\mathrm{d} t} \Vert v_\varepsilon^{\frac{n}{2}} \Vert^2_{L^2(\mathbb{T}^2)} + 3\Vert \nabla (v_\varepsilon^{\frac{n}{2}}) \Vert^2_{L^2(\mathbb{T}^2)} \leq 2n^2 \Vert   v_\varepsilon^{\frac{n}{2}} \Vert_{L^2(\mathbb{T}^2)}^2. 
       \end{aligned}
    \end{equation}
Next, an application of the Gagliardo--Nirenberg inequality implies 
\begin{equation*}
    \begin{aligned}
        \Vert v_\varepsilon^{\frac{n}{2}} \Vert_{L^2(\mathbb{T}^2)} \leq C_{GN} \Big( \Vert \nabla (v_\varepsilon^{\frac{n}{2}}) \Vert_{L^2(\mathbb{T}^2)}^{\nicefrac{1}{2}} \Vert v_\varepsilon^{\frac{n}{2}} \Vert_{L^1(\mathbb{T}^2)}^{\nicefrac{1}{2}} + \Vert v_\varepsilon^{\frac{n}{2}} \Vert_{L^1(\mathbb{T}^2)}  \Big); 
    \end{aligned}
\end{equation*}
note that, by squaring both sides and using Young's inequality, the above also gives  $\Vert \nabla v^{\frac{n}{2}} \Vert_{L^2(\mathbb{T}^2)}^{2} \geq C_1 \Vert v^{\frac{n}{2}} \Vert_{L^2(\mathbb{T}^2)}^2 - C_2\Vert v^{\frac{n}{2}} \Vert_{L^1(\mathbb{T}^2)}^2  )$ for some positive constants $C_1,C_2$ depending only on $C_{GN}$. In turn, substituting into the right-hand side of \eqref{eq:before GN} and using Young's inequality again yields $ \frac{\mathrm{d}}{\mathrm{d} t} \Vert v_\varepsilon^{\frac{n}{2}} \Vert^2_{L^2(\mathbb{T}^2)} +  2 \Vert \nabla (v_\varepsilon^{\frac{n}{2}}) \Vert^2_{L^2(\mathbb{T}^2)} \leq ( 4 n^4 C_{GN}^4 + 4n^2 C_{GN}^2 ) \Vert v_\varepsilon^{\frac{n}{2}} \Vert_{L^1(\mathbb{T}^2)}^2  $, \textit{i.e.}, using also $\Vert v_\varepsilon^{\frac{n}{2}} \Vert^2_{L^2(\mathbb{T}^2)} = \Vert v_\varepsilon^{n} \Vert_{L^1(\mathbb{T}^2)}$, 
\begin{equation*}
        \begin{aligned} 
        \frac{\mathrm{d}}{\mathrm{d} t} \Vert v_\varepsilon^{n} \Vert_{L^1(\mathbb{T}^2)} +   \Vert v_\varepsilon^{n} \Vert_{L^1(\mathbb{T}^2)} \leq Cn^4 \Vert v_\varepsilon^{\frac{n}{2}} \Vert_{L^1(\mathbb{T}^2)}^2  , 
       \end{aligned}
    \end{equation*}
where the positive constant $C$ depends only on $C_{GN}$, is independent of $\varepsilon,n,t_0$, and can be assumed greater than 1. By setting $n_k := 2^k$ and $A_k(t) := \Vert v^{n_k}_\varepsilon(t+t_0,\cdot) \Vert_{L^1(\mathbb{T}^2)}, $ we obtain, with $C_* := 16 C$ which can be assumed to verify $C_* \geq 2$, the recurrence inequality 
    \begin{equation*}
        \frac{\mathrm{d} A_k}{\mathrm{d} t} + A_k \leq C_*^k (A_{k-1})^2, 
    \end{equation*}
  which is precisely \eqref{eq:for tech iter lemma}. 
Using the estimate \eqref{eq:gronwall quantitative large times} and 
$$
\begin{aligned} &\sup_k A_k(0)^{1/n_k} = \sup_k \Vert v_\varepsilon(t_0) \Vert_{L^{n_k}(\mathbb{T}^2)} = \Vert v_\varepsilon(t_0) \Vert_{L^\infty(\mathbb{T}^2)} \leq \Vert v_0 \Vert_{L^\infty(\mathbb{T}^2)} =: M_1 , \\ 
&\Vert A_0 \Vert_{L^\infty([t_0,t])} \!=\! \operatorname*{ess \, sup}_{s \in [t_0,t]} \Vert v_\varepsilon(s) \Vert_{L^1(\mathbb{T}^2)} \!\leq \! |\mathbb{T}^2|^{\frac{1}{2}}  \operatorname*{ess \, sup}_{s \in [t_0,t]}\Vert v_\varepsilon(s) \Vert_{L^2(\mathbb{T}^2)} \!\leq \! |\mathbb{T}^2|^{\frac{1}{2}} \Vert v_0 \Vert_{L^\infty} e^{Ct} \! =: \! M_2, 
\end{aligned}$$ 
where we also used H\"older's inequality in the second line (and where the constant $C$ has changed but remains independent of $\varepsilon,t_0,t,$ and the initial data), Lemma \ref{lem:tech iteration lemma} yields 
\begin{equation*}
   \begin{aligned} \Vert v_\varepsilon \Vert_{L^\infty([t_0,t]\times\mathbb{T}^2)} \leq \sup_k \Vert A_k \Vert^{1/n_k}_{L^\infty([0,t])} \leq C(M_1+M_2) \leq C\Vert v_0 \Vert_{L^\infty} e^{Ct}, 
   \end{aligned}
\end{equation*}
for some positive constant $C$ independent of $\varepsilon,t_0,t$, the initial data, and the solution. As a result, by letting $\varepsilon \to 0^+$ and using that $v_\varepsilon = \frac{v}{1+\varepsilon v}$ so that $v_\varepsilon \to v$ a.e., we get 
\begin{equation*}
    \operatorname*{ess \, inf}_{(t_0,t)} u \geq C^{-1} e^{-Ct} \Vert v_0 \Vert_{L^\infty}^{-1} \qquad \forall t > t_0, 
\end{equation*}
which, by rewriting in terms of $u(t_0,\cdot)$ as per \eqref{eq:lower bound in proof of propagation}, yields the required result.

We cannot test \eqref{eq:p eq} with ${\bf p}$, since  it is not known to be an admissible test function. Instead, we consider smoothed approximations of ${\bf p}$ and argue similarly to \cite[Lemma 4.2]{reg2}.

    \smallskip 

    \noindent 1. \textit{Approximation}. Let $\eta$ be the usual Friedrichs bump function, and $\{\eta^\varepsilon\}_{\varepsilon>0}$ the usual sequence of Friedrichs mollifiers in $\mathbb{R}^2$; we only smooth in the $x$ variable. Let ${\bf p}^\varepsilon = \eta^\varepsilon*{\bf p}$, and define $D = (1-\rho){\bf P}$ and its approximation $D^\varepsilon = \eta^\varepsilon*D$. We insert $\eta^\varepsilon(s,x-y)$ as test function in \eqref{eq:p eq} and integrate in $y$ over $\mathbb{R}^2$---this is the same as mollifying \eqref{eq:p eq}---and get 
    \begin{equation}\label{eq:mollified p eqn}
        \partial_t {\bf p}^\varepsilon + \operatorname{div} D^\varepsilon = \operatorname{div}((1-\rho)\nabla{\bf p}^\varepsilon + {\bf p}^\varepsilon \otimes \nabla \rho) - {\bf p}^\varepsilon + \operatorname{div} (E^\varepsilon + F^\varepsilon), 
    \end{equation}
    where $E^\varepsilon = \eta^\varepsilon*((1-\rho)\nabla {\bf p}) - (1-\rho)\eta^\varepsilon*\nabla {\bf p}$ and $F^\varepsilon = \eta^\varepsilon*({\bf p} \otimes \nabla \rho) - (\eta^\varepsilon*{\bf p} )\otimes \nabla \rho. $

    \smallskip 

    \noindent 2. \textit{Error control}. We show that for some $C_T$ independent of $\varepsilon,t$ (but which depends on $T$), 
    \begin{equation}\label{eq:unif bounds for H1 for p with mollifications}
        \Vert D^\varepsilon \Vert_{L^\infty([0,T]\times\mathbb{T}^2)} + \Vert E^\varepsilon \Vert_{L^2([0,T]\times\mathbb{T}^2)} + \Vert F^\varepsilon \Vert_{L^2([0,T]\times\mathbb{T}^2)} \leq C_T. 
    \end{equation}
   To begin with, for a.e.~$s\in (t,T)$ it holds $\Vert D^\varepsilon (s) \Vert_{L^\infty(\mathbb{T}^2)} \leq  \Vert D(s) \Vert_{L^\infty(\mathbb{T}^2)} \leq  \Vert {\bf P} \Vert_{L^\infty} \leq C,$ for some positive constant $C$ independent of $\varepsilon,t,T$, using standard properties of the mollifier in the first inequality. The first part of \eqref{eq:unif bounds for H1 for p with mollifications} follows. Next, we estimate $F^\varepsilon$: directly from basic properties of the mollifier sequence, we have for a.e.~$s \in (t,T)$
\begin{equation*}
    \Vert \eta^\varepsilon*({\bf p} \otimes \nabla \rho)(s) \Vert_{L^2(\mathbb{T}^2)} \leq C \Vert ({\bf p} \otimes \nabla \rho) (s) \Vert_{L^2(\mathbb{T}^2)} \leq C \Vert {\bf p} \Vert_{L^\infty } \Vert \nabla \rho(s) \Vert_{L^2(\Omega)}, 
\end{equation*}
for some positive constant $C$ independent of $\varepsilon,t,T$, and analogously 
\begin{equation*}
    \Vert (\eta^\varepsilon*{\bf p} )\otimes \nabla \rho (s) \Vert_{L^2(\mathbb{T}^2)} \!\leq\! \Vert (\eta^\varepsilon*{\bf p} )(s) \Vert_{L^\infty(\mathbb{T}^2)}\Vert \nabla \rho(s) \Vert_{L^2(\mathbb{T}^2)} \!\leq\! \Vert {\bf p} \Vert_{L^\infty} \Vert \nabla \rho(s) \Vert_{L^2(\mathbb{T}^2)}, 
\end{equation*}
thus, by integrating in time, there is a positive $C_T=C\Vert \nabla \rho\Vert_{L^2([0,T]\times\mathbb{T}^2)}$ independent of $\varepsilon,t$ such that $\Vert F^\varepsilon \Vert_{L^2([0,T]\times\mathbb{T}^2)} \leq C_T$, whence the final term in \eqref{eq:unif bounds for H1 for p with mollifications} is bounded. 


The final error term $E^\varepsilon$ is written $E^\varepsilon(s,x) = \int_{\mathbb{R}^2} \eta^\varepsilon(x-y)\big[ \rho(s,x)-\rho(s,y) \big]\nabla{\bf p}(t,y) \, \mathrm{d}  y$, and---by integrating by parts---admits the two-term decomposition 
\begin{equation*}
   \begin{aligned}
       E^\varepsilon(s,x) =\!\!  \underbrace{\int_{\mathbb{R}^2} \!\!{\bf p}(s,y) \otimes \nabla \eta^\varepsilon(x\!-\!y) \big[ \rho(s,x)\!-\!\rho(s,y) \big] \, \mathrm{d}  y}_{=: E^\varepsilon_1(s,x)} + \!\underbrace{\int_{\mathbb{R}^2} \!\!\eta^\varepsilon(x\!-\!y) {\bf p}(s,y) \otimes \nabla \rho(s,y) \, \mathrm{d}  y}_{=: E^\varepsilon_2(s,x)} . 
   \end{aligned} 
\end{equation*}
Using standard properties of mollifiers, $\Vert E^\varepsilon_2(s) \Vert_{L^2(\mathbb{T}^2)} \leq C \Vert \nabla \rho(s) \Vert_{L^2(\mathbb{T}^2)} \Vert {\bf p} \Vert_{L^\infty},$ thus 
\begin{equation}\label{eq:Eeps2 bound unif}
    \Vert E^\varepsilon_2 \Vert_{L^2([0,T]\times\mathbb{T}^2)} \leq C \Vert \nabla \rho \Vert_{L^2([0,T]\times\mathbb{T}^2)}  , 
\end{equation}
for some  $C$ independent of $\varepsilon,t,T$. Meanwhile, for a.e.~$x\in \mathbb{R}^2$ and $y \in \operatorname{\mathrm{supp}} \eta^\varepsilon(x-\cdot)$,
\begin{equation*}
   \begin{aligned} 
 | \rho(s,x)-\rho(s,y) |= \bigg|\int_0^1 \frac{\mathrm{d}}{\mathrm{d} \sigma}\rho(s,\sigma x \!+\!(1\!-\!\sigma)y)  \, \mathrm{d}  \sigma\bigg| &= \bigg|\int_0^1 \nabla \rho(s,\sigma x \!+\!(1\!-\!\sigma)y) \!\cdot\! (x-y)  \, \mathrm{d}  \sigma \bigg| \\ 
 &\leq \varepsilon \int_0^1 |\nabla \rho(s,\sigma x +(1-\sigma)y)| \, \mathrm{d}  \sigma,  
   \end{aligned}
\end{equation*}
using $\operatorname{\mathrm{supp}} \eta^\varepsilon = B(0,\varepsilon)$ to bound $|x-y|\leq \varepsilon$. The boundedness of ${\bf p}$ then implies 
\begin{equation*}
    \begin{aligned}
       | E^\varepsilon_1(s,x) | &\leq \varepsilon^{-2} \int_{B(x,\varepsilon)} \big|\nabla \eta(\frac{x-y}{\varepsilon}) \big| \bigg(  \int_0^1 |\nabla \rho(s,\sigma x +(1-\sigma)y)| \, \mathrm{d}  \sigma\bigg) \, \mathrm{d}  y \\ 
        &= \int_{B(0,1)} |\nabla \eta (w)| \bigg(  \int_0^1 |\nabla \rho \big(s, x - (1-\sigma)\varepsilon w \big)| \, \mathrm{d}  \sigma\bigg) \, \mathrm{d}  w, 
    \end{aligned}
\end{equation*}
and, by Jensen's inequality, we get $|E^\varepsilon_1(s,x)|^2 \leq C \int_{B(0,1)} \int_0^1 |\nabla \rho (s, x - (1-\sigma)\varepsilon w )|^2 \, \mathrm{d}  \sigma \, \mathrm{d}  w$, for some positive constant $C$ independent of $\varepsilon,t,T$. The Fubini--Tonelli Theorem then implies, using the periodicity of $\nabla \rho$ and translation invariance of Lebesgue measure, 
\begin{equation*}
    \Vert E^\varepsilon_1(s) \Vert^2_{L^2(\mathbb{T}^2)} \leq C \int_{B(0,1)} \int_0^1 \int_{\mathbb{T}^2} |\nabla \rho(s,x)|^2 \, \mathrm{d}  x \, \mathrm{d}  \sigma \, \mathrm{d}  w \leq C \Vert \nabla \rho(s) \Vert^2_{L^2(\mathbb{T}^2)}. 
\end{equation*}
By integrating in time, and combining with \eqref{eq:Eeps2 bound unif}, we deduce $\Vert E^\varepsilon \Vert_{L^2([0,T]\times\mathbb{T}^2)} \leq C_T$. 

\smallskip 

    \noindent 3. \textit{$H^1$ bound on ${\bf p}$}. ${\bf p}^\varepsilon \in L^\infty(t,T;C^\infty(\mathbb{T}^2))$ is an admissible test function for \eqref{eq:mollified p eqn}. Furthermore, it is immediate from \eqref{eq:mollified p eqn} that $\partial_t {\bf p}^\varepsilon \in L^2((t,T);H^{-1}(\mathbb{T}^2))$ whence the Lions--Magenes Lemma applies and $\langle \partial_t {\bf p}^\varepsilon,{\bf p}^\varepsilon\rangle = \frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t} \Vert {\bf p}^\varepsilon\Vert^2_{L^2}$. By \eqref{eq:unif bounds for H1 for p with mollifications} and Young's inequality, 
    \begin{equation*}
        \begin{aligned}
             \Vert {\bf p}^\varepsilon(s)\Vert^2_{L^2(\mathbb{T}^2)} \!+\!  c_{t,T} \int_t^{s} \int_{\mathbb{T}^2} |\nabla {\bf p}^\varepsilon|^2 \, \mathrm{d}  x \, \mathrm{d}  s' \leq \Vert {\bf p}^\varepsilon(t)\Vert^2_{L^2(\mathbb{T}^2)} \!+\! \frac{C_T^2}{c_{t,T}} \!+\!  2 c_{t,T}^{-1} \Vert \nabla \rho \Vert^2_{L^2([0,s]\times\mathbb{T}^2)}, 
        \end{aligned}
    \end{equation*}
for all $t<s\leq T$, using also $\Vert {\bf p}^\varepsilon(t)\Vert_{L^\infty(\mathbb{T}^2)} \leq C \Vert {\bf p}(t)\Vert_{L^\infty(\mathbb{T}^2)} \leq C$. We deduce 
    \begin{equation}\label{eq:just before H1 final bound for p}
        \begin{aligned}
            \Vert {\bf p}^\varepsilon\Vert_{L^\infty((t,T);L^2(\mathbb{T}^2))}^2 +  \Vert \nabla {\bf p}^\varepsilon\Vert_{L^2((t,T)\times\mathbb{T}^2)}^2 &\leq C_{t,T}', 
        \end{aligned}
    \end{equation}
    for some $C_{t,T}'$ independent of $\varepsilon$. We let $\varepsilon \to 0$, and the required boundedness of $\nabla {\bf p}$ follows from the lower semicontinuity of the norms. Finally, $\partial_t {\bf p} \in L^2((t,T);H^{-1}(\mathbb{T}^2))$ from \eqref{eq:p eq}. 

    \smallskip 

    \noindent 4. \textit{$L^4$ bound on $\nabla\rho$}. 
It now follows from equation \eqref{eq:rho eq} that $\partial_t \rho - \Delta \rho = - \operatorname{div}((1-\rho){\bf p}) \in L^2((t',T')\!\times\!\mathbb{T}^2)$ for all $0\!<\!t'\!<\!T'$, thus the Calder\'on--Zygmund Theorem yields 
\begin{equation}\label{eq:dt rho and laplace rho in L2loc}
    \partial_t \rho , \nabla^2 \rho \in L^2((t,T) \! \times \! \mathbb{T}^2) \qquad \forall 0<t<T<\infty. 
\end{equation}
Thus, we may rigorously perform the standard $H^2$ estimate on \eqref{eq:rho eq} by testing against $\Delta \rho$, which yields $\frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t}\Vert \nabla \rho\Vert_{L^2(\mathbb{T}^2)}^2  + \frac{1}{2}\Vert \nabla^2 \rho\Vert_{L^2(\mathbb{T}^2)}^2 \leq \frac{1}{2} \Vert \operatorname{div}((1-\rho){\bf p}) \Vert_{L^2(\mathbb{T}^2)}^2$, \textit{i.e.}, 
    \begin{equation}\label{eq:grad rho in Linft L2}
        \nabla \rho \in L^\infty((t,T);L^2(\mathbb{T}^2)) \qquad \forall 0 < t < T<\infty. 
    \end{equation}
    It follows from \eqref{eq:grad rho in Linft L2} and \eqref{eq:dt rho and laplace rho in L2loc} that $\nabla \rho$ satisfies the assumptions of the interpolation Lemma \ref{lem:dibenedetto classic},  which yields $\nabla \rho \in L^4((t,T)\!\times\!\mathbb{T}^2)$ for all $0<t<T<\infty$.

\label{cor:consequence of gehring}
    For all $0\!<\!t\!<\!T\!<\!\infty$, $\exists \delta>0$ depending only on $t,T,c_{t,T}$, such that 
    \begin{equation*}
        \nabla {\bf p} \in L^{2+\delta}((t,T)\!\times\!\mathbb{T}^2), \quad \partial_t \rho, \nabla^2 \rho \in L^{2+\delta}((t,T)\!\times\!\mathbb{T}^2), \quad  \nabla \rho \in L^{2+\delta}((t,T);L^\infty(\mathbb{T}^2)). 
    \end{equation*}

\label{prop:galerkin p}
    For all $n\in\mathbb{N}$, $\exists {\bf p}^n \in AC([t,T];C^\infty(\mathbb{T}^2))$ satisfying 
    \begin{equation}\label{eq:galerkin approx 1}
    \left\lbrace \begin{aligned} 
        &\partial_t {\bf p}^n - \operatorname{div}((1-\rho)\nabla {\bf p}^n + {\bf p}^n \otimes \nabla \rho) + {\bf p}^n = - \operatorname{div}((1-\rho){\bf P}), \\ 
        &{\bf p}^n(t) = \sum_{j=1}^n \langle {\bf p}(t),\varphi_j \rangle \varphi_j, 
    \end{aligned}\right. 
\end{equation}
in the weak sense dual to $\mathrm{span}\{\varphi_j\}_{j=1}^n$ for all $s \in [t,T]$, with the initial data achieved in the strong $L^2$-sense. Furthermore, ${\bf p}^n \rightharpoonup {\bf p} $ weakly in $L^2((t,T);H^2(\mathbb{T}^2))$, 
and 
\begin{equation}\label{eq:n indep bounds galerkin p}
\sup_n \Vert {\bf p}^n \Vert_{L^\infty((t,T);L^2(\mathbb{T}^2))} + \sup_n \Vert \nabla {\bf p}^n \Vert_{L^2((t,T)\!\times\!\mathbb{T}^2)} + \sup_n \Vert \nabla^2 {\bf p}^n \Vert_{L^2((t,T)\!\times\!\mathbb{T}^2)} < \infty. 
\end{equation}

We divide the proof into several steps. 

\smallskip 

 \noindent 1. \textit{Existence of ${\bf p}^n$}. Exploiting the orthonormality of the eigenfunctions and testing \eqref{eq:galerkin approx 1} with $\varphi_j$, we see that \eqref{eq:galerkin approx 1} is satisfied by the ansatz \eqref{eq:ansatz p n} in duality with $\mathrm{span}\{\varphi_j\}_{j=1}^n$ if 
   \begin{equation*}
    \begin{aligned}
        \frac{\mathrm{d} \boldsymbol{\alpha}^n_{j}}{\mathrm{d} t}  \!+\! \sum_{k=1}^n  \boldsymbol{\alpha}^n_{k} \bigg( \int_{\mathbb{T}^2} \Big( (1\!-\!\rho) \nabla \varphi_k + \varphi_k \nabla \rho \Big) \!\cdot\! \nabla\varphi_{j} \, \mathrm{d}  x \bigg) \!+\! \boldsymbol{\alpha}^n_j = \int_{\mathbb{T}^2}\!\!   (1-\rho){\bf P}   \nabla \varphi_j  \, \mathrm{d}  x. 
    \end{aligned}
\end{equation*}
The above reads as a linear system of ODEs, of the form $\boldsymbol{\alpha}'(s) + A(s)\boldsymbol{\alpha}(s) = B(s)$, where the tensors $A,B$ are sufficiently regular that the standard well-posedness theory applies---no assumptions on the invertibility/definiteness of $A$ are needed. Specifically, $A(s),B(s)$ are \emph{locally integrable} in the time variable $s$, thus an application of Carath\'eodory's Theorem implies that there exists ${\bf p}^n \in AC([t,T];C^\infty(\mathbb{T}^2))$ solving \eqref{eq:galerkin approx 1} in duality with $\mathrm{span}\{\varphi_j\}_{j=1}^n$ (of the form \eqref{eq:ansatz p n}), with the initial data achieved in $L^2(\mathbb{T}^2)$ at $s=t$.    

\smallskip 


\noindent 2. \textit{Estimates independent of $n$}. By testing \eqref{eq:galerkin approx 1} with ${\bf p}^n$ (this is allowed since ${\bf p}^n(s) \in \mathrm{span}\{\varphi_j\}_{j=1}^n$), we get the usual $H^1$-type estimate $\frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t}\Vert {\bf p}^n \Vert^2_{L^2(\mathbb{T}^2)} + \frac{c_{t,T}}{2}\Vert \nabla {\bf p}^n \Vert^2_{L^2(\mathbb{T}^2)} + \Vert {\bf p}^n \Vert^2_{L^2(\mathbb{T}^2)} \leq \frac{1}{c_{t,T}}(\Vert (1-\rho){\bf P} \Vert^2_{L^2(\mathbb{T}^2)} + \Vert {\bf p}^n |\nabla \rho| \Vert^2_{L^2(\mathbb{T}^2)})$, where we used the lower bound on $1-\rho$ provided by $c_{t,T}$ and the Lions--Magenes Lemma (directly from the equation $\partial_t {\bf p}^n \in L^2((t,T);\mathrm{span}\{\varphi_j\}_{j=1}^n)$ since $\mathrm{span}\{\varphi_j\}_{j=1}^n$ is a finite-dimensional Hilbert space). Integrating in time yields (for all $t < s \leq T$) 
\begin{equation*}
   \begin{aligned} \Vert {\bf p}^n(s) \Vert^2_{L^2(\mathbb{T}^2)} + c_{t,T} \Vert \nabla {\bf p}^n \Vert^2_{L^2((t,s)\times\mathbb{T}^2)}  \leq & \,  \Vert {\bf p}^n(t) \Vert^2_{L^2(\mathbb{T}^2)} + c_{t,T}^{-1}\Vert (1-\rho){\bf P} \Vert^2_{L^2((t,T)\times\mathbb{T}^2)} \\ 
   &+ c_{t,T}^{-1} \int_t^s \Vert \nabla \rho(s') \Vert_{L^\infty(\mathbb{T}^2)}^2 \Vert {\bf p}^n(s') \Vert^2_{L^2(\mathbb{T}^2)} \, \mathrm{d}  s', 
   \end{aligned}
\end{equation*}
where we dropped the positive term $\Vert {\bf p}^n \Vert^2_{L^2((t,T)\times\mathbb{T}^2)}$ on the left-hand side. Due to the strong convergence of initial data \eqref{eq:conv of initial data for galerkin ii}, we see that the  first two terms on the right-hand side are bounded independently of $n$ by some $C_{t,T}$ depending only on $t,T,c_{t,T}$. We get 
\begin{equation*}
    \Vert {\bf p}^n(s) \Vert^2_{L^2(\mathbb{T}^2)} + \Vert \nabla {\bf p}^n \Vert^2_{L^2((t,s)\times\mathbb{T}^2)}  \leq  C_{t,T} \bigg( 1+ \int_t^s \Vert \nabla \rho(s') \Vert_{L^\infty(\mathbb{T}^2)}^2 \Vert {\bf p}^n(s') \Vert^2_{L^2(\mathbb{T}^2)} \, \mathrm{d}  s' \bigg), 
\end{equation*}
and an application Gr\"onwall's Lemma implies (for a different constant $C_{t,T}$) 
\begin{equation*}
    \Vert {\bf p}^n \Vert^2_{L^\infty((t,T);L^2(\mathbb{T}^2))} + c_{t,T} \Vert \nabla {\bf p}^n \Vert^2_{L^2((t,T)\times\mathbb{T}^2)}  \leq C_{t,T} \exp \bigg( C_{t,T} \int_t^T \Vert \nabla \rho(s') \Vert_{L^\infty(\mathbb{T}^2)}^2  \, \mathrm{d}  s' \bigg), 
\end{equation*}
where the integral is bounded since $\nabla \rho \in L^{2+\delta}((t,T);L^\infty(\mathbb{T}^2))$ for some $\delta>0$ depending on $t,T,c_{t,T}$ by Corollary \ref{cor:consequence of gehring}, and the boundedness of the first two terms in \eqref{eq:n indep bounds galerkin p} follows. 

Next, we perform the $H^2$-type estimate by testing \eqref{eq:galerkin approx 1} with $\Delta {\bf p}^n$ (this is allowed since $\Delta {\bf p}^n \in \mathrm{span}\{\varphi_j\}_{j=1}^n$ due to \eqref{eq:relation for eig}). Since ${\bf p}^n(s) \in C^\infty(\mathbb{T}^2)$, we rigorously pass to the non-divergence form of \eqref{eq:galerkin approx 1}. Similarly to the computation \eqref{eq:formal computation before galerkin}, we get 
\begin{equation*}
\begin{aligned}
\frac{\mathrm{d}}{\mathrm{d} t}\Vert \nabla {\bf p} \Vert^2_{L^2(\mathbb{T}^2)} \!+\! \frac{c_{t,T}}{2}\Vert \Delta & {\bf p} \Vert_{L^2(\mathbb{T}^2)}^2 \leq c_{t,T}^{-1}\Big( \Vert \operatorname{div}((1\!-\!\rho){\bf P}) \Vert^2_{L^2(\mathbb{T}^2)} \!+\! 2\int_{\mathbb{T}^2} |{\bf p}^n|^2 |\Delta \rho|^2 \, \mathrm{d}  x \Big) \\ 
&\leq c_{t,T}^{-1}\Big( \Vert \operatorname{div}((1\!-\!\rho){\bf P}) \Vert^2_{L^2(\mathbb{T}^2)} \!+\! 2  \Vert {\bf p}^n(s) \Vert^2_{L^{q_\delta}(\mathbb{T}^2)} \Vert \Delta \rho(s) \Vert_{L^{2+\delta}(\mathbb{T}^2)}^2\Big), 
\end{aligned}
\end{equation*}
using the Lions--Magenes Lemma in the finite-dimensional Hilbert space $\{\varphi_j\}_{j=1}^n$, where the final term is present because \emph{a priori} we do not know ${\bf p}^n \in L^\infty$, unlike ${\bf p}$; we recall that $q_\delta$ defined in \eqref{def: q delta} depends on $t,T,c_{t,T}$. Next, the Sobolev inequality implies $\Vert {\bf p}^n(s) \Vert_{L^{q_\delta}(\mathbb{T}^2)} \leq C_S \Vert {\bf p}^n(s) \Vert_{H^1(\mathbb{T}^2)}$ for some $C_S$ independent of $n$ but which depends on $t,T,c_{t,T}$ (since $q_{\delta}$ does). Integrating in $s$ and using $\nabla {\bf P} \in L^2_\mathrm{loc}$ from Lemma \ref{lem:H1 for P}, we get 
\begin{equation*}
   \begin{aligned}
       \Vert \nabla{\bf p}^n(s) \Vert^2_{L^2(\mathbb{T}^2)} \!+\! c_{t,T} \Vert \Delta {\bf p}^n \Vert^2_{L^2((t,s)\times\mathbb{T}^2)}  \leq \Vert \nabla{\bf p}^n(t) \Vert^2_{L^2(\mathbb{T}^2)} \!+\! c_{t,T}^{-1}\Vert \operatorname{div}((1\!-\!\rho){\bf P}) \Vert^2_{L^2} & \\ 
       + 4 C_S^2 c_{t,T}^{-1} \Vert {\bf p}^n \Vert^2_{L^\infty((t,T);L^2(\mathbb{T}^2))} \Vert \Delta \rho \Vert^2_{L^2((t,T);L^{2+\delta}(\mathbb{T}^2))} & \\ 
       + 4 C_S^2 c_{t,T}^{-1} \int_t^s \Vert \Delta \rho(s') \Vert^2_{L^{2+\delta}(\mathbb{T}^2)} \Vert \nabla {\bf p}^n (s') \Vert^2_{L^2(\mathbb{T}^2)} \, \mathrm{d}  s' &  
   \end{aligned} 
\end{equation*}
for all $t < s \leq T$. The strong convergence to the initial data \eqref{eq:conv of initial data for galerkin}, the uniform bound on $\Vert {\bf p}^n \Vert_{L^\infty((t,T);L^2(\mathbb{T}^2))}$, and Corollary \ref{cor:consequence of gehring} implies that there exists $C_{t,T}$ independent of $n$ such that the first three terms on the previous right-hand side are bounded by $C_{t,T}$. We deduce 
\begin{equation*}
    \Vert \nabla{\bf p}^n(s) \Vert^2_{L^2(\mathbb{T}^2)} \!+ c_{t,T} \Vert \Delta {\bf p}^n \Vert^2_{L^2((t,s)\times\mathbb{T}^2)} \leq C_{t,T} \Big(1 \!+\! \int_t^s \!\! \Vert \Delta \rho(s') \Vert^2_{L^{2+\delta}(\mathbb{T}^2)} \Vert \nabla {\bf p}^n (s') \Vert^2_{L^2(\mathbb{T}^2)} \, \mathrm{d}  s' \Big), 
\end{equation*}
for some $C_{t,T}$ independent of $n$, whence an application of Gr\"onwall's Lemma implies 
\begin{equation*}
    \Vert \nabla{\bf p}^n \Vert^2_{L^\infty((t,T);L^2(\mathbb{T}^2))} \!+\! c_{t,T} \Vert \Delta {\bf p}^n \Vert^2_{L^2((t,T)\times\mathbb{T}^2)} \leq C_{t,T} \exp \Big( C_{t,T} \int_t^T \Vert \Delta \rho(s') \Vert^2_{L^{2+\delta}(\mathbb{T}^2)} \, \mathrm{d}  s' \Big), 
\end{equation*}
for a different $C_{t,T}$; the final integral is bounded due to Corollary \ref{cor:consequence of gehring}. Thus \eqref{eq:n indep bounds galerkin p} follows. 


\smallskip 

\noindent 3. \textit{Convergence to ${\bf p}$}. The uniform bounds \eqref{eq:n indep bounds galerkin p} imply that $\{{\bf p}^n\}_n$ is a uniformly bounded sequence in $L^2((t,T);H^2(\mathbb{T}^2))$. As such, by Alaoglu's Theorem, it admits a weakly convergent limit ${\bf p}^\infty \in L^2((t,T);H^2(\mathbb{T}^2))$ for a subsequence which we do not relabel. By passing to the limit in the \emph{linear} equation \eqref{eq:galerkin approx 1}, we see that ${\bf p}^\infty$ satisfies 
    \begin{equation}\label{eq:galerkin approx 1 limit}
    \left\lbrace \begin{aligned} 
        &\partial_t {\bf p}^\infty - \operatorname{div}((1-\rho)\nabla {\bf p}^\infty + {\bf p}^\infty \otimes \nabla \rho) + {\bf p}^\infty = - \operatorname{div}((1-\rho){\bf P}), \\ 
        &{\bf p}^\infty(t) = {\bf p}(t), 
    \end{aligned}\right. 
\end{equation}
where we used that ${\bf p} = \sum_{j=1}^\infty \langle {\bf p}(t),\varphi_j \rangle \varphi_j$ in $L^2(\mathbb{T}^2)$ from \eqref{eq:conv of initial data for galerkin}. The equation \eqref{eq:galerkin approx 1 limit} holds in duality with $L^2((t,T);\mathrm{span}\{\varphi_j\}_{j=1}^\infty)$, and hence, by density, in duality with $L^2((t,T);H^1(\mathbb{T}^2))$; we also deduce directly from \eqref{eq:galerkin approx 1 limit} that $\partial_t {\bf p}^\infty \in L^2((t,T);H^{-1}(\mathbb{T}^2))$. Next, we define the difference $\mathbf{w} := {\bf p}^\infty - {\bf p}$. On account of ${\bf p},{\bf p}^\infty \in L^2((t,T);H^1(\mathbb{T}^2))$, from Lemma \ref{lem:H1 p}, we have that $\mathbf{w}$ satisfies 
\begin{equation*}
    \partial_t \mathbf{w} - \operatorname{div}((1-\rho)\nabla \mathbf{w} + \mathbf{w} \otimes \nabla \rho) + \mathbf{w} = 0, 
\end{equation*}
with zero initial condition, and $\mathbf{w}$ is itself an admissible test function for this equation with $\partial_t \mathbf{w}\in L^2((t,T);H^{-1}(\mathbb{T}^2))$. The Lions--Magenes Lemma applies, and testing with $\mathbf{w}$ gives 
\begin{equation*}
    \begin{aligned}
        \frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t}\Vert \mathbf{w} \Vert^2_{L^2(\mathbb{T}^2)} \!+\! \frac{c_{t,T}}{2}\Vert \nabla \mathbf{w} \Vert^2_{L^2(\mathbb{T}^2)} \!+\! \Vert \mathbf{w} \Vert^2_{L^2(\mathbb{T}^2)} \leq \frac{1}{2c_{t,T}} \Vert \mathbf{w} \!\otimes\! \nabla \rho \Vert^2_{L^2}\leq \frac{1}{2c_{t,T}} \Vert \nabla \rho \Vert_{L^\infty}^2 \Vert \mathbf{w} \Vert^2_{L^2}. 
    \end{aligned}
\end{equation*}
Writing $Y(s) := \Vert \mathbf{w}(s)\Vert^2_{L^2(\mathbb{T}^2)}$, this implies $Y'(s) \leq c_{t,T}^{-1} \Vert \nabla \rho(s) \Vert^2_{L^\infty(\mathbb{T}^2)} Y(s)$, and hence
\begin{equation*}
    Y(s) \leq {Y(t)}\exp\bigg( c_{t,T}^{-1} \int_t^T \Vert \nabla \rho(s') \Vert^2_{L^\infty(\mathbb{T}^2)} \, \mathrm{d}  s' \bigg) = 0 \qquad \forall s \in [t,T], 
\end{equation*}
since $Y(t)=0$, where the integral is finite since $\nabla \rho \in L^{2+\delta}((t,T);L^\infty(\mathbb{T}^2))$ for some $\delta>0$ depending on $t,T,c_{t,T}$ (Corollary \ref{cor:consequence of gehring}). Hence ${\bf p} = {\bf p}^\infty \in L^2((t,T);H^2(\mathbb{T}^2))$.

\label{cor:continuity rho and hess in L4 nabla rho L8}
    For all $0<t<T<\infty$, it holds 
    \begin{equation*}
        \partial_t \rho,\nabla^2 \rho \in L^4((t,T)\!\times\!\mathbb{T}^2), \quad \nabla \rho \in L^8((t,T)\!\times\!\mathbb{T}^2), \quad \rho \in C^{\nicefrac{1}{4}}([t,T]\!\times\!\mathbb{T}^2). 
    \end{equation*}

Our objective is, as usual, to test the equation \eqref{eq:main eqn} against $f$, which gives the result formally. However, \emph{a priori} $f$ is not regular enough to be a test function. To this end, similarly to Lemma \ref{lem:H1 p}, we introduce the $\xi$-mollifier sequence $\{\eta^\varepsilon\}_\varepsilon$ in $\mathbb{R}^3$ constructed from the Friedrichs bump function. Define $D=(1-\rho) f {\bf e}(\theta)$ and $D^\varepsilon = \eta^\varepsilon*D$. Inserting $\eta^\varepsilon(s,\xi-y)$ into the weak formulation of \eqref{eq:main eqn} and integrating in $y$, we get 

    \begin{equation}\label{eq:mollified f eqn}
        \partial_t f^\varepsilon + \operatorname{div} D^\varepsilon = \operatorname{div}((1-\rho)\nabla f^\varepsilon + f^\varepsilon \nabla \rho) +\partial_\theta^2 f^\varepsilon + \operatorname{div} (E^\varepsilon + F^\varepsilon), 
    \end{equation}
    where $E^\varepsilon = \eta^\varepsilon*((1-\rho)\nabla f) - (1-\rho)\eta^\varepsilon*\nabla f$ and $F^\varepsilon = \eta^\varepsilon*(f \nabla \rho) - (\eta^\varepsilon* f ) \nabla \rho. $

    \smallskip 

    \noindent 1. \textit{Control of error terms}. Using that $f \in L^3_{t,\xi}$ from Definition \ref{def:function space}, standard properties of the mollifier imply that $\Vert D^\varepsilon \Vert_{L^3([t,T]\times\mathbb{T}^3)} \leq C \Vert D \Vert_{L^3([t,T]\times\mathbb{T}^3)} \leq C\Vert f \Vert_{L^3([t,T]\times\mathbb{T}^3)}$, where the constant $C$ is independent of $t,T,\varepsilon$. Similarly, for the term $F^\varepsilon$, we have $\Vert \eta^\varepsilon*(f\nabla \rho)(s) \Vert_{L^2(\mathbb{T}^3)} \leq C \Vert f\nabla \rho(s) \Vert_{L^2(\mathbb{T}^3)} \leq C\Vert f (s)\Vert_{L^3(\mathbb{T}^2)} \Vert \nabla \rho(s) \Vert_{L^6(\mathbb{T}^2)}$, whence squaring and using Young's inequality with the exponent $\nicefrac{3}{2}$ yields $\Vert \eta^\varepsilon*(f\nabla \rho) \Vert_{L^2([t,T]\times\mathbb{T}^3)}^2 \leq C(\Vert f \Vert_{L^3([t,T]\times\mathbb{T}^2)}^3 + \Vert \nabla \rho \Vert^6_{L^6([t,T]\times\mathbb{T}^2)})$, where the constant $C$ is independent of $t,T,\varepsilon$; the final term is bounded in view of Corollary \ref{cor:continuity rho and hess in L4 nabla rho L8}. The second term in $F^\varepsilon$ is controlled analgously, whence we deduce $ \Vert D^\varepsilon \Vert_{L^2([t,T]\times\mathbb{T}^2)} + \Vert F^\varepsilon \Vert_{L^2([t,T]\times\mathbb{T}^2)} \leq C_{t,T}$ for some $C_{t,T}$ depending only on $t,T,c_{t,T}$. It remains to estimate $E^\varepsilon$, which, like in Lemma \ref{lem:H1 p}, we split into two parts. Standard computations (\textit{cf.~}Step 2 of the proof of Lemma \ref{lem:H1 p}) give 
    \begin{equation*}
   \begin{aligned}
       E^\varepsilon(s,\xi) =\!\!  \underbrace{\int_{\mathbb{R}^3} \!\!f(s,y) \nabla \eta^\varepsilon(\xi\!-\!y) \big[ \rho(s,\xi)\!-\!\rho(s,y) \big] \, \mathrm{d}  y}_{=: E^\varepsilon_1(s,\xi)} + \!\underbrace{\int_{\mathbb{R}^3} \!\!\eta^\varepsilon(\xi\!-\!y) f(s,y) \nabla \rho(s,y) \, \mathrm{d}  y}_{=: E^\varepsilon_2(s,\xi)} . 
   \end{aligned} 
\end{equation*}
We have $\Vert E_2^\varepsilon(s) \Vert_{L^2(\mathbb{T}^3)} \leq C \Vert f \nabla \rho(s) \Vert_{L^2(\mathbb{T}^2)}$ using standard properties of the mollifier (with $C$ independent of $t,T,\varepsilon$), which yields $\Vert E_2^\varepsilon \Vert_{L^2([t,T]\times\mathbb{T}^3)} \leq C_{t,T}$ using the same approach as for $F^\varepsilon$. For $E^\varepsilon_1$, an identical strategy to that in Step 2 of the proof of Lemma \ref{lem:H1 p} yields 
\begin{equation*}
    \begin{aligned}
       | E^\varepsilon_1(s,\xi) | &\leq \int_{B(0,1)} f(s,\xi-\varepsilon w) |\nabla \eta (w)| \bigg(  \int_0^1 |\nabla \rho \big(s, \xi - (1-\sigma)\varepsilon w \big)| \, \mathrm{d}  \sigma\bigg) \, \mathrm{d}  w. 
    \end{aligned}
\end{equation*}
By squaring, Jensen's inequality, integrating in $\xi$ and using Fubini's Theorem, we get 
\begin{equation*}
    \begin{aligned}
       \Vert E^\varepsilon_1(s) \Vert^2_{L^2(\mathbb{T}^3)} &\leq C \int_{B(0,1)} \int_0^1 \bigg( \int_{\mathbb{T}^3} |f(s,\xi-\varepsilon w)|^2  |\nabla \rho \big(s, \xi - (1-\sigma)\varepsilon w \big)|^2 \, \mathrm{d}  \xi  \bigg) \, \mathrm{d}  \sigma  \, \mathrm{d}  w , 
    \end{aligned}
\end{equation*}
where the constant $C$ depends only on $\Vert \nabla \eta \Vert_{L^\infty}$. Using H\"older's inequality (with exponent $\nicefrac{3}{2}$) and the translation invariance of Lebesgue measure, we deduce 
\begin{equation*}
    \begin{aligned}
       \Vert E^\varepsilon_1(s) \Vert^2_{L^2(\mathbb{T}^3)} &\leq C \Vert f(s)^2 \Vert_{L^{\nicefrac{3}{2}}(\mathbb{T}^3)} \Vert |\nabla \rho(s) |^2\Vert_{L^3(\mathbb{T}^2)} = C\Vert f(s) \Vert_{L^3(\mathbb{T}^3)}^2 \Vert \nabla \rho(s) \Vert_{L^6(\mathbb{T}^2)}^2 . 
    \end{aligned}
\end{equation*}
Young's inequality yields $\Vert E^\varepsilon_1 \Vert_{L^2([t,T]\times\mathbb{T}^3)}^2 \leq C(\Vert f \Vert_{L^3}^3 + \Vert \nabla \rho \Vert^6_{L^6})$. We have shown 
\begin{equation}\label{eq:unif eps bound f in parabolic space}
\Vert D^\varepsilon \Vert_{L^2([t,T]\times\mathbb{T}^2)}^2 + \Vert E^\varepsilon \Vert_{L^2([t,T]\times\mathbb{T}^2)}^2 + \Vert F^\varepsilon \Vert_{L^2([t,T]\times\mathbb{T}^2)}^2 \leq C_{t,T}
\end{equation}
for some $C_{t,T}$ depending only on $t,T,c_{t,T}$, and independent of $\varepsilon$. 

    \smallskip 

    \noindent 2. \textit{$H^1$ bound}. Note that it is clear from the previous bounds and the equation \eqref{eq:mollified f eqn} that $\partial_t f^\varepsilon \in L^2((t,T);H^{-1}(\mathbb{T}^3))$, and hence the use of the Lions--Magenes Lemma is justified. Testing \eqref{eq:mollified f eqn} with $f^\varepsilon$, we get, using \eqref{eq:unif eps bound f in parabolic space}, the lower bound on $1\!-\!\rho$, and Young's inequality, 
    \begin{equation*}
        \frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t}\Vert f^\varepsilon \Vert^2_{L^2(\mathbb{T}^3)} + \frac{c_{t,T}}{4} \Vert \nabla_\xi f^\varepsilon\Vert^2_{L^2(\mathbb{T}^3)} \leq \frac{C_{t,T}}{2c_{t,T}} + c_{t,T}^{-1} \Vert f^\varepsilon\Vert^2_{L^3(\mathbb{T}^3)} \Vert \nabla \rho \Vert_{L^6(\mathbb{T}^2)}^2. 
    \end{equation*}
    By integrating in time, using that $\Vert f^\varepsilon(t) \Vert_{L^2(\mathbb{T}^3)} \leq C \Vert f(t) \Vert_{L^2(\mathbb{T}^3)} \leq C' \Vert f(t) \Vert_{L^3(\mathbb{T}^3)}$, which is finite by Definition \ref{def:function space}, we find that $\Vert f^\varepsilon \Vert^2_{L^\infty((t,T);L^2(\mathbb{T}^3))} + \Vert \nabla_\xi f^\varepsilon\Vert^2_{L^2((t,T)\times\mathbb{T}^3)}$ is bounded independently of $\varepsilon$. The result then follows from the lower semicontinuity of the norms, by letting $\varepsilon \to 0^+$; the equation \eqref{eq:main eqn} then yields $\partial_t f \in L^2((t,T);H^{-1}(\mathbb{T}^3))$.

Let $R \leq 1,s \in [t,T]$ be such that $Q_R(s)\subset [t,T]\!\times\!\mathbb{T}^3$. We show there exist $C_{t,T}$ (depending only on $t,T,c_{t,T}$) and $\beta>0$ (independent $t,T,s,R$), such that 
  \begin{equation}\label{eq:moser upper for f}
      \Vert f \Vert_{L^\infty(Q_r(s))} \leq \frac{C_{t,T}}{(R-r)^\beta} \qquad \forall 0<r<R, 
  \end{equation}
  from which the conclusion of the proposition follows immediately by a covering argument; recall that we are only interested in the \emph{qualitative} statement $f \in L^\infty_{t,\mathrm{loc}}L^\infty_\xi$. Without loss of generality (arguing by translation), we may assume $s=0$ for our cylinders: herein, 
  \begin{equation}\label{eq:the translated cylinders stuff}
      \operatorname*{ess \, inf}_{Q_R}(1\!-\!\rho) \geq c_{t,T} , \qquad \Vert \Delta \rho \Vert_{L^4(Q_R)} \leq \Vert \Delta \rho \Vert_{L^4((t,T)\times\mathbb{T}^2)}, 
  \end{equation}
  and the term involving $\Delta \rho$ is finite by Corollary \ref{cor:continuity rho and hess in L4 nabla rho L8}. 

  \smallskip 

  \noindent 1. \textit{Caccioppoli inequality}. Let $M>0,q \geq 2, 0<r<R\leq 1$. In this step, we prove 
\begin{equation}\label{eq:first checkpoint moser bis pour f}
   \begin{aligned}
      \Vert (f \wedge M)^{\frac{q}{2}} \Vert_{L^\infty((-r,r_;L^2(\mathbb{T}^3))}^2 + \Vert \nabla_\xi (f \wedge M)^{\frac{q}{2}} \Vert_{L^2(Q_r)}^2   \leq \frac{\kappa q^2}{R\!-\!r} \Vert f^{\frac{q}{2}} \Vert_{L^{\nicefrac{8}{3}}(Q_R)}^2 , 
   \end{aligned} 
\end{equation}
where $\kappa := C c_{t,T}^{-2} (1\!+\!\Vert \Delta \rho \Vert^2_{L^4((t,T)\times\mathbb{T}^3)} ) $ and the constant $C$ is independent of $q,M,c_{t,T},R,r$ and all other norms of $f$ and its averaged quantities (\textit{i.e.~}$\rho,{\bf p}$, \emph{etc.}). The final term on the right-hand side of \eqref{eq:first checkpoint moser bis pour f} is \emph{a priori} only finite for $2\leq q \leq \nicefrac{5}{2}$ by Lemma \ref{lem:f parabolic space}; nevertheless, the inequality remains true for all $q \geq 2$, with the possibility of this term being infinite.

Let $\psi \in C^\infty_c((-R,R))$ be a localising function (depending only on time) such that 
\begin{equation*}
    0 \leq \psi \leq 1 , \quad \psi|_{[-r,r]}=1, \quad \psi|_{[-1,1]\setminus[-R,R]}=0, \quad \Vert \partial_t \psi \Vert_{L^\infty((-1,1))} \leq \frac{C}{R-r},
    \end{equation*}
    for some constant $C$ independent of $r,R$. We wish to test \eqref{eq:main eqn} with $q (f\wedge M)^{q-1} \psi^2 \in L^2_{t,\mathrm{loc}}H^1_\xi$ by Lemma \ref{lem:f parabolic space}, since we \emph{formally expect} $\frac{\mathrm{d}}{\mathrm{d} t} \Vert (f \wedge M)^{\frac{q}{2}} \Vert^2_{L^2_\xi}=\langle \partial_t f , q (f \wedge M)^{q-1} \rangle$. However, since we only know $\partial_t f \in L^2_{t,\mathrm{loc}}H^{-1}_\xi$, there is no obvious non-linear chain rule for the pairing $\langle \partial_t f , q (f\wedge M)^{q-1}  \rangle$; the Lions--Magenes Lemma only applies when $q=2$. 

    A common strategy is to use \emph{Steklov averages} to bypass this: for all $h \in (0,1)$, define 
   \begin{equation}\label{eq:steklov def}
       f^h(s,\xi) := \frac{1}{h}\int_s^{s+h} f(s',\xi) \, \mathrm{d}  s' \implies \partial_t f^h(s,\xi) = \frac{f(s+h,\xi) - f(s,\xi)}{h} \qquad \text{a.e.} 
   \end{equation}
  We then obtain the evolution on $f^h$ from \eqref{eq:main eqn} by applying $\frac{1}{h}\int_s^{s+h}$ to the equation, \textit{i.e.}, 
   \begin{equation}\label{eq:steklov averaged eq}
       \partial_t f^h + \operatorname{div}( \big[(1-\rho) f \big]^h {\bf e}(\theta)) = \operatorname{div}( \big[ (1-\rho) \nabla f + f \nabla \rho \big]^h ) + \partial^2_\theta f^h. 
   \end{equation}
   Now we test \eqref{eq:steklov averaged eq} with $q (f^h \wedge M)^{q-1} \psi^2  $. By \eqref{eq:steklov def}, $\partial_t f^h \in L^3_\mathrm{loc}([0,\infty);L^3(\mathbb{T}^3))$, whence the usual chain rule for Sobolev functions applies (\textit{cf.}~\cite[\S 5.10]{Evans}), and we get 
   \begin{equation*}
       \langle \partial_t f^h , q (f^h \wedge M)^{q-1} \psi^2  \rangle = \frac{\mathrm{d}}{\mathrm{d} t} \int_{\mathbb{T}^3} \Phi_{M,q}(f^h) \psi^2 \, \mathrm{d}  \xi  - 2 \int_{\mathbb{T}^3} \psi \partial_t \psi \Phi_{M,q}(f^h) \, \mathrm{d}  \xi , 
   \end{equation*}
   where $\Phi_{M,q}(s) = \int_0^s q(r \!\wedge\! M)^{q-1} \, \mathrm{d}  r$. Observe that (for $q \geq 2$) this function satisfies $\frac{\mathrm{d}}{\mathrm{d} s}(s \wedge M)^q = q (s \wedge M)^{q-1} \mathds{1}_{\{0 \leq s \leq M\}} \leq q(s \wedge M)^{q-1} = \Phi'_{M,q}(s) \leq q s^{q-1} = \frac{\mathrm{d}}{\mathrm{d} s} s^q$, whence 
    \begin{equation}\label{eq:Phi for steklov}
      (s \wedge M)^q \leq \Phi_{M,q}(s) \leq s^q \qquad \forall s \geq 0. 
   \end{equation}
 Integrating in time over $[-R,s]$ for $s \in (-r,r)$, for which $\psi(s)=1$, $\psi(-R)=0$, we get 
   \begin{equation}\label{eq:steklov long}
       \begin{aligned}
           \int_{\mathbb{T}^3}\!&  \Phi_{M,q}(f^h(s)) \!+\! q(q\!-\!1) \!  \int_{-R}^s \!\int_{\mathbb{T}^3} \!\!\psi^2 (f^h\!\!\wedge\!M)^{q-2} \Big( \big[ (1\!-\!\rho) \nabla f \!+\! f \nabla \rho \big]^h \!\cdot\! \nabla f^h \!\!+\!    |\partial_\theta f^h|^2 \Big) \mathds{1}_{\{f^h < M\}} \\ 
           &\!= \!2\! \int_{-R}^s \! \int_{\mathbb{T}^3}\!\!  \psi \partial_t \psi \Phi_{M,q}(f^h) \!+\!  q(q\!-\!1) \! \int_{-R}^s \! \int_{\mathbb{T}^3} \!\! \psi^2 \big[(1-\rho) f \big]^h {\bf e}(\theta) \!\cdot\! (f^h \wedge M)^{q-2} \nabla f^h \mathds{1}_{\{f^h < M\}}. 
       \end{aligned}
   \end{equation}
   Standard results on Steklov averages (\textit{e.g.~}\cite[\S 1.3 Lemma 3.2]{DiBenedetto}) imply $\nabla_\xi f^h \to \nabla_\xi f$ and $[(1-\rho)\nabla f + f \nabla \rho]^h \to (1-\rho)\nabla f + f \nabla \rho$ strongly $L^2$ (by Lemma \ref{lem:f parabolic space}, Corollary \ref{cor:continuity rho and hess in L4 nabla rho L8}), hence 
   \begin{equation}\label{eq:steklov strong L1}
       \Big( [ (1\!-\!\rho) \nabla f \!+\! f \nabla \rho ]^h \!\cdot\! \nabla f^h \!+    |\partial_\theta f^h|^2 \Big) \to \Big( [ (1\!-\!\rho) \nabla f \!+\! f \nabla \rho ] \cdot\! \nabla f \!+    |\partial_\theta f|^2 \Big) \quad \text{strongly in } L^1. 
   \end{equation}
   Also, $f^h \to f$ strongly in $L^3$ and a.e.~(for a subsequence). Hence, $(f^h \!\wedge\! M)^{q-2} \mathds{1}_{\{f^h < M\}} \to (f\! \wedge\! M)^{q-2} \mathds{1}_{\{f < M\}} $ a.e.~and, since the term is bounded by $M^{q-2}$, the Dominated Convergence Theorem implies $\iint \psi^2 (f^h \wedge M)^{q-2} \mathds{1}_{\{f^h < M\}} \varphi \, \mathrm{d}  \xi \, \mathrm{d}  t \to \iint \psi^2 (f \wedge M)^{q-2} \mathds{1}_{\{f < M\}} \varphi \, \mathrm{d}  \xi \, \mathrm{d}  t$ for all $\varphi \in L^1$, \textit{i.e.}, 
   \begin{equation}\label{eq:steklov weak star Linfty}
      \psi^2 (f^h \wedge M)^{q-2} \mathds{1}_{\{f^h < M\}} \overset{*}{\rightharpoonup} \psi^2 (f \wedge M)^{q-2} \mathds{1}_{\{f < M\}} \quad \text{weakly-* in } L^\infty. 
   \end{equation}
   Combining \eqref{eq:steklov strong L1} and \eqref{eq:steklov weak star Linfty} as a weak-strong product implies 
   \begin{equation*}
       \begin{aligned}
          \lim_{h \to 0^+} \int_{-R}^s \!\int_{\mathbb{T}^3} \!\!\psi^2 (f^h\wedge & M)^{q-2} \Big( \big[ (1\!-\!\rho) \nabla f \!+\! f \nabla \rho \big]^h \!\cdot\! \nabla f^h \!\!+\!    |\partial_\theta f^h|^2 \Big) \mathds{1}_{\{f^h < M\}} \\ 
          &= \int_{-R}^s \!\int_{\mathbb{T}^3} \!\!\psi^2 (f\!\!\wedge\!M)^{q-2} \Big( \big[ (1\!-\!\rho) \nabla f \!+\! f \nabla \rho \big] \!\cdot\! \nabla f \!\!+\!    |\partial_\theta f|^2 \Big) \mathds{1}_{\{f < M\}} , 
       \end{aligned}
   \end{equation*}
   and an analogous argument yields the expected convergence of the final term in \eqref{eq:steklov long}. Meanwhile, directly from the definition of $\Phi_{M,q}(s) = \int_0^s q(r \wedge M)^{q-1} \, \mathrm{d}  r$, it holds 
   \begin{equation*}
      \begin{aligned}
          \Phi_{M,q}(f^h) &= (f^h)^q \mathds{1}_{\{f^h  < M\}} + \big[ M^q + qM^{q-1}(f^h -M) \big] \mathds{1}_{\{f^h  \geq M\}} \\ 
          &= \Big[ (f^h)^q \!-\! \big[ M^q \!+\! qM^{q-1}(f^h\!-\!M) \big]   \Big]\mathds{1}_{\{f^h < M\}} \!+\! \big[ M^q \!+\! qM^{q-1}(f^h -M) \big] , 
      \end{aligned}
   \end{equation*}
and we have that the first term on the right-hand side is uniformly bounded in $h$ by $2(1+q)M^q $ and converges a.e.~to $[f^q \!-\! [ M^q \!+\! qM^{q-1}(f\!-\!M) ] ]\mathds{1}_{\{f < M\}}$ (for a subsequence) while the second term converges strongly to $M^q + qM^{q-1}(f-M)$ in $L^3(\mathbb{T}^3)$ by standard results on Steklov averages. Using also the Dominated Convergence Theorem, we deduce 
\begin{equation*}
    \lim_{h\to 0^+} 2 \int_{-R}^s  \int_{\mathbb{T}^3}   \psi \partial_t \psi \Phi_{M,q}(f^h)  = 2 \int_{-R}^s  \int_{\mathbb{T}^3}  \psi \partial_t \psi \Phi_{M,q}(f). 
\end{equation*}
Meanwhile, Fatou's Lemma implies $\int_{\mathbb{T}^3} \Phi_{M,q}(f(s)) \leq \liminf_{h\to 0^+} \int_{\mathbb{T}^3} \Phi_{M,q}(f^h(s))$. Thus, by letting $h \to 0^+$,  using also the lower bound \eqref{eq:the translated cylinders stuff}, we deduce from \eqref{eq:steklov long} that (a.e.~$s$) 
      \begin{equation*}
       \begin{aligned}
           \int_{\mathbb{T}^3}   \Phi_{M,q}(f(s)) + & q(q\!-\!1)c_{t,T} \int_{-R}^s \!\int_{\mathbb{T}^3} \psi^2 |(f\!\wedge\!M)^{\frac{q}{2}-1} \nabla_\xi f|^2 \mathds{1}_{\{f < M\}} \\ 
           \leq & \,  q(q\!-\!1)\bigg|\int_{-R}^s \!\int_{\mathbb{T}^3}\!\! \psi^2 (f\!\wedge\! M)^{q-1}  \nabla f \mathds{1}_{\{f<M\}} \!\cdot\! \! \nabla \rho \bigg| \\ 
           &+  q(q\!-\!1) \int_{-R}^s \! \int_{\mathbb{T}^3} \!\! \psi^2 \Big| (f \!\wedge\! M)^{q-1} \nabla f \mathds{1}_{\{f < M\}} \Big| + \frac{C}{R-r} \int_{-R}^s \! \int_{\mathbb{T}^3} \! \Phi_{M,q}(f). 
       \end{aligned}
   \end{equation*}
Using the lower bound \eqref{eq:Phi for steklov}, $0 \leq \psi \leq 1$, and integration by parts to get $\Delta \rho$, we deduce 
  \begin{equation*}
       \begin{aligned}
           &\int_{\mathbb{T}^3}  |(f(s)\wedge M)^{\frac{q}{2}}|^2 +  4(1\!-\!q^{-1})c_{t,T} \int_{-R}^s \!\int_{\mathbb{T}^3}   |\nabla_\xi [\psi (f\!\wedge\!M)^{\frac{q}{2}}] |^2  \\ 
           &\leq  (q\!-\!1)\!\!\! \iint_{Q(R)}\!\! \!\! \!\! | (f\!\wedge\! M)^{\frac{q}{2}} |^2 |\Delta \rho| \!+\!  2(q\!-\!1) \!\!\!\int_{-R}^s \! \int_{\mathbb{T}^3} \!\! (f \!\wedge\! M)^{\frac{q}{2}} | \nabla [\psi (f \!\wedge\! M)^{\frac{q}{2}}] | \!+\! \frac{C}{R-r}\!\! \iint_{Q(R)}\!\! \!\!\!\! \Phi_{M,q}(f) , 
       \end{aligned}
   \end{equation*}
for a.e.~$s \in (-r,r)$. Using \eqref{eq:the translated cylinders stuff}, Young's inequality, and the upper bound \eqref{eq:Phi for steklov}, it holds 
  \begin{equation*}
       \begin{aligned}
           &\Vert (f\wedge  M)^{\frac{q}{2}}\Vert_{L^\infty((-r,r);L^2(\mathbb{T}^3))}^2 +  3(1\!-\!q^{-1})c_{t,T} \Vert \nabla_\xi [(f\!\wedge\!M)^{\frac{q}{2}}] \Vert_{L^2(Q_r)}^2  \\ 
           &\leq \! (q\!-\!1) \Vert | (f\!\wedge\! M)^{\frac{q}{2}} |^2 \Vert_{L^{\frac{4}{3}}(Q_R)}  \Vert \Delta \rho\Vert_{L^4(Q_R)}  \!+\!  \frac{q(q\!-\!1)}{c_{t,T}} \Vert (f \!\wedge\! M)^{\frac{q}{2}} \Vert_{L^2(Q_R)}^2 \!+\!\frac{C}{R\!-\!r} \Vert f^{\frac{q}{2}} \Vert^2_{L^2(Q_R)}; 
       \end{aligned}
   \end{equation*}
note the final term is \emph{a priori} only finite for $2\leq q \leq \nicefrac{5}{2}$ by Lemma \ref{lem:f parabolic space}; nevertheless, the inequality remains true for all $q \geq 2$, with the possibility of this term being infinite. Using $1-q^{-1} \geq \nicefrac{1}{2}$ and H\"older's inequality to control the $L^2$ norm by $L^{\nicefrac{8}{3}}$ we deduce \eqref{eq:first checkpoint moser bis pour f}. 



\smallskip 

\noindent 2. \textit{Moser iteration}. Lemma \ref{lem:dibenedetto classic} and \eqref{eq:first checkpoint moser bis pour f} give $ \Vert  (f \wedge M)^{\frac{q}{2}} \Vert_{L^{\nicefrac{10}{3}}(Q_r)}^2 \!\leq\! \frac{C\kappa q^2}{R\!-\!r}  \Vert f^{\frac{q}{2}} \Vert_{L^{\nicefrac{8}{3}}(Q_R)}^2 $, and thus, by letting $M\to \infty$ and the Monotone Convergence Theorem, it holds 
\begin{equation}\label{eq:first checkpoint moser bis pour f recursive}
   \begin{aligned}
      \Vert  f \Vert_{L^{\nicefrac{5q}{3}}(Q_r)} \leq \Big( \frac{C\kappa q^2}{R\!-\!r}  \Big)^{\nicefrac{1}{q}} \Vert f \Vert_{L^{\nicefrac{4q}{3}}(Q_R)}, 
   \end{aligned} 
\end{equation}
where we recall $C,\kappa$ are independent of $q,r,R$; the above holds for all choices of $0<r<R\leq 1$ and all $q \geq 2$. Next, define the powers $q_n := 2 (\frac{5}{4})^n$ for $n \geq 0$ and the radii 
\begin{equation*}
   r_0 = R, \qquad  r_n = R-(R-r) \gamma^{-1} \sum_{j=1}^n (\frac{5}{4})^{-j}
\end{equation*}
where $\gamma = \sum_{n\geq 1}(5/4)^{-n}$, so that $R=r_0 > r_1 > \dots > r_n \searrow r$. Note that $r_n - r_{n+1} = (R-r)\gamma^{-1} (5/4)^{-n-1}$. Iterating \eqref{eq:first checkpoint moser bis pour f recursive} along this sequence (setting $q=q_n$, $R=r_n$, $r=r_{n+1}$), it holds---by setting $L := 5C\kappa \gamma$ and $\alpha := 5/4$---the estimate 
\begin{equation}\label{eq:f moser before n to infty}
    \Vert  f\Vert_{L^{\frac{8 }{3}\alpha^{n+1}}(Q_{r_{n+1}})} \leq \Big( \frac{L  \alpha^{3n}}{R\!-\!r}  \Big)^{\frac{1}{2\alpha^n}} \Vert f \Vert_{L^{\frac{8}{3}\alpha^n}(Q_{r_n})} \leq  \bigg( \prod_{j=0}^{n}\Big( \frac{L  \alpha^{3j}}{R\!-\!r}  \Big)^{\frac{1}{2\alpha^j}} \bigg) \Vert f \Vert_{L^{\frac{8}{3}}(Q_{R})}. 
\end{equation}
We study the convergence of the product. We have 
\begin{equation*}
    \begin{aligned}
        \log\bigg( \prod_{j=0}^{n}\Big( \frac{L  \alpha^{3j}}{R\!-\!r}  \Big)^{\frac{1}{2\alpha^j}} \bigg) =& \,  \frac{\alpha}{2}\log\Big(\frac{L}{R\!-\!r}\Big) \sum_{j=1}^{n+1} \alpha^{-j} \!+\! \frac{3}{2} \log \alpha \sum_{j=0}^n j \alpha^{-j} \nearrow  \frac{\alpha \gamma}{2} \log\Big(\frac{L}{R\!-\!r}\Big) \!+\! \bar{C}
    \end{aligned}
\end{equation*}
where $\bar{C}$ depends only on $\alpha$. Returning to \eqref{eq:f moser before n to infty} and letting $n\to\infty$, it holds 
\begin{equation*}
     \Vert  f\Vert_{L^{\infty}(Q_{r})} \leq C\bigg(\frac{L}{R-r}\bigg)^{\frac{5\gamma}{8}} \Vert f \Vert_{L^{\nicefrac{8}{3}}(Q_R)} , 
\end{equation*}
where $C$ depends only on $\alpha$. Using $\Vert f \Vert_{L^{8/3}(Q_R)} \leq C_{t,T} \Vert f \Vert_{L^{10/3}((t,T)\times\mathbb{T}^3)}$ and Lemma \ref{lem:f parabolic space}, and recalling the definitions of $L,\kappa$ from \eqref{eq:first checkpoint moser bis pour f}, we get \eqref{eq:moser upper for f}.

As in \S \ref{sec:H2 for p}, the underlying notion is that, provided the passage from divergence form \eqref{eq:main eqn} to non-divergence form is justified, then \eqref{eq:main eqn} reads 
    \begin{equation}\label{eq:non div form f}
        \partial_t f + \operatorname{div}((1-\rho)f{\bf e}(\theta)) = (1-\rho)\Delta f + f \Delta \rho + \partial^2_\theta f, 
    \end{equation}
    whence testing with $\Delta f$ (and $\partial^2_\theta f$) gives the conclusion. To do this rigorously, we employ Galerkin's method. Without loss of generality $t$ is a Lebesgue point of $t \mapsto (f(t),\nabla_\xi f(t))$. 

    \smallskip 

    \noindent 1. \textit{Galerkin approximations}. We recall the notations of \S \ref{sec:H2 for p}, with $\{\varphi_j\}_j$ the orthonormal basis of $L^2(\mathbb{T}^2)$ of eigenfunctions of the Laplacian, and define the \emph{ansatz}
\begin{equation*}
    f^n(s,x,\theta) := \sum^n_{j=1} \alpha^n_j(s,\theta) \varphi_j(x), 
\end{equation*}
where the scalar coefficients $\{\alpha^n_j\}_{j=1}^{n}$ are determined from the linear system of PDEs 
\begin{equation}\label{eq:coeff f galerkin}
    \partial_t \alpha^n_j - \partial^2_\theta \alpha^n_j + \sum_{k=1}^n \alpha^n_k\bigg( \int_{\mathbb{T}^2} \Big( (1\!-\!\rho) \nabla \varphi_k  + \varphi_k \nabla \rho \Big)\!\cdot \!\nabla \varphi_j \, \mathrm{d}  x \bigg) \!=\! \int_{\mathbb{T}^2}  (1-\rho) f {\bf e}(\theta) \!\cdot \!\nabla \varphi_j \, \mathrm{d}  x, 
\end{equation}
with initial data $\alpha^n_j(t,\theta) = \langle f(t,\cdot,\theta) , \varphi_j \rangle, $ chosen such that $f^n$ solves the \emph{linear} equation
\begin{equation}\label{eq:galerkin f}
    \left\lbrace\begin{aligned}
        &\partial_t f^n + \operatorname{div}((1-\rho)f {\bf e}(\theta)) = \operatorname{div}((1-\rho)\nabla f^n + f^n \nabla \rho ) + \partial^2_\theta f^n, \\ 
        &f^n(t,\cdot,\theta) = \sum_{j=1}^n \langle f(t,\cdot,\theta) , \varphi_j \rangle \varphi_j 
    \end{aligned}\right.
\end{equation}
in the weak sense dual to $L^2((t,T);H^1(\mathbb{T});\mathrm{span}\{\varphi_j\}_{j=1}^n)$. The standard theory for strongly parabolic linear systems (recall \eqref{eq:ctT def}) implies the existence $\alpha^n_j \in L^2((t,T);H^1(\mathbb{T}))$ with $\partial_t \alpha^n_j \in L^2((t,T);H^{-1}(\mathbb{T}))$ solving \eqref{eq:coeff f galerkin}, and thus of $f^n$ solving \eqref{eq:galerkin f} in the aforementioned weak sense. Additionally, we have (as $n\to\infty$)
\begin{equation*}
    \Vert f^n(t,\cdot,\theta) \Vert^2_{L^2(\mathbb{T}^2)} = \sum_{j=1}^n \langle f(t,\cdot,\theta) , \varphi_j \rangle^2 \longrightarrow \Vert f(t,\cdot,\theta) \Vert^2_{L^2(\mathbb{T}^2)} \quad \text{a.e.~} \theta. 
\end{equation*}
Integrating in $\theta$ gives $\Vert f^n(t) \Vert^2_{L^2(\mathbb{T}^3)} = \int_\mathbb{T} \sum_{j=1}^n \langle f(t,\cdot,\theta) , \varphi_j \rangle^2 \, \mathrm{d}  \theta,$ so  the Monotone Convergence Theorem (the integrands form an increasing non-negative sequence) implies 
\begin{equation*}
   \lim_{n\to\infty}\Vert f^n(t) \Vert^2_{L^2(\mathbb{T}^3)} = \int_\mathbb{T} \lim_{n\to\infty} \sum_{j=1}^n \langle f(t,\cdot,\theta) , \varphi_j \rangle^2 \, \mathrm{d}  \theta = \int_\mathbb{T} \Vert f(t,\cdot,\theta) \Vert^2_{L^2(\mathbb{T}^2)} \, \mathrm{d}  \theta. 
\end{equation*}
Analogously, by similar manipulations as \eqref{eq:conv of initial data for galerkin}, this convergence holds for $\Vert \nabla_\xi f(t)\Vert_{L^2}$:
\begin{equation}\label{eq:conv initial data galerkin f}
    \lim_{n\to\infty}\Vert f^n(t) \Vert^2_{L^2(\mathbb{T}^3)} = \Vert f(t) \Vert^2_{L^2(\mathbb{T}^3)}, \quad \lim_{n\to\infty}\Vert \nabla_{\xi} f^n(t) \Vert^2_{L^2(\mathbb{T}^3)} = \Vert \nabla_{\xi} f(t,\cdot) \Vert^2_{L^2(\mathbb{T}^3)}. 
\end{equation}

\smallskip 

\noindent 2. \textit{$H^1$ estimate}. We begin with the standard $H^1$ estimate, by testing \eqref{eq:galerkin f} with $f^n$ itself; this is allowed since $f^n $ is written as a linear combination of the $\{\varphi_j\}$. Using the Lions--Magenes Lemma over the finite-dimensional Hilbert space $\mathrm{span}\{\varphi_j\}_{j=1}^n$, and \eqref{eq:ctT def}, 
\begin{equation*}
    \begin{aligned}
        \frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t}\Vert f^n \Vert_{L^2(\mathbb{T}^3)}^2 + \frac{c_{t,T}}{2} \Vert & \nabla_{\xi} f^n \Vert^2_{L^2(\mathbb{T}^3)} \leq \frac{1}{2c_{t,T}}\Vert (1\!-\!\rho) f {\bf e}(\theta) \Vert^2_{L^2(\mathbb{T}^3)} - \int_{\mathbb{T}^3} f^n \nabla f^n \!\cdot\! \nabla \rho \, \mathrm{d}  \xi \\ 
        &\leq \frac{1}{2c_{t,T}}\Vert f \Vert^2_{L^2(\mathbb{T}^3)} + \frac{1}{c_{t,T}} \int_{\mathbb{T}^3} |f^n|^2 | \nabla \rho |^2 \, \mathrm{d}  \xi + \frac{c_{t,T}}{4} \Vert \nabla_\xi f^n \Vert^2_{L^2(\mathbb{T}^3)} , 
    \end{aligned}
\end{equation*}
whence $ \frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t}\Vert f^n \Vert_{L^2(\mathbb{T}^3)}^2 + \frac{c_{t,T}}{4} \Vert\nabla_{\xi} f^n \Vert^2_{L^2(\mathbb{T}^3)} \leq \frac{1}{2c_{t,T}}\Vert f \Vert^2_{L^2(\mathbb{T}^3)} + \frac{1}{c_{t,T}}\Vert f^n\Vert_{L^2(\mathbb{T}^3)}^2 \Vert \nabla \rho \Vert_{L^\infty(\mathbb{T}^3)}^2$, and integrating in time yields (for all $t<s\leq T$) 
\begin{equation*}
    \begin{aligned}
     \Vert f^n (s) \Vert^2_{L^2(\mathbb{T}^3)} + {c_{t,T}}\Vert \nabla_\xi f^n \Vert^2_{L^2((t,s)\times\mathbb{T}^3)} \leq & \, \Vert f^n(t) \Vert^2_{L^2(\mathbb{T}^3)} \!+\! c_{t,T}^{-1} \Vert f \Vert^2_{L^2((t,T)\times\mathbb{T}^3)}   \\ 
     &+ 2c_{t,T}^{-1} \int_t^s \! \Vert \nabla \rho (s')\Vert_{L^\infty(\mathbb{T}^3)}^2  \Vert f^n(s') \Vert_{L^{2}(\mathbb{T}^3)}^2 \, \mathrm{d}  s' \\ 
     \leq & \, C_{t,T} \bigg( 1 + \int_t^s \! \Vert \nabla \rho (s')\Vert_{L^\infty(\mathbb{T}^3)}^2  \Vert f^n(s') \Vert_{L^{2}(\mathbb{T}^3)}^2 \, \mathrm{d}  s' \bigg) , 
    \end{aligned}
\end{equation*}
where we used the convergence of initial data \eqref{eq:conv initial data galerkin f} to establish the boundedness-in-$n$ of the right-hand side, and $C_{t,T}$ depends only on $t,T,c_{t,T}$. By Gr\"onwall's Lemma, we deduce 
\begin{equation*}
    \begin{aligned}
        \Vert f^n \Vert^2_{L^\infty((t,T);L^2(\mathbb{T}^3))} \leq C_{t,T} \exp \bigg( C_{t,T} \int_t^T \Vert \nabla \rho(s) \Vert^2_{L^\infty(\mathbb{T}^3)} \, \mathrm{d}  s \bigg) , 
    \end{aligned}
\end{equation*}
where we notice that the final term is bounded by Corollary \ref{cor:consequence of gehring}. Returning to the previous estimate, 
we deduce that there exists $C_{t,T}$ depending only on $t,T,c_{t,T}$ (not $n$) such that 
\begin{equation}\label{eq:H1 bound galerkin f}
  \Vert f^n \Vert_{L^\infty((t,T);L^2(\mathbb{T}^3))}^2 + \Vert \nabla_\xi f^n \Vert^2_{L^2((t,T)\times\mathbb{T}^3)} \leq C_{t,T}. 
\end{equation}

\smallskip 

\noindent 3. \textit{$H^2$ estimate}. We pass from the divergence form to non-divergence form of \eqref{eq:galerkin f}; this is allowed since each $f^n$ is smooth in $x$ (being a linear combination of eigenfunctions of the Laplacian). Testing with $\Delta f^n$, which is allowed since $\Delta f^n(t,\cdot,\theta) \in \mathrm{span}\{\varphi_j\}_{j=1}^n$ a.e.~$t,\theta$, 
\begin{equation*}
    \begin{aligned}
        \frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t}\Vert \nabla f^n \Vert^2_{L^2(\mathbb{T}^3)} \!+\! \frac{c_{t,T}}{2} \Vert \Delta f^n \Vert^2_{L^2(\mathbb{T}^3)} \!+ & \Vert \nabla \partial_\theta f^n \Vert^2_{L^2(\mathbb{T}^3)} \\ 
        &\leq \frac{1}{2c_{t,T}} \Vert \operatorname{div}((1\!-\!\rho) f {\bf e}(\theta) ) \Vert^2_{L^2(\mathbb{T}^3)} - \int_{\mathbb{T}^3}f^n \Delta f^n \Delta \rho \, \mathrm{d}  \xi , 
    \end{aligned}
\end{equation*}
so that, by Young's inequality and integrating in time, for all $t<s\leq T$, 
\begin{equation*}
    \begin{aligned}
         \Vert \nabla & f^n(s) \Vert^2_{L^2(\mathbb{T}^3)}  \!+\! \frac{c_{t,T}}{2} \Vert \Delta f^n \Vert^2_{L^2((t,s)\times\mathbb{T}^3)} \!+ \! \Vert \nabla \partial_\theta f^n \Vert^2_{L^2((t,s)\times\mathbb{T}^3)} \\ 
        &\leq \Vert \nabla f^n(t) \Vert^2_{L^2(\mathbb{T}^3)} + c_{t,T}^{-1} \Vert \operatorname{div}((1\!-\!\rho) f {\bf e}(\theta)) \Vert^2_{L^2((t,T)\times\mathbb{T}^3)} + 2 c_{t,T}^{-1}\int_t^s \Vert f^n \Delta \rho \Vert_{L^2(\mathbb{T}^3)}^2 \, \mathrm{d}  s' . 
    \end{aligned}
\end{equation*}
From the convergence of the initial data  \eqref{eq:conv initial data galerkin f}, Lemma \ref{lem:f parabolic space}, and Proposition \ref{prop:f bounded moser}, we deduce that there exists $C_{t,T}$ depending only on $t,T$ such that 
\begin{equation}\label{eq:long part of H2 for f}
    \begin{aligned}
         \Vert \nabla  f^n(s) \Vert^2_{L^2(\mathbb{T}^3)}  \!+\! \frac{c_{t,T}}{2} \Vert \Delta f^n & \Vert^2_{L^2((t,s)\times\mathbb{T}^3)} + \! \Vert \nabla \partial_\theta f^n \Vert^2_{L^2((t,T)\times\mathbb{T}^3)} \\ 
        &\leq C_{t,T} \bigg( 1 \!+\! \int_t^s\!\! \int_\mathbb{T} \!\! \Vert (f^n \Delta \rho) (s',\theta') \Vert_{L^2(\mathbb{T}^2)}^2 \, \mathrm{d}  \theta' \, \mathrm{d}  s' \bigg) , 
    \end{aligned}
\end{equation}
note that we have written the $\theta$ integral explicitly in the final term. Using H\"older's inequality, this final term may be estimated as (since $\rho$ is independent of $\theta$)
\begin{equation*}
    \begin{aligned}
         \int_t^s\!\! \int_\mathbb{T} \!\! \Vert (f^n \Delta \rho) (s',\theta') \Vert_{L^2(\mathbb{T}^2)}^2 \, \mathrm{d}  \theta' \, \mathrm{d}  s'  &\leq \int_t^s\!\! \int_\mathbb{T} \!\! \Vert f^n (s',\theta') \Vert^2_{L^4(\mathbb{T}^2)} \Vert \Delta \rho (s',\theta') \Vert_{L^4(\mathbb{T}^2)}^2 \, \mathrm{d}  \theta' \, \mathrm{d}  s' \\ 
         &\leq C\int_t^s\!\! \Vert \Delta \rho (s') \Vert_{L^4(\mathbb{T}^2)}^2 \bigg( \int_\mathbb{T} \!\! \Vert f^n (s',\theta') \Vert^2_{H^1(\mathbb{T}^2)}  \, \mathrm{d}  \theta' \bigg) \, \mathrm{d}  s'
    \end{aligned}
\end{equation*}
where we used the Sobolev inequality in $\mathbb{T}^2$ (\textit{i.e.~}with respect to only $x$), and the constant $C$ depends only on $\mathbb{T}^2$ and the exponent $4$. Returning to \eqref{eq:long part of H2 for f}, we get 
\begin{equation*}
    \begin{aligned}
         \Vert &\nabla  f^n(s) \Vert^2_{L^2(\mathbb{T}^3)}  +\! \frac{c_{t,T}}{2}  \Vert \Delta f^n \Vert^2_{L^2((t,s)\times\mathbb{T}^3)} + \! \Vert \nabla \partial_\theta f^n \Vert^2_{L^2((t,s)\times\mathbb{T}^3)} \\ 
        &\leq C_{t,T} \bigg( 1 \!+\! \int_t^s\!\! \Vert \Delta \rho (s') \Vert_{L^4(\mathbb{T}^2)}^2 \Big( \Vert f^n (s') \Vert^2_{L^2(\mathbb{T}^3)} + \Vert \nabla f^n (s') \Vert^2_{L^2(\mathbb{T}^3)} \Big) \, \mathrm{d}  s' \bigg)\\ 
        &\leq C_{t,T} \bigg( 1 \!+\! \Vert f^n \Vert^2_{L^\infty((t,T);L^2(\mathbb{T}^3))} \Vert \Delta \rho \Vert_{L^4((t,T)\times\mathbb{T}^3)}^2 \!+\! \int_t^s\!\! \Vert \Delta \rho (s') \Vert_{L^4(\mathbb{T}^2)}^2 \Vert \nabla f^n (s') \Vert^2_{L^2(\mathbb{T}^3)}  \, \mathrm{d}  s' \bigg), 
    \end{aligned}
\end{equation*}
\textit{i.e.}, $\Vert \nabla  f^n(s) \Vert^2_{L^2} \leq C_{t,T}(1\!+\!\int_t^s \Vert \Delta \rho (s') \Vert_{L^4}^2 \Vert \nabla f^n (s') \Vert^2_{L^2)}  \, \mathrm{d}  s' )$, and Gr\"onwall's Lemma implies 
\begin{equation*}
    \Vert \nabla f^n \Vert^2_{L^\infty((t,T);L^2(\mathbb{T}^3))} \leq C_{t,T} \exp\bigg( \int_t^T \Vert \Delta \rho(s) \Vert^2_{L^4(\mathbb{T}^2)} \, \mathrm{d}  s \bigg), 
\end{equation*}
and the final integral is bounded on account of $\Delta \rho \in L^4((t,T)\!\times\!\mathbb{T}^3)$ by Corollary \ref{cor:continuity rho and hess in L4 nabla rho L8}. Returning to the previous estimate, we deduce that, for some $C_{t,T}$ independent of $n$, 
\begin{equation}\label{eq:H2 glaerkin f n}
    \begin{aligned}
         \Vert \nabla  f^n \Vert^2_{L^\infty((t,T);L^2(\mathbb{T}^3))}  +\! \Vert \Delta f^n \Vert^2_{L^2((t,T)\times\mathbb{T}^3)} + \! \Vert \nabla \partial_\theta f^n \Vert^2_{L^2((t,T)\times\mathbb{T}^3)} \leq C_{t,T}. 
    \end{aligned}
\end{equation}

\smallskip 

\noindent 4. \textit{Convergence and conclusion}. An analogous strategy to Step 3, but testing this time with $\partial^2_\theta f^n$ (again this belongs to the span of the eigenfunctions for a.e.~$t,\theta$) shows the uniform-in-$n$ boundedness of $\Vert \partial^2_\theta f^n \Vert_{L^2}$. Putting together with the bounds \eqref{eq:H1 bound galerkin f} and \eqref{eq:H2 glaerkin f n}, we get that $f^n \rightharpoonup {f}^\infty$ weakly in $L^2((t,T);H^2(\mathbb{T}^3))$, and an argument analogous to Step 3 of the proof of Proposition \ref{prop:galerkin p} shows that ${f}^\infty=f$. Hence estimate \eqref{eq:H2 glaerkin f n} also holds for $f$.

Finally, using Proposition \ref{prop:f bounded moser} and Gagliardo--Nirenberg inequality (for $C$ depending only on $\mathbb{T}^3$), $\Vert \nabla_{\xi} f(s) \Vert_{L^4(\mathbb{T}^3)} \leq C ( \Vert \nabla_{\xi}^2 f(s) \Vert_{L^2(\mathbb{T}^3)}^{\frac{1}{2}} \Vert f(s) \Vert_{L^\infty(\mathbb{T}^3)}^{\frac{1}{2}} + \Vert f(s) \Vert_{L^1(\mathbb{T}^3)})$, and thus $\Vert \nabla_{\xi} f \Vert_{L^4((t,T)\times\mathbb{T}^3)}^4 \leq C ( \Vert \nabla_{\xi}^2 f \Vert_{L^2((t,T)\times\mathbb{T}^3)}^{2} \Vert f \Vert_{L^\infty((t,T)\times\mathbb{T}^3)}^{2} + (T-t) )$.

The proof is divided into two steps. 

  \smallskip 

  \noindent 1. \textit{Initial upgrade of integrability}. By Lemma \ref{lem:H2 f}, the $\xi$-derivatives of $f$ are endowed with sufficient integrability to rigorously pass to the non-divergence form of the equation \eqref{eq:non div form f}, which holds weakly in duality with $L^2((t,T)\times\mathbb{T}^3)$. By defining the matrix 
  \begin{equation}\label{eq:A def for non div f}
      A := \left( \begin{matrix}
          (1-\rho)\mathrm{Id}_2 & 0 \\ 
          0 & 1
      \end{matrix} \right) , 
  \end{equation}
  which is symmetric, $\nicefrac{1}{4}$-H\"older continuous by Corollary \ref{cor:continuity rho and hess in L4 nabla rho L8}, and strongly elliptic by the lower bound on $1-\rho$ provided by \eqref{eq:ctT def}, we may recast \eqref{eq:non div form f} in the form 
  \begin{equation}\label{eq:recast dt f fess f in all Lp}
      \partial_t f - A:\nabla^2_\xi f = f\Delta \rho + f{\bf e}(\theta)\cdot\nabla \rho - (1-\rho)\nabla f \cdot {\bf e}(\theta), 
  \end{equation}
and thus $\partial_t f - A:\nabla^2_\xi f \in L^4((t,T)\!\times\!\mathbb{T}^3)$  by Proposition \ref{prop:f bounded moser}, Corollary \ref{cor:continuity rho and hess in L4 nabla rho L8}, and Lemma \ref{lem:H2 f}. In turn, the Schauder result of Lemma \ref{lem:Lp schauder} applies, and we deduce $\partial_t f , \nabla^2_\xi f \in L^4((t,T)\!\times\!\mathbb{T}^3)$---technically, the estimate holds for any time interval $(t',T')\subset\subset (t,T)$, but by resizing the original $(t,T)$, we obtain the result on any such interval. By arguing as per Step 4 of the proof of Lemma \ref{lem:H2 f}, the Gagliardo--Nirenberg inequality implies $\Vert \nabla_{\xi} f(s) \Vert_{L^8(\mathbb{T}^3)}^8 \leq C ( \Vert \nabla_{\xi}^2 f(s) \Vert_{L^4(\mathbb{T}^3)}^{4} \Vert f(s) \Vert_{L^\infty(\mathbb{T}^3)}^{4} + {\Vert f(s) \Vert^4_{L^1(\mathbb{T}^3)}} )$, hence $\nabla_\xi f \in L^8((t,T)\!\times\!\mathbb{T}^3)$. 

  \smallskip 

  \noindent 2. \textit{Inductive argument}. We will show that, for all $m \geq 1$ and all $(t,T)\subset \subset (0,\infty)$, it holds $\partial_t f , \nabla^2_\xi f \in L^{2^m}((t,T)\!\times\mathbb{T}^3)$ and $\nabla_\xi f \in L^{2^{m+1}}((t,T)\!\times\!\mathbb{T}^3)$. We have already shown the result for $m=1,2$. Suppose the result is true for $m\in\mathbb{N}$: we study the case $m+1$. Then, by \eqref{eq:rho eq}, it holds $\partial_t \rho - \Delta \rho = \rho \operatorname{div} {\bf p} - \nabla \rho \cdot {\bf p} \in L^{2^{m+1}}((t,T)\!\times\!\mathbb{T}^2)$ by the induction hypothesis. Thus, the Calder\'on--Zygmund Theorem implies that (up to resizing the original time interval), it holds $\partial_t \rho , \nabla^2 \rho \in L^{2^{m+1}}((t,T)\!\times\!\mathbb{T}^2)$. Whence, returning to \eqref{eq:recast dt f fess f in all Lp} and using also the boundedness of $f$ from Proposition \ref{prop:f bounded moser}, it holds $\partial_t f - A:\nabla^2_\xi f \in L^{2^{m+1}}((t,T)\!\times\mathbb{T}^3)$. The Schauder Lemma \ref{lem:Lp schauder} implies (up to resizing the original time interval) that $\partial_t f , \nabla^2_\xi f \in L^{2^{m+1}}((t,T)\!\times\mathbb{T}^3)$, and arguing by the Gagliardo--Nirenberg inequality as per the end of Step 1 (\textit{cf.}~Step 4 of Lemma \ref{lem:H2 f}) shows $ \Vert \nabla_{\xi} f \Vert^{2^{m+2}}_{L^{2^{m+2}}((t,T)\times\mathbb{T}^3)} \leq C ( \Vert \nabla_{\xi}^2 f \Vert_{L^{2^{m+1}}((t,T)\times\mathbb{T}^3)}^{2^{m+1}} \Vert f \Vert_{L^\infty((t,T)\times\mathbb{T}^3)}^{2^{m+1}} + (T-t)). $ By induction, the result holds for all $m$, and thus the conclusion of the lemma follows by interpolation in Lebesgue spaces.

\label{lem:rho dot H1}
    For all $0<t<T<\infty$, it holds $\dot{\rho}\in L^\infty((t,T);L^2(\mathbb{T}^2))$, $\nabla \dot{\rho} \in L^2((t,T)\!\times\!\mathbb{T}^2)$, $\partial_t \dot{\rho} \in L^2((t,T);H^{-1}(\mathbb{T}^2))$, and 
    \begin{equation}\label{eq:dot rho eq}
        \partial_t \dot{\rho} + \operatorname{div}((1-\rho)\dot{{\bf p}} - {\bf p} \dot\rho ) = \Delta \dot{\rho} \qquad \text{weakly in } L^2((t,T);H^1(\mathbb{T}^2)). 
    \end{equation}

Firstly, observe that $\dot{\rho},\dot{{\bf p}} \in L^p((t,T)\!\times\!\mathbb{T}^2)$ for all $p \in [1,\infty)$ by Proposition \ref{prop:higher integ dt f and hess f}, so that \eqref{eq:dot rho eq} has meaning in the sense of distributions---we need to show that it follows from \eqref{eq:rho eq}, and we do so by means of a difference quotient argument. From \eqref{eq:rho eq} and linearity:
    \begin{equation*}
        \partial_t D_h \rho + \operatorname{div}( (1-\tau_h\rho)D_h {\bf p} - {\bf p} D_h \rho ) = \Delta D_h \rho \qquad \text{weakly in }L^2(0,\infty;H^1(\mathbb{T}^2));
    \end{equation*}
    recall $\tau_h \rho(t) = \rho(t\!+\!h)$. We test this with $D_h \rho$, whence the Lions--Magenes Lemma gives 
    \begin{equation*}
       \begin{aligned} \frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t} \Vert D_h \rho \Vert^2_{L^2(\mathbb{T}^2)} + \Vert \nabla D_h \rho \Vert^2_{L^2(\mathbb{T}^2)} = \int_{\mathbb{T}^2} (1-\tau_h \rho) \nabla D_h \rho \!\cdot \!D_h {\bf p} \, \mathrm{d}  x - \int_{\mathbb{T}^2} D_h \rho {\bf p} \!\cdot\! \nabla D_h \rho \, \mathrm{d}  x .
       \end{aligned}
    \end{equation*}
    Young's inequality, the boundedness of ${\bf p}$, and integrating in time imply  $\Vert D_h \rho(s) \Vert^2_{L^2(\mathbb{T}^2)} + \Vert \nabla D_h \rho \Vert^2_{L^2((t,s)\times\mathbb{T}^2)} \leq  \Vert D_h \rho(t) \Vert^2_{L^2(\mathbb{T}^2)}  + 2\Vert D_h {\bf p} \Vert^2_{L^2((t,T)\times\mathbb{T}^2)} + 2\Vert D_h \rho \Vert^2_{L^2((t,T)\times\mathbb{T}^2)}$ for a.e.~$t<s\leq T$. Standard properties of difference quotients (\textit{cf.~e.g.~}\cite[\S 5.8.2]{Evans}) yield 
    \begin{equation*}
       \begin{aligned} \Vert D_h \rho \Vert^2_{L^\infty((t,T);L^2(\mathbb{T}^2))} \!+\! \Vert \nabla D_h \rho & \Vert^2_{L^2((t,T)\times\mathbb{T}^2)} \\ 
       &\leq C \Big( \Vert \dot\rho(t) \Vert^2_{L^2(\mathbb{T}^2)}  \!+ \!\Vert \dot {\bf p} \Vert^2_{L^2((t,T)\times\mathbb{T}^2)}\! +\! \Vert \dot \rho \Vert^2_{L^2((t,T)\times\mathbb{T}^2)} \Big) , 
       \end{aligned}
    \end{equation*}
    where the constant $C$ is independent of $h$. Standard results on difference quotients imply that (by letting $h \to 0^+$) it holds $\dot{\rho} \in L^\infty((t,T)\!\times\!\mathbb{T}^2), \nabla \dot{\rho} \in L^2((t,T)\!\times\!\mathbb{T}^2)$ as claimed. In turn, having established this regularity, we may rigorously pass a full time derivative $\partial_t $ onto \eqref{eq:rho eq}, and we deduce \eqref{eq:dot rho eq}. The boundedness $\partial_t \dot{\rho} \in L^2((t,T);H^{-1}(\mathbb{T}^2))$ follows from this equation and the boundedness of the other terms.

\label{lem:H1 dot f}
    For all $0<t<T<\infty$, it holds $\dot{f} \in L^\infty((t,T);L^2(\mathbb{T}^3)), 
abla_\xi \dot{f} \in L^2((t,T)\!	imes\!\mathbb{T}^3)$, $\partial_t \dot{f} \in L^2((t,T);H^{-1}(\mathbb{T}^3))$, and moreover, weakly in $L^2((t,T);H^1(\mathbb{T}^3))$: 
