As per the proof of Lemma \ref{lem:rho dot H1}, we obtain directly from \eqref{eq:main eqn} and linearity: 
    \begin{equation*}
 \begin{aligned} \partial_t D_h f +   \operatorname{div}\big[ & \big(D_h f (1-\tau_h \rho) - f D_h \rho \big){\bf e}(\theta) \big] \\ 
 &= \operatorname{div}\big[ (1-\tau_h \rho) \nabla D_h f - D_h \rho \nabla f + \tau_h f \nabla D_h \rho + D_h f \nabla \rho \big] + \partial^2_\theta D_h f;
 \end{aligned}
\end{equation*}
recall $\tau_h f = f(t\!+\!h)$. Testing with $D_h f$, we get (using the Lions--Magenes Lemma) 
\begin{equation*}
   \begin{aligned} \frac{1}{2}&\frac{\mathrm{d}}{\mathrm{d} t} \Vert D_h f \Vert^2_{L^2(\mathbb{T}^3)} + c_{t,T+1} \Vert \nabla_\xi D_h f \Vert^2_{L^2(\mathbb{T}^3)} \\ 
   &\leq \!\Big( \!\Vert D_h f \Vert_{L^2} \! + \! \Vert f D_h \rho \Vert_{L^2} \! + \! \Vert D_h \rho \nabla f \Vert_{L^2} \!+\! \Vert \tau_h f   \nabla D_h \rho \Vert_{L^2} \!+\! \Vert D_h f \nabla \rho \Vert_{L^2}\!\Big)\! \Vert \nabla D_h f \Vert_{L^2}, 
   \end{aligned}
\end{equation*}
whence Young's inequality and standard properties of difference quotients yield 
\begin{equation*}
   \begin{aligned} \frac{1}{2}&\frac{\mathrm{d}}{\mathrm{d} t} \Vert D_h f \Vert^2_{L^2(\mathbb{T}^3)} + \frac{c_{t,T+1}}{2} \Vert \nabla_\xi D_h f \Vert^2_{L^2(\mathbb{T}^3)} \\ 
   &\leq \! C c_{t,T+1}^{-1} \Big( \!\Vert \dot{f} \Vert_{L^2}^2 \! + \! \Vert f \Vert^2_{L^\infty} \Vert \dot{\rho} \Vert_{L^2}^2 \! + \! \Vert \dot \rho \Vert_{L^4}^2 \Vert \nabla f \Vert_{L^4}^2 \!+\! \Vert \tau_h f \Vert^2_{L^\infty} \Vert  \nabla \dot{\rho} \Vert_{L^2}^2 \!+\! \Vert \dot f \Vert_{L^4} \Vert \nabla \rho \Vert_{L^4}^2 \!\Big)
   \end{aligned}
\end{equation*}
