We argue analogously to Proposition \ref{prop:galerkin p}. Following this strategy to the letter, we obtain the existence of $ \dot{{\bf p}}^n \in AC([t,T];\mathrm{span}\{\varphi_j\}_{j=1}^n)$ ($\varphi_j$ eigenfunctions of $\Delta_x$) solving 
    \begin{equation}\label{eq:galerkin approx dot p}
    \left\lbrace \begin{aligned} 
        &\partial_t \dot{{\bf p}}^n \!-\! \operatorname{div}((1\!-\!\rho)\nabla \dot{{\bf p}}^n \!+\! \dot{\bf p}^n \otimes \nabla \rho) \!+\! \dot{\bf p}^n =  \operatorname{div}( {\bf P} \dot\rho \!-\!(1\!-\!\rho)\dot{{\bf P}} \!+\! {\bf p} \otimes \nabla \dot\rho  \!-\!   \dot\rho \nabla {\bf p} ), \\ 
        &\dot{\bf p}^n(t) = \sum_{j=1}^n \langle \dot{\bf p}(t),\varphi_j \rangle \varphi_j. 
    \end{aligned}\right. 
\end{equation}
Testing the above with $\dot{{\bf p}}^n$ and Young's inequality we get (a.e.~$t < s \leq T$)  
$$\begin{aligned}\Vert \dot{\bf p}^n(s) \Vert_{L^2 } + \Vert \nabla \dot{\bf p}^n \Vert_{L^2((t,s)\times\mathbb{T}^2)} \leq C_{t,T}\Big( & \Vert \dot{\bf p} (t) \Vert_{L^2}^2 +  \Vert \dot{\bf p}^n |\nabla \rho| \Vert^2_{L^2} + \Vert \dot{\rho} \Vert^2_{L^2}  \\ 
&+ \Vert \dot{\bf P} \Vert^2_{L^2} + \Vert {\bf p} |\nabla \dot\rho | \Vert^2_{L^2} + \Vert \dot\rho |\nabla {\bf p} | \Vert^2_{L^2} \Big) \end{aligned}$$
for $C_{t,T}$ depending only on $t,T,c_{t,T}$; we use the lower bound on $1\!-\!\rho$ from \eqref{eq:ctT def}. Hence, 
\begin{equation*}
    \begin{aligned}\Vert \dot{\bf p}^n(s) \Vert_{L^2(\mathbb{T}^2)} + \Vert \nabla \dot{\bf p}^n \Vert_{L^2((t,s)\times\mathbb{T}^2)} \leq C_{t,T}\Big(1 + \int_t^s \Vert \nabla \rho(s') \Vert_{L^\infty(\mathbb{T}^2)}^2 \Vert \dot{\bf p}^n(s') \Vert^2_{L^2(\mathbb{T}^2)} \, \mathrm{d}  s' \Big),  \end{aligned}
\end{equation*}
and we conclude that $\Vert \dot{\bf p}^n \Vert_{L^\infty((t,T);L^2(\mathbb{T}^2))} + \Vert \nabla \dot{\bf p}^n \Vert_{L^2((t,T)\times\mathbb{T}^2)} \leq C_{t,T}$ using Gr\"onwall's Lemma as per the proof of Proposition \ref{prop:galerkin p}. Furthermore, given that $\dot{\bf p}^n(t) \in C^\infty(\mathbb{T}^2)$ for each $n$ (being a linear combination of eigenfunctions of $\Delta_x$), we rigorously pass to the non-divergence form of \eqref{eq:galerkin approx dot p}. Testing with $\Delta \dot{\bf p}^n$, we obtain the uniform bound $\sup_n (\Vert \nabla \dot{\bf p}^n \Vert_{L^\infty((t,T);L^2(\mathbb{T}^2))} + \Vert \Delta \dot{\bf p}^n \Vert_{L^2((t,T)\times\mathbb{T}^2)} ) \leq C_{t,T}$; we skip the details since they are analogous (and simpler) to those in Proposition \ref{prop:galerkin p}. An argument akin to Step 3 in Proposition \ref{prop:galerkin p} shows $\dot{\bf p}^n \rightharpoonup \dot{\bf p}$ weakly in $L^2((t,T);H^2(\mathbb{T}^2))$, and the result follows.

