\smallskip 

\noindent 1. \textit{Improved regularity of $\rho$}. Our aim in this step is to prove the following: for all $0<t<T$, there exists $\beta>0$ depending on $t,T,c_{t,T}$ such that 
   \begin{equation}\label{eq:Drho is Holder}
   D \rho \in C^{1+\nicefrac{\beta}{2},2+\beta}([t,T]\times\mathbb{T}^2), \quad \text{\textit{i.e.}~}\quad\partial_t D\rho, D^3 \rho \in C^{\nicefrac{\beta}{2},\beta}([t,T]\times\mathbb{T}^2). 
   \end{equation}



Recall from Corollary \ref{cor:continuity of laplace rho} and Lemma \ref{lem:nabla f continuous} that $\Delta \rho , \nabla f \in C^{\nicefrac{1}{5}}([t,T]\!\times\!\mathbb{T}^3)$ for all $0<t<T$. As such, the entire right-hand side of \eqref{eq:recast dt f fess f in all Lp} is H\"older continuous, as is the matrix $A$ from \eqref{eq:A def for non div f}; in fact for all $0<t<T$ they belong to $C^{\nicefrac{\alpha}{2},\alpha}([t,T]\!\times\!\mathbb{T}^3)$ for some $\alpha \in (0,1)$. As such (by modifying the size of the time interval---we omit the details for concision), the Schauder result of Lemma \ref{lem:Schauder Holder} implies 
\begin{equation}\label{eq:after one schauder f}
f \in C^{1+\nicefrac{\alpha}{2},2+\alpha}([t,T]\times\mathbb{T}^3) \qquad \forall 0<t<T;
\end{equation}
note that this level of regularity is already enough to deduce that $f$ is a classical solution of \eqref{eq:main eqn}. We return to the equation \eqref{eq:rho eq} for $\rho$. We mollify the entire equation (in $x$ only) and get $\partial_t \rho^\varepsilon - \Delta \rho^\varepsilon = F^\varepsilon := -\operatorname{div}((1-\rho){\bf p})*\eta_\varepsilon$,  where $\rho^\varepsilon = \rho*\eta_\varepsilon$ for $\eta_\varepsilon = \varepsilon^{-2}\eta(\cdot/\varepsilon)$ with $\eta$ the usual Friedrichs bump function in $\mathbb{R}^2$. By applying an $x_j$ derivative, we get 
    \begin{equation*}
        \partial_t \rho^\varepsilon_{x_j} - \Delta \rho^\varepsilon_{x_j} = F^\varepsilon_{x_j} , 
    \end{equation*}
   and note that $F^\varepsilon_{x_j} = F_{x_j}*\eta_\varepsilon = ({\bf p}_{x_j} \!\cdot\! \nabla \rho + {\bf p} \!\cdot\! \nabla \rho_{x_j} + \rho_{x_j} \nabla {\bf p} - (1-\rho) \operatorname{div} {\bf p}_{x_j})*\eta_\varepsilon$. The regularity of $f$ from \eqref{eq:after one schauder f} implies that, for all $0<t<T$, there exists $\beta \in (0,1)$ depending on $t,T,c_{t,T}$ such that $F_{x_j} \in C^{\nicefrac{\beta}{2},\beta}([t,T]\times\mathbb{T}^2)$. Standard properties of the mollifier sequence then imply that $\Vert F^\varepsilon_{x_j} \Vert_{C^{\nicefrac{\beta}{2},\beta}([t,T]\times\mathbb{T}^2)} \leq C \Vert F_{x_j} \Vert_{C^{\nicefrac{\beta}{2},\beta}([t,T]\times\mathbb{T}^2)} $ where the constant $C$ is independent of $t,T,\varepsilon$. Hence, another application of Lemma \ref{lem:Schauder Holder} implies $\Vert \rho^\varepsilon_{x_j} \Vert_{C^{1+\nicefrac{\beta}{2},2+\beta}([t',T']\times\mathbb{T}^2)} \leq C(\Vert F_{x_j} \Vert_{C^{\nicefrac{\beta}{2},\beta}([t,T]\times\mathbb{T}^2)} + \Vert \nabla \rho \Vert_{L^2([t,T]\times\mathbb{T}^2)})$ for $[t',T']\subset\subset [t,T]$ with $C$ depending on $t,t',T,T'$. In turn, an application of the Ascoli--Arzel\`a Theorem implies the strong convergence of $\rho^\varepsilon_{x_j} \to \rho_{x_j}$ in the norm of $C^{1+\nicefrac{\tilde\beta}{2},2+\tilde\beta}([t',T']\times\mathbb{T}^2)$ for all $0<\tilde\beta < \beta$, and \eqref{eq:Drho is Holder} follows (for a different $\beta$ depending on $t,T,c_{t,T}$). 


\smallskip 

\noindent 2. \textit{Improved regularity for $f$}. The regularity \eqref{eq:after one schauder f} implies that we may rigorously pass a $\xi_j$ derivative \emph{in the divergence form of \eqref{eq:main eqn}} to deduce that 
\begin{equation}\label{eq:one space deriv f xi j}
   \begin{aligned}
       \partial_t f_{\xi_j} + \operatorname{div}((1-\rho)f_{\xi_j}{\bf e}(\theta) &- \rho_{\xi_j} f {\bf e}(\theta) + (1-\rho)f {\bf e}_{\xi_j}(\theta)) \\ 
       &= \operatorname{div}((1-\rho)\nabla f_{\xi_j} + f_{\xi_j} \nabla \rho - \rho_{\xi_j} \nabla f  + f \nabla \rho_{\xi_j}) + \partial^2_\theta f_{\xi_j}
   \end{aligned}
\end{equation}
holds (in divergence form) in the sense dual to $L^1((t,T);W^{1,1}(\mathbb{T}^3))$. Our objective is then to show that $\nabla^2_\xi f_{\xi_j} \in L^2_{t,\mathrm{loc}}L^2_\xi$ so that we may pass to the non-divergence form of this equation. To do this rigorously, we perform the same Galerkin method as in Lemma \ref{lem:H2 f} to deduce $f_{\xi_j} \in L^2((t,T);H^2(\mathbb{T}^3))$; we do not write the details in full for clarity of presentation. The sought boundedness can be seen from the formal computation (testing \eqref{eq:one space deriv f xi j} with $\Delta f_{\xi_j}$ after having passed to non-divergence form) 
\begin{equation*}
    \begin{aligned}
        \frac{1}{2}\frac{\mathrm{d}}{\mathrm{d} t}\Vert \nabla f_{\xi_j} \Vert^2_{L^2} + c_{t,T}\Vert \Delta f_{\xi_j} \Vert^2_{L^2} & \leq   \Vert \Delta f_{\xi_j}\Vert_{L^2} \Big( \! \Vert f_{\xi_j} \Delta \rho \Vert_{L^2} \!+\! \Vert \rho_{\xi_j} \Delta f \Vert_{L^2} \!+\! \Vert f \Delta \rho_{\xi_j} \Vert_{L^2} \!+\! \Vert \nabla f_{\xi_j} \Vert_{L^2} \\ 
        &+\! \Vert f_{\xi_j} \nabla \rho \Vert_{L^2} \!+\! \Vert f \nabla \rho_{\xi_j} \Vert \!+\! \Vert \rho_{\xi_j} \nabla f \Vert_{L^2} \!+\! \Vert \nabla f \Vert_{L^2} \!+\! \Vert f \nabla \rho \Vert_{L^2}   \! \Big)    , 
    \end{aligned}
\end{equation*}
where we note from \eqref{eq:after one schauder f}--\eqref{eq:Drho is Holder} that all terms on the right-hand side are bounded in $L^\infty$. Applying Young's inequality yields $\Delta f_{\xi_j} \in L^2((t,T);L^2(\mathbb{T}^3))$, and repeating the same argument by testing with $\partial^2_\theta f_{\xi_j}$ yields $\nabla^2_\xi f_{\xi_j} \in L^2((t,T);L^2(\mathbb{T}^3))$. 







   Next, we show that: for all $0<t<T$ there exists $\beta>0$ depending on $t,T$ such that 
   \begin{equation}\label{eq:schauder level 2 f}
      D_\xi f \in C^{1+\nicefrac{\beta}{2},2+\beta}([t,T]\times\mathbb{T}^3). 
   \end{equation}
   Having shown $\nabla^2_\xi f_{\xi_j} \in L^2_{t,\mathrm{loc}}L^2_\xi$, we return to \eqref{eq:one space deriv f xi j} and rigorously pass to the non-divergence form of the equation to get 
   \begin{equation*}
       \partial_t f_{\xi_j} - A:\nabla^2_\xi f_{\xi_j} = A_{\xi_j}:\nabla_\xi^2 f + G_{\xi_j}, 
   \end{equation*}
   where $G=f\Delta \rho + f{\bf e}(\theta)\cdot\nabla \rho - (1-\rho)\nabla f \cdot {\bf e}(\theta)$ is such that $D_\xi G \in C^{\beta}([t,T]\times\mathbb{T}^3)$ for some $\beta>0$ (depending on $t,T,c_{t,T}$) by \eqref{eq:Drho is Holder}--\eqref{eq:after one schauder f}; note that the equation holds in the sense of $L^2$ functions. Furthermore, the results \eqref{eq:after one schauder f} and \eqref{eq:Drho is Holder} imply that the entire right-hand side belongs to $C^{\beta}([t,T]\times\mathbb{T}^3)$ for some $\beta>0$ depending on $t,T,c_{t,T}$. In turn, we directly apply the Schauder result of Lemma \ref{lem:Schauder Holder} and deduce that $f_{\xi_j} \in C^{1+\nicefrac{\beta}{2},2+\beta}([t',T']\times\mathbb{T}^3)$ for the same $\beta$ on any $[t',T'] \subset\subset [t,T]$ compactly contained therein, and \eqref{eq:schauder level 2 f} follows. 


    \smallskip 

    \noindent 3. \textit{Conclusion}. We iterate the previous two steps: having shown that $D^m_\xi f$ is H\"older continuous, we apply a further $\partial_{x_j}$ to \eqref{eq:rho eq} to deduce H\"older continuity of $D^{m+1} \rho$, and then returning to \eqref{eq:main eqn} and applying an additional $\partial_{\xi_j}$ we deduce $D^{m+1}_\xi f$ is H\"older continuous. Using the equation to exchange $t$-derivatives for $\xi$-derivatives, we also obtain the H\"older continuity of all time derivatives, and mixed $t,\xi$ derivatives. The proof is complete.

